def badge_target(a):
    """Находит пользователя, канал или группу по @нику / ссылке / -100… / +invite.
    Возвращает (table, id, label) или None."""
    a = (a or "").strip()
    if re.fullmatch(r"-?100\d{5,}", a):
        ch = q1("SELECT * FROM chats WHERE tg_id=? AND type IN ('channel','group')", (a if a.startswith("-") else "-" + a,))
    elif a.startswith("+"):
        ch = q1("SELECT * FROM chats WHERE invite=? AND type IN ('channel','group')", (a,))
    else:
        n = a.lower().lstrip("@")
        u = q1("SELECT id, username FROM users WHERE username=? AND is_bot=0", (n,))
        if u:
            return ("users", u["id"], "@" + u["username"])
        ch = q1("SELECT * FROM chats WHERE link=? AND type IN ('channel','group')", (n,))
    if ch:
        return ("chats", ch["id"], "%s «%s»" % ("📢" if ch["type"] == "channel" else "👥", _html.escape(str(ch["title"] or ch["id"]))))
    return None


