def _personal_channel(u):
    cid = u["personal_channel"] if "personal_channel" in u.keys() else None
    if not cid:
        return None
    c = q1("SELECT * FROM chats WHERE id=? AND type='channel' AND frozen=0", (cid,))
    if not c:
        return None
    last = q1("SELECT text, ts FROM messages WHERE chat_id=? ORDER BY id DESC LIMIT 1", (c["id"],))
    n = _members_count(c["id"])
    title = c["title"] or ""
    return {"id": c["id"], "title": title, "link": c["link"] or "", "is_public": bool(c["is_public"]),
            "subscribers": n, "sub_text": sub_text("channel", n),
            "avatar_data": c["avatar_data"] or None, "avatar_color": c["avatar_color"] or "#65aadd",
            "initials": title[:2].upper(),
            "last_message": (last["text"] if last else "") or "",
            "time": fmt_list_time(last["ts"]) if last else ""}


def is_premium(u):
    try:
        if "premium" not in u.keys() or not u["premium"]:
            return False
        pu = u["premium_until"]
        return (not pu) or pu > int(time.time())
    except Exception:
        return False


def _col(u, name):
    return (u[name] or "") if name in u.keys() else ""


def _user_json_raw(u):
    return {
        "bio": _col(u, "bio"),
        "work_hours": _col(u, "work_hours"),
        "address": _col(u, "address"),
        "personal_channel": _personal_channel(u),
        "id": u["id"],
        "username": u["username"],
        "display_name": u["display_name"],
        "avatar_color": u["avatar_color"],
        "avatar_data": u["avatar_data"] or None,
        "avatar_text": u["avatar_text"] or None,
        "is_bot": bool(u["is_bot"]),
        "verified": bool(u["verified"]) or _gr(u),
        "grib": _gr(u),
        "premium": is_premium(u),
        "premium_until": (u["premium_until"] or 0) if is_premium(u) else 0,
        "verified_org": (u["verified_org"] or "") if "verified_org" in u.keys() else "",
        "badge": _col(u, "badge"),
        "worn_gift": _worn(u),
        "scam": bool(u["scam"]),
        "scam_bio": SCAM_BIO if u["scam"] else None,
        "profile_color": _col(u, "profile_color"),
        "profile_emoji": _col(u, "profile_emoji"),
        "name_color": _col(u, "name_color"),
    }


def get_user(uid):
    try:
        uid = int(uid)
    except (TypeError, ValueError):
        raise ApiError("user_id обязателен")
    u = q1("SELECT * FROM users WHERE id=?", (uid,))
    if not u:
        raise ApiError("Пользователь не найден", 404)
    return u


def get_human(uid):
    u = get_user(uid)
    if u["is_bot"]:
        raise ApiError("Недопустимый пользователь", 403)
    if _fz(u):
        raise ApiError("Аккаунт заморожен", 403)
    return u


def touch(uid):
    try:
        ex("UPDATE users SET last_seen=? WHERE id=?", (now(), int(uid)))
    except Exception:
        pass


def clean_username(s):
    s = (s or "").strip().lstrip("@").lower().replace(" ", "_")
    return re.sub(r"[^\w]", "", s, flags=re.UNICODE)[:32]


def require_member(chat_id, user_id):
    if not q1("SELECT 1 FROM members WHERE chat_id=? AND user_id=?",
              (chat_id, user_id)):
        raise ApiError("Нет доступа к чату", 403)


def ensure_bot():
    b = q1("SELECT * FROM users WHERE is_bot=1 LIMIT 1")
    if b:
        return b
    ex("INSERT INTO users(username,display_name,avatar_color,is_bot,created)"
       " VALUES('vexis_bot','Vexis Bot','#2AABEE',1,?)", (now(),))
    return q1("SELECT * FROM users WHERE is_bot=1 LIMIT 1")


