def device_label(ua):
    ua = ua or ""
    if "Edg/" in ua:
        br = "Edge"
    elif "OPR/" in ua:
        br = "Opera"
    elif "Firefox/" in ua:
        br = "Firefox"
    elif "Chrome/" in ua or "CriOS/" in ua:
        br = "Chrome"
    elif "Safari/" in ua:
        br = "Safari"
    else:
        br = "Vexis Web"
    if "Android" in ua:
        os_ = "Android"
    elif "iPhone" in ua or "iPad" in ua:
        os_ = "iOS"
    elif "Windows" in ua:
        os_ = "Windows"
    elif "Mac OS" in ua:
        os_ = "macOS"
    elif "Linux" in ua:
        os_ = "Linux"
    else:
        os_ = ""
    return br + (" · " + os_ if os_ else "")


def create_session(user_id, label=None):
    token = secrets.token_urlsafe(24)
    ip = getattr(_req_ctx, "ip", "") or ""
    ua = getattr(_req_ctx, "ua", "") or ""
    dev = label or device_label(ua)
    ex("INSERT INTO sessions(user_id,token,device,ip,created,last_seen) VALUES(?,?,?,?,?,?)",
       (user_id, token, dev, ip, now(), now()))
    return token


def ensure_service_chat(uid):
    r = q1("""SELECT c.id FROM chats c JOIN members m ON m.chat_id=c.id
              WHERE c.type='service' AND m.user_id=?""", (uid,))
    if r:
        return r["id"]
    cid = new_chat("service", [uid, SERVICE["id"]])
    add_message(cid, SERVICE["id"],
                "Это служебный чат Vexis. Здесь появляются коды для входа и уведомления о новых входах в аккаунт.")
    return cid


def notify_service(uid, text):
    cid = ensure_service_chat(uid)
    add_message(cid, SERVICE["id"], text)
    return cid


def add_message(chat_id, sender_id, text, ts=None, reply_to=None, fwd_from=None):
    cur = ex("INSERT INTO messages(chat_id,sender_id,text,ts,reply_to,fwd_from) VALUES(?,?,?,?,?,?)",
             (chat_id, sender_id, text, ts or now(), reply_to, fwd_from))
    return cur.lastrowid


def new_chat(ctype, user_ids):
    cur = ex("INSERT INTO chats(type,created) VALUES(?,?)", (ctype, now()))
    cid = cur.lastrowid
    for uid in user_ids:
        ex("INSERT OR IGNORE INTO members(chat_id,user_id) VALUES(?,?)", (cid, uid))
    return cid


# ───────────────────────── API handlers ─────────────────────────
def api_login(body, _qs):
    if os.environ.get("ALLOW_NICK_LOGIN") != "1":
        raise ApiError("Вход по нику отключён — войдите по номеру телефона", 403)
    raw = (body.get("username") or "").strip()
    uname = clean_username(raw)
    if len(uname) < 2:
        raise ApiError("Минимум 2 символа")
    u = q1("SELECT * FROM users WHERE username=?", (uname,))
    if u and u["is_bot"]:
        raise ApiError("Этот ник занят")
    if not u:
        ex("INSERT INTO users(username,display_name,avatar_color,last_seen,created)"
           " VALUES(?,?,?,?,?)",
           (uname, raw.lstrip("@")[:40] or uname, random.choice(COLORS), now(), now()))
        u = q1("SELECT * FROM users WHERE username=?", (uname,))
    touch(u["id"])
    return user_json(u)


def api_chats(_body, qs):
    me = get_human(qs.get("user_id"))
    touch(me["id"])
    rows = q("""
        SELECT c.id, c.type, c.created, m.last_read,
               (SELECT id FROM messages WHERE chat_id=c.id ORDER BY id DESC LIMIT 1) AS last_id
        FROM chats c JOIN members m ON m.chat_id=c.id
        WHERE m.user_id=? AND c.type NOT IN ('channel','group')""", (me["id"],))
    out = []
    for r in rows:
        if not r["last_id"]:
            continue
        last = q1("SELECT * FROM messages WHERE id=?", (r["last_id"],))
        unread = q1("SELECT COUNT(*) n FROM messages WHERE chat_id=? AND id>? AND sender_id!=?",
                    (r["id"], r["last_read"], me["id"]))["n"]
        item = {
            "id": r["id"], "type": r["type"],
            "last_message": ("Вы: " if last["sender_id"] == me["id"] else "") + last["text"],
            "time": fmt_list_time(last["ts"]), "_ts": last["ts"],
            "unread": unread, "muted": False, "verified": False, "grib": False, "badge": "", "worn_gift": None, "scam": False, "frozen": False,
            "online": False, "is_bot": False,
        }
        if r["type"] == "saved":
            item.update(title="Избранное", initials="★", avatar_color="#3390ec",
                        is_saved=True, verified=True)
        else:
            other = q1("""SELECT u.* FROM members m JOIN users u ON u.id=m.user_id
                          WHERE m.chat_id=? AND m.user_id!=?""", (r["id"], me["id"]))
            if not other:
                continue
            name = other["display_name"] or other["username"]
            item.update(
                title=name, initials=name[:2].upper(),
                avatar_color=other["avatar_color"],
                avatar_data=other["avatar_data"] or None,
                username=other["username"], is_bot=bool(other["is_bot"]),
                verified=bool(other["verified"]) or _gr(other), grib=_gr(other),
                verified_org=other["verified_org"] or "", badge=_col(other, "badge"), worn_gift=_worn(other), scam=bool(other["scam"]),
                premium=is_premium(other),
                profile_color=_col(other, "profile_color"), profile_emoji=_col(other, "profile_emoji"),
                name_color=_col(other, "name_color"),
                online=bool(other["is_bot"]) or (now() - other["last_seen"] < ONLINE_WINDOW),
            )
            if not other["is_bot"]:
                om = q1("SELECT last_read FROM members WHERE chat_id=? AND user_id=?", (r["id"], other["id"]))
                item["read"] = bool(om and om["last_read"] >= last["id"])
                if _typing_others(r["id"], me["id"]):
                    item["typing"] = True
                    item["typing_text"] = "печатает…"
            if _fz(other):
                item.update(title=FROZEN_NAME, initials="УА", avatar_color="#e68844",
                            avatar_data=GHOST_AVATAR, username="", verified=False, grib=False,
                            scam=False, online=False, frozen=True)
        out.append(item)
    return _chats_with_groups(me, out)


def fmt_count(n):
    """Как в Telegram: 999, 1.4K, 12.5K, 2.3M (дробная часть отбрасывается, не округляется)."""
    n = int(n)
    if n < 1000:
        return str(n)
    if n < 1000000:
        w, d, suf = n // 1000, (n % 1000) // 100, "K"
    else:
        w, d, suf = n // 1000000, (n % 1000000) // 100000, "M"
    return "%d%s%s" % (w, ("." + str(d)) if d else "", suf)


def msg_views(chat_id, mid, boost=0):
    real = q1("SELECT COUNT(*) n FROM members WHERE chat_id=? AND last_read>=?", (chat_id, mid))["n"]
    return max(1, real + (boost or 0))


def msg_json(r, chat_id):
    out = {"id": r["id"], "chat_id": chat_id, "sender_id": r["sender_id"],
           "text": r["text"], "time": fmt_hm(r["ts"]), "ts": r["ts"],
           "fwd_from": r["fwd_from"], "edited": bool(r["edited"]),
           "service": bool(r["service"]) if "service" in r.keys() else False}
    _ct = q1("SELECT type FROM chats WHERE id=?", (chat_id,))
    if _ct and _ct["type"] == "channel":
        out["views"] = msg_views(chat_id, r["id"], r["view_boost"] if "view_boost" in r.keys() else 0)
    if _ct and _ct["type"] == "group":
        _su = q1("SELECT * FROM users WHERE id=?", (r["sender_id"],))
        if _su:
            out["sender_name"] = _su["display_name"] or _su["username"]
            out["sender_color"] = (_col(_su, "name_color").split(",")[0]) or _su["avatar_color"]
    if r["reply_to"]:
        o = q1("""SELECT m.id, m.text, u.display_name, u.username FROM messages m
                  JOIN users u ON u.id=m.sender_id WHERE m.id=? AND m.chat_id=?""",
               (r["reply_to"], chat_id))
        if o:
            out["reply"] = {"id": o["id"], "name": o["display_name"] or o["username"],
                            "text": o["text"][:200]}
        else:
            out["reply"] = {"id": r["reply_to"], "name": "", "gone": True,
                            "text": "Сообщение удалено"}
    return out


def api_messages(_body, qs):
    try:
        chat_id = int(qs.get("chat_id"))
        after = int(qs.get("after") or 0)
    except (TypeError, ValueError):
        raise ApiError("chat_id обязателен")
    uid = qs.get("user_id")
    if uid:  # необязательная проверка доступа
        require_member(chat_id, int(uid))
        touch(uid)
    rows = q("SELECT * FROM messages WHERE chat_id=? AND id>? ORDER BY id LIMIT 500",
             (chat_id, after))
    return [msg_json(r, chat_id) for r in rows]


def bot_reply(text):
    t = text.strip().lower()
    if t.startswith("/start"):
        return "Привет! Я Vexis Bot 🤖\nНапиши /help, чтобы узнать, что я умею."
    if t.startswith("/help"):
        return "/start — приветствие\n/time — текущее время\n/ping — проверка связи\nИли просто напиши что-нибудь."
    if t.startswith("/time"):
        return "Сейчас " + datetime.now(TZ).strftime("%H:%M:%S, %d.%m.%Y")
    if t.startswith("/ping"):
        return "pong 🏓"
    return "Ты написал: " + text[:200]


def api_send(body, _qs):
    me = get_human(body.get("user_id"))
    try:
        chat_id = int(body.get("chat_id"))
    except (TypeError, ValueError):
        raise ApiError("chat_id обязателен")
    text = (body.get("text") or "").strip()
    if not text:
        raise ApiError("Пустое сообщение")
    if len(text) > 4000:
        raise ApiError("Слишком длинное сообщение (максимум 4000)")
    require_member(chat_id, me["id"])
    _ct = q1("SELECT type, frozen FROM chats WHERE id=?", (chat_id,))
    if _ct and _ct["frozen"]:
        raise ApiError("Чат заморожен", 403)
    if _ct and _ct["type"] == "channel" and not is_chat_admin(chat_id, me["id"]):
        raise ApiError("Публиковать могут только администраторы", 403)
    touch(me["id"])
    TYPING.pop((chat_id, me["id"]), None)
    reply_to = None
    try:
        rt = int(body.get("reply_to") or 0)
        if rt and q1("SELECT 1 FROM messages WHERE id=? AND chat_id=?", (rt, chat_id)):
            reply_to = rt
    except (TypeError, ValueError):
        pass
    fwd_from = (body.get("fwd_from") or "").strip()[:60] or None
    mid = add_message(chat_id, me["id"], text, None, reply_to, fwd_from)
    chat = q1("SELECT type FROM chats WHERE id=?", (chat_id,))
    if chat and chat["type"] == "bot":
        add_message(chat_id, BOT["id"], bot_reply(text), now())
    return {"id": mid, "ok": True}


TYPING = {}          # (chat_id, user_id) -> время последнего «печатает»
TYPING_TTL = 6       # секунд


def _typing_others(chat_id, me_id):
    t = now()
    for k in [k for k, v in TYPING.items() if t - v > TYPING_TTL]:
        TYPING.pop(k, None)
    return [uid for (cid, uid) in TYPING if cid == chat_id and uid != me_id]


def api_typing(body, _qs):
    me = get_human(body.get("user_id"))
    try:
        chat_id = int(body.get("chat_id"))
    except (TypeError, ValueError):
        raise ApiError("chat_id обязателен")
    require_member(chat_id, me["id"])
    TYPING[(chat_id, me["id"])] = now()
    touch(me["id"])
    return {"ok": True}


def api_read(body, _qs):
    me = get_human(body.get("user_id"))
    chat_id = int(body.get("chat_id") or 0)
    require_member(chat_id, me["id"])
    ex("""UPDATE members SET last_read=COALESCE(
            (SELECT MAX(id) FROM messages WHERE chat_id=?),0)
          WHERE chat_id=? AND user_id=?""", (chat_id, chat_id, me["id"]))
    return {"ok": True}


def api_saved(_body, qs):
    me = get_human(qs.get("user_id"))
    r = q1("""SELECT c.id FROM chats c JOIN members m ON m.chat_id=c.id
              WHERE c.type='saved' AND m.user_id=?""", (me["id"],))
    cid = r["id"] if r else new_chat("saved", [me["id"]])
    return {"id": cid, "title": "Избранное"}


def api_service(_body, qs):
    me = get_human(qs.get("user_id"))
    cid = ensure_service_chat(me["id"])
    return {"id": cid, "title": "Vexis", "verified": True, "avatar_data": SERVICE["avatar_data"], "avatar_color": SERVICE["avatar_color"]}


def api_sessions(_body, qs):
    me = get_human(qs.get("user_id"))
    tok = qs.get("token") or ""
    rows = q("SELECT * FROM sessions WHERE user_id=? AND revoked=0 ORDER BY last_seen DESC", (me["id"],))
    t = now()
    return [{"id": r["id"], "device": r["device"], "ip": r["ip"] or "",
              "created": r["created"], "last_seen": r["last_seen"], "now": t,
              "online": t - r["last_seen"] < ONLINE_WINDOW,
              "current": bool(tok) and r["token"] == tok} for r in rows]


def api_session_ensure(body, _qs):
    """Старые входы без токена получают сеанс, чтобы текущее устройство было в списке."""
    me = get_human(body.get("user_id"))
    tok = (body.get("token") or "").strip()
    if tok:
        r = q1("SELECT revoked, user_id FROM sessions WHERE token=?", (tok,))
        if r and r["user_id"] == me["id"]:
            return {"ok": True, "revoked": bool(r["revoked"]), "token": tok}
    return {"ok": True, "revoked": False, "token": create_session(me["id"])}


def api_session_revoke(body, _qs):
    me = get_human(body.get("user_id"))
    if body.get("self_token"):
        ex("UPDATE sessions SET revoked=1 WHERE user_id=? AND token=?", (me["id"], body["self_token"]))
        return {"ok": True}
    if body.get("all_others"):
        ex("UPDATE sessions SET revoked=1 WHERE user_id=? AND token!=?", (me["id"], (body.get("token") or "")))
        return {"ok": True}
    try:
        sid = int(body.get("session_id"))
    except (TypeError, ValueError):
        raise ApiError("session_id обязателен")
    r = q1("SELECT user_id FROM sessions WHERE id=?", (sid,))
    if not r or r["user_id"] != me["id"]:
        raise ApiError("Сессия не найдена", 404)
    ex("UPDATE sessions SET revoked=1 WHERE id=?", (sid,))
    return {"ok": True}


def api_session_ping(body, _qs):
    tok = (body.get("token") or "").strip()
    if not tok:
        return {"ok": True}
    r = q1("SELECT revoked FROM sessions WHERE token=?", (tok,))
    if not r or r["revoked"]:
        return {"ok": True, "revoked": True}
    ex("UPDATE sessions SET last_seen=? WHERE token=?", (now(), tok))
    return {"ok": True, "revoked": False}


def api_bot(_body, qs):
    me = get_human(qs.get("user_id"))
    r = q1("""SELECT c.id FROM chats c JOIN members m ON m.chat_id=c.id
              WHERE c.type='bot' AND m.user_id=?""", (me["id"],))
    if r:
        cid = r["id"]
    else:
        cid = new_chat("bot", [me["id"], BOT["id"]])
        add_message(cid, BOT["id"], "Привет! Я Vexis Bot 🤖\nНапиши /help.")
    return {"id": cid, "title": BOT["display_name"], "avatar_color": BOT["avatar_color"]}


def api_search(_body, qs):
    me = get_human(qs.get("user_id"))
    needle = (qs.get("q") or "").strip().lstrip("@")
    if not needle:
        return []
    like = "%" + needle.replace("%", "").replace("_", r"\_") + "%"
    rows = q("""SELECT * FROM users
                WHERE id!=? AND is_bot=0 AND frozen=0
                  AND (username LIKE ? ESCAPE '\\' OR alt_username LIKE ? ESCAPE '\\' OR display_name LIKE ? ESCAPE '\\')
                ORDER BY display_name COLLATE NOCASE LIMIT 50""",
             (me["id"], like, like, like))
    return [user_json(r) for r in rows]


def api_private(body, _qs):
    me = get_human(body.get("user_id"))
    other = get_user(body.get("other_id"))
    if me["id"] == other["id"]:
        return api_saved({}, {"user_id": me["id"]})
    r = q1("""SELECT c.id FROM chats c
              JOIN members a ON a.chat_id=c.id AND a.user_id=?
              JOIN members b ON b.chat_id=c.id AND b.user_id=?
              WHERE c.type='private'""", (me["id"], other["id"]))
    cid = r["id"] if r else new_chat("private", [me["id"], other["id"]])
    return {"id": cid}


def api_me(_body, qs):
    u = get_user(qs.get("user_id"))
    if u["is_bot"]:
        raise ApiError("Недопустимый пользователь", 403)
    return user_json_own(u)


def ascii_username(raw):
    return re.sub(r"[^a-z0-9_]", "", (raw or "").strip().lstrip("@").lower())[:32]


def username_problem(me, uname):
    """None если имя можно занять, иначе текст ошибки."""
    if uname == me["username"]:
        return None
    if uname and uname == (me["alt_username"] or ""):
        return None
    nft = q1("SELECT owner_id FROM nft_usernames WHERE username=? AND owner_id IS NOT NULL", (uname,))
    if nft:   # коллекционное имя: свободно только для владельца (и ему можно любую длину)
        return None if nft["owner_id"] == me["id"] else "Это имя пользователя уже занято."
    if len(uname) < 5:
        return "Имя пользователя должно содержать не меньше 5 символов."
    if q1("SELECT id FROM users WHERE username=? AND id!=?", (uname, me["id"])):
        return "Это имя пользователя уже занято."
    if q1("SELECT id FROM users WHERE alt_username=? AND id!=?", (uname, me["id"])):
        return "Это имя пользователя уже занято."
    return None


def api_username_check(_body, qs):
    me = get_human(qs.get("user_id"))
    uname = ascii_username(qs.get("q"))
    err = username_problem(me, uname)
    return {"ok": err is None, "error": err, "username": uname}


COLOR_PAIR_RE = re.compile(r"#[0-9a-fA-F]{6}(,#[0-9a-fA-F]{6})?")
PROFILE_ICONS = ("anchor", "star", "heart", "bolt", "moon", "flame", "crown", "gem", "snow",
                 "paw", "flower", "note", "skull", "smile", "gift", "rocket")


def _visible_phone(viewer, u):
    """Номер телефона — только если владелец разрешил («Все» / «Мои контакты»)."""
    if not u["phone"]:
        return ""
    if viewer["id"] == u["id"]:
        return u["phone"]
    mode = _col(u, "phone_priv") or "nobody"
    if mode == "all":
        return u["phone"]
    if mode == "contacts":
        has = q1("""SELECT 1 FROM members a JOIN members b ON a.chat_id=b.chat_id
                    JOIN chats c ON c.id=a.chat_id
                    WHERE c.type='private' AND a.user_id=? AND b.user_id=?""", (viewer["id"], u["id"]))
        return u["phone"] if has else ""
    return ""


def api_user_look(_body, qs):
    """Оформление чужого профиля (цвет шапки, фоновая иконка, цвет имени) — видно всем."""
    viewer = get_human(qs.get("user_id"))
    u = None
    if qs.get("username"):
        u = q1("SELECT * FROM users WHERE username=? AND frozen=0", (clean_username(qs.get("username")),))
    elif qs.get("id"):
        try:
            u = q1("SELECT * FROM users WHERE id=? AND frozen=0", (int(qs.get("id")),))
        except (TypeError, ValueError):
            u = None
    if not u:
        return {"profile_color": "", "profile_emoji": "", "name_color": "", "phone": ""}
    return {"profile_color": _col(u, "profile_color"), "profile_emoji": _col(u, "profile_emoji"),
            "name_color": _col(u, "name_color"), "phone": _visible_phone(viewer, u), "worn_gift": _worn(u)}


def api_profile(body, _qs):
    me = get_human(body.get("user_id"))
    sets, args = [], []
    if "display_name" in body:
        name = (body["display_name"] or "").strip()[:64]
        if not name:
            raise ApiError("Имя не может быть пустым")
        sets.append("display_name=?"); args.append(name)
    if "username" in body:
        uname = ascii_username(body["username"])
        err = username_problem(me, uname)
        if err:
            raise ApiError(err)
        if uname != me["username"]:
            sets.append("username=?"); args.append(uname)
            owned_n = {r["username"].lower() for r in q("SELECT username FROM nft_usernames WHERE owner_id=?", (me["id"],))}
            alt = me["alt_username"]
            if uname in owned_n:
                if me["username"].lower() not in owned_n:
                    alt = me["username"]          # обычное имя не пропадает, а уходит в «также»
            else:
                alt = None                        # вручную задали новое обычное имя
            sets.append("alt_username=?"); args.append(alt)
    if "avatar_color" in body and body["avatar_color"]:
        sets.append("avatar_color=?"); args.append(str(body["avatar_color"])[:16])
    if "avatar_text" in body:
        sets.append("avatar_text=?"); args.append(str(body["avatar_text"] or "")[:8])
    if "avatar_data" in body:
        data = body["avatar_data"] or None
        if data and (not str(data).startswith("data:image/") or len(data) > 4_000_000):
            raise ApiError("Некорректное фото")
        sets.append("avatar_data=?"); args.append(data)
    if "bio" in body:
        sets.append("bio=?"); args.append(" ".join(str(body["bio"] or "").split())[:140])
    if "birthday" in body:
        bd = str(body["birthday"] or "").strip()
        if bd:
            m = re.match(r"^(\d{2})\.(\d{2})(?:\.(\d{4}))?$", bd)
            try:
                datetime(int(m.group(3) or 2000), int(m.group(2)), int(m.group(1)))
            except (AttributeError, ValueError):
                raise ApiError("Некорректная дата рождения")
        sets.append("birthday=?"); args.append(bd or None)
    if "work_hours" in body:
        raw = body["work_hours"]
        if raw:
            try:
                w = json.loads(raw) if isinstance(raw, str) else raw
                ok = isinstance(w, dict) and isinstance(w.get("days"), list) and len(w["days"]) == 7
                for d in (w["days"] if ok else []):
                    if d is not None and not (isinstance(d, list) and len(d) == 2
                                              and all(isinstance(x, int) and 0 <= x <= 1440 for x in d) and d[0] < d[1]):
                        ok = False
            except (ValueError, TypeError):
                ok = False
            if not ok:
                raise ApiError("Некорректные часы работы")
            raw = json.dumps({"on": bool(w.get("on")), "days": w["days"]})
        sets.append("work_hours=?"); args.append(raw or None)
    if "address" in body:
        sets.append("address=?"); args.append(" ".join(str(body["address"] or "").split())[:200] or None)
    if "phone_priv" in body:
        _pp = str(body.get("phone_priv") or "nobody")
        if _pp not in ("all", "contacts", "nobody"):
            raise ApiError("Неверная настройка")
        sets.append("phone_priv=?"); args.append(_pp)
    for _k in ("profile_color", "name_color"):
        if _k in body:
            _v = (body.get(_k) or "").strip()
            if _v and not COLOR_PAIR_RE.fullmatch(_v):
                raise ApiError("Неверный цвет")
            sets.append(_k + "=?"); args.append(_v or None)
    if "profile_emoji" in body:
        _v = (body.get("profile_emoji") or "").strip()
        if _v and _v not in PROFILE_ICONS:
            raise ApiError("Неверная иконка")
        sets.append("profile_emoji=?"); args.append(_v or None)
    if "personal_channel" in body:
        cid = body["personal_channel"]
        if cid:
            c = q1("SELECT id FROM chats WHERE id=? AND type='channel' AND owner_id=? AND frozen=0", (cid, me["id"]))
            if not c:
                raise ApiError("Закрепить можно только свой канал")
            cid = c["id"]
        sets.append("personal_channel=?"); args.append(cid or None)
    if sets:
        ex("UPDATE users SET " + ",".join(sets) + " WHERE id=?", (*args, me["id"]))
    return user_json_own(get_user(me["id"]))


def _chat_and_user(body_or_qs):
    me = get_human(body_or_qs.get("user_id"))
    try:
        chat_id = int(body_or_qs.get("chat_id"))
    except (TypeError, ValueError):
        raise ApiError("chat_id обязателен")
    require_member(chat_id, me["id"])
    return me, chat_id


def api_chat_state(_body, qs):
    """Что могло измениться у уже загруженных сообщений: удаления, закреп, реакции."""
    me, chat_id = _chat_and_user(qs)
    touch(me["id"])
    ids = [r["id"] for r in q("SELECT id FROM messages WHERE chat_id=? ORDER BY id", (chat_id,))]
    c = q1("SELECT pinned FROM chats WHERE id=?", (chat_id,))
    pinned = None
    if c and c["pinned"]:
        p = q1("SELECT id, text FROM messages WHERE id=? AND chat_id=?", (c["pinned"], chat_id))
        if p:
            pinned = {"id": p["id"], "text": p["text"][:200]}
    rx = {}
    for r in q("""SELECT r.message_id, r.emoji, r.user_id FROM reactions r
                  JOIN messages m ON m.id=r.message_id WHERE m.chat_id=? ORDER BY r.rowid""",
               (chat_id,)):
        d = rx.setdefault(str(r["message_id"]), {})
        e = d.setdefault(r["emoji"], {"e": r["emoji"], "n": 0, "mine": False})
        e["n"] += 1
        e["mine"] = e["mine"] or r["user_id"] == me["id"]
    for r in q("""SELECT b.message_id, b.emoji, b.n FROM reaction_boost b
                  JOIN messages m ON m.id=b.message_id WHERE m.chat_id=? AND b.n>0""", (chat_id,)):
        d = rx.setdefault(str(r["message_id"]), {})
        e = d.setdefault(r["emoji"], {"e": r["emoji"], "n": 0, "mine": False})
        e["n"] += r["n"]
    views = {}
    if c and q1("SELECT type FROM chats WHERE id=?", (chat_id,))["type"] == "channel":
        for r in q("SELECT id, view_boost FROM messages WHERE chat_id=?", (chat_id,)):
            views[str(r["id"])] = msg_views(chat_id, r["id"], r["view_boost"])
    extra = {"read_upto": 0, "my_read": 0, "typing": False, "peer": None}
    _ctr = q1("SELECT type FROM chats WHERE id=?", (chat_id,))
    _mm = q1("SELECT last_read FROM members WHERE chat_id=? AND user_id=?", (chat_id, me["id"]))
    extra["my_read"] = (_mm["last_read"] if _mm else 0) or 0
    _others = q("SELECT user_id, last_read FROM members WHERE chat_id=? AND user_id!=?", (chat_id, me["id"]))
    if _ctr and _ctr["type"] in ("private", "group") and _others:
        extra["read_upto"] = min((o["last_read"] or 0) for o in _others)
    if _ctr and _ctr["type"] == "private" and _others:
        _ou = q1("SELECT * FROM users WHERE id=?", (_others[0]["user_id"],))
        if _ou and not _ou["is_bot"] and not _fz(_ou):
            extra["peer"] = {"online": now() - (_ou["last_seen"] or 0) < ONLINE_WINDOW}
            extra["typing"] = bool(_typing_others(chat_id, me["id"]))
    return {"ids": ids, "pinned": pinned, "views": views, **extra,
            "reactions": {k: list(v.values()) for k, v in rx.items()},
            "edited": {str(r["id"]): r["text"] for r in q("SELECT id, text FROM messages WHERE chat_id=? AND edited IS NOT NULL", (chat_id,))}}


def api_delete(body, _qs):
    me, chat_id = _chat_and_user(body)
    ctype = q1("SELECT type FROM chats WHERE id=?", (chat_id,))["type"]
    n = 0
    for mid in (body.get("ids") or [])[:200]:
        try:
            mid = int(mid)
        except (TypeError, ValueError):
            continue
        m = q1("SELECT sender_id FROM messages WHERE id=? AND chat_id=?", (mid, chat_id))
        if not m:
            continue
        # в личном чате можно удалить для всех только свои; в Избранном/боте — любые
        if m["sender_id"] == me["id"] or ctype in ("saved", "bot") or (ctype in ("channel", "group") and is_chat_admin(chat_id, me["id"])):
            ex("DELETE FROM messages WHERE id=?", (mid,))
            n += 1
    ex("""UPDATE chats SET pinned=NULL WHERE id=?
          AND pinned NOT IN (SELECT id FROM messages WHERE chat_id=?)""", (chat_id, chat_id))
    return {"ok": True, "deleted": n}



def api_chat_msg_search(_body, qs):
    """Поиск сообщений внутри чата (без учёта регистра, в т.ч. кириллица)."""
    me, chat_id = _chat_and_user(qs)
    needle = (qs.get("q") or "").strip().casefold()
    if not needle:
        raise ApiError("Пустой запрос")
    res = []
    for r in q("SELECT id, sender_id, text, ts FROM messages WHERE chat_id=? ORDER BY id DESC LIMIT 5000", (chat_id,)):
        if needle in (r["text"] or "").casefold():
            res.append({"id": r["id"], "sender_id": r["sender_id"], "text": r["text"][:200],
                        "time": fmt_hm(r["ts"]), "ts": r["ts"]})
            if len(res) >= 100:
                break
    return {"results": res, "count": len(res)}


AUTO_TTL = {"off": 0, "1d": 86400, "1w": 7 * 86400, "1m": 30 * 86400}


def api_auto_delete(body, _qs):
    """Автоудаление: сообщения в личных чатах и Избранном старше срока удаляются."""
    me = get_human(body.get("user_id"))
    val = str(body.get("value") or "off")
    if val not in AUTO_TTL:
        raise ApiError("Неверное значение")
    ex("UPDATE users SET auto_ttl=? WHERE id=?", (AUTO_TTL[val], me["id"]))
    return {"ok": True, "value": val}


def auto_delete_sweep():
    for u in q("SELECT id, auto_ttl FROM users WHERE auto_ttl>0"):
        limit = now() - u["auto_ttl"]
        ex("""DELETE FROM messages WHERE ts<? AND COALESCE(service,0)=0 AND chat_id IN
              (SELECT c.id FROM chats c JOIN members m ON m.chat_id=c.id
               WHERE m.user_id=? AND c.type IN ('private','saved'))""", (limit, u["id"]))
    ex("""UPDATE chats SET pinned=NULL WHERE pinned IS NOT NULL
          AND pinned NOT IN (SELECT id FROM messages)""")


def _auto_delete_loop():
    while True:
        time.sleep(60)
        try:
            auto_delete_sweep()
        except Exception:
            traceback.print_exc()


def api_edit(body, _qs):
    me, chat_id = _chat_and_user(body)
    try:
        mid = int(body.get("message_id"))
    except (TypeError, ValueError):
        raise ApiError("message_id обязателен")
    text = (body.get("text") or "").strip()
    if not text:
        raise ApiError("Пустое сообщение")
    if len(text) > 4000:
        raise ApiError("Слишком длинное сообщение (максимум 4000)")
    m = q1("SELECT sender_id FROM messages WHERE id=? AND chat_id=?", (mid, chat_id))
    if not m:
        raise ApiError("Сообщение не найдено", 404)
    if m["sender_id"] != me["id"]:
        raise ApiError("Можно изменять только свои сообщения", 403)
    ex("UPDATE messages SET text=?, edited=? WHERE id=? AND text!=?", (text, now(), mid, text))
    return {"ok": True}


def api_pin(body, _qs):
    me, chat_id = _chat_and_user(body)
    try:
        mid = int(body.get("message_id") or 0)
    except (TypeError, ValueError):
        mid = 0
    if mid and not q1("SELECT 1 FROM messages WHERE id=? AND chat_id=?", (mid, chat_id)):
        raise ApiError("Сообщение не найдено", 404)
    ex("UPDATE chats SET pinned=? WHERE id=?", (mid or None, chat_id))
    return {"ok": True}


def api_react(body, _qs):
    me = get_human(body.get("user_id"))
    try:
        mid = int(body.get("message_id"))
    except (TypeError, ValueError):
        raise ApiError("message_id обязателен")
    m = q1("SELECT chat_id FROM messages WHERE id=?", (mid,))
    if not m:
        raise ApiError("Сообщение не найдено", 404)
    require_member(m["chat_id"], me["id"])
    emoji = (body.get("emoji") or "").strip()[:16]
    cur = q1("SELECT emoji FROM reactions WHERE message_id=? AND user_id=?", (mid, me["id"]))
    if not emoji or (cur and cur["emoji"] == emoji):
        ex("DELETE FROM reactions WHERE message_id=? AND user_id=?", (mid, me["id"]))
    else:
        ex("INSERT OR REPLACE INTO reactions(message_id,user_id,emoji) VALUES(?,?,?)",
           (mid, me["id"], emoji))
    return {"ok": True}


