def norm_phone(s):
    d = re.sub(r"\D", "", s or "")
    if (s or "").strip().startswith("+888") and 6 <= len(d) <= 11:
        return "+" + d   # анонимный номер: +888 и 3–8 цифр
    if len(d) == 11 and d[0] == "8" and not d.startswith("888"):
        d = "7" + d[1:]
    if len(d) == 10:
        d = "7" + d
    if len(d) < 8 or len(d) > 15:
        return None
    return "+" + d


def is_ru(phone):
    return phone.startswith("+7") and len(phone) == 12


def pretty_phone(p):
    if is_anon(p):
        return "+888 " + " ".join(p[4:][i:i + 4] for i in range(0, len(p) - 4, 4))
    if is_ru(p):
        return "+7 (%s) %s-%s-%s" % (p[2:5], p[5:8], p[8:10], p[10:12])
    return p


def tg(method, params=None, timeout=35):
    req = urllib.request.Request(
        "https://api.telegram.org/bot%s/%s" % (BOT_TOKEN, method),
        data=json.dumps(params or {}).encode("utf-8"),
        headers={"Content-Type": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return json.loads(r.read().decode("utf-8"))
    except urllib.error.HTTPError as e:
        try:
            return json.loads(e.read().decode("utf-8"))
        except Exception:
            return {"ok": False, "description": str(e)}
    except Exception as e:
        return {"ok": False, "description": str(e)}


def bot_send(chat_id, text, kb=None):
    p = {"chat_id": chat_id, "text": text, "parse_mode": "HTML"}
    if kb is not None:
        p["reply_markup"] = kb
    return tg("sendMessage", p)


