MONTHS_SHORT = ["янв.", "февр.", "мар.", "апр.", "мая", "июн.", "июл.", "авг.", "сент.", "окт.", "нояб.", "дек."]



_MM_IDX = {"t": 0.0, "map": {}}


def _mm_norm(name):
    """Имя файла без расширения, регистра, пробелов, _ и - : 'Soft Bloom', soft_bloom, SOFT-BLOOM -> softbloom."""
    return re.sub(r"[^0-9a-zа-яё]", "", os.path.splitext(name)[0].lower())


def _mm_find_file(name):
    """Ищет картинку маски по имени среди всех файлов внутри gifts/ (любая вложенность, любой регистр, .png/.webp/.jpg...)."""
    key = _mm_norm(name)
    for attempt in (0, 1):
        if attempt == 1 or not _MM_IDX["map"]:
            if time.time() - _MM_IDX["t"] < 3 and _MM_IDX["map"]:
                break
            idx = {}
            for dp, _dn, fns in os.walk(GIFT_DIR):
                for fn in fns:
                    if os.path.splitext(fn)[1].lower() in GIFT_MIME:
                        k = _mm_norm(fn)
                        full = os.path.join(dp, fn)
                        if k not in idx or "mythmask" in dp.lower():
                            idx[k] = full
            _MM_IDX["map"], _MM_IDX["t"] = idx, time.time()
        fp = _MM_IDX["map"].get(key)
        if fp and os.path.isfile(fp):
            return fp
    return None


def _mm_placeholder(name):
    """Если файла маски нет — вместо битой картинки рисуем плашку с названием нужного файла."""
