class NftError(Exception):
    pass


def fmt_nft_date(ts):
    """29 окт., 06:38  (если год не текущий: 29 окт. 2025, 06:38)"""
    d = datetime.fromtimestamp(ts or 0, TZ)
    year = "" if d.year == datetime.now(TZ).year else " %d" % d.year
    return "%d %s%s, %s" % (d.day, MONTHS_SHORT[d.month - 1], year, d.strftime("%H:%M"))


def fmt_nft_price(ton, xtr):
    """0 (XTR 14)"""
    t = ("%g" % (ton or 0))
    return t + (" (XTR %d)" % xtr if xtr else "")


def nft_json(r):
    owner = None
    if r["owner_id"]:
        u = q1("SELECT * FROM users WHERE id=?", (r["owner_id"],))
        if u:
            owner = {"id": u["id"], "username": u["username"], "display_name": u["display_name"],
                     "avatar_color": u["avatar_color"], "avatar_data": u["avatar_data"] or None,
                     "avatar_text": u["avatar_text"] or None, "verified": bool(u["verified"])}
    return {
        "nft": True, "username": r["username"], "link": "%s/%s" % (PUBLIC_URL, r["username"]),
        "price_ton": r["price_ton"], "price_xtr": r["price_xtr"],
        "price_text": fmt_nft_price(r["price_ton"], r["price_xtr"]),
        "how": r["how"], "acquired": r["acquired"], "acquired_text": fmt_nft_date(r["acquired"]),
        "owner": owner,
    }


def api_nft_username(_body, qs):
    uname = ascii_username(qs.get("username"))
    r = q1("SELECT * FROM nft_usernames WHERE username=? AND owner_id IS NOT NULL", (uname,)) if uname else None
    return nft_json(r) if r else {"nft": False}


def api_usernames(_body, qs):
    """Основное имя + остальные имена пользователя по порядку (для «а также @…» и экрана порядка)."""
    if qs.get("user_id"):
        u = get_human(qs.get("user_id"))
    else:
        uname = ascii_username(qs.get("username"))
        u = q1("SELECT * FROM users WHERE (username=? OR alt_username=?) AND is_bot=0", (uname, uname)) if uname else None
    if not u:
        return {"main": None, "main_nft": False, "extra": []}
    rows = q("SELECT username FROM nft_usernames WHERE owner_id=? ORDER BY pos, created", (u["id"],))
    names = [r["username"] for r in rows]
    main = u["username"]
    extra = [{"username": n, "nft": True} for n in names if n != main.lower()]
    alt = u["alt_username"]
    if alt and alt.lower() != main.lower():
        extra.insert(max(0, min(int(u["alt_pos"] or 0), len(extra))), {"username": alt, "nft": False})
    return {"main": main, "main_nft": main.lower() in names, "extra": extra}


def api_nft_order(body, _qs):
    """Новый порядок имён. Имя на самом верху становится основным; прежнее обычное не пропадает, а уходит в «также»."""
    me = get_human(body.get("user_id"))
    order = body.get("order")
    if not isinstance(order, list):
        raise ApiError("order обязателен")
    with _lock:
        me = get_human(me["id"])
        owned = [r["username"] for r in db.execute(
            "SELECT username FROM nft_usernames WHERE owner_id=? ORDER BY pos, created", (me["id"],)).fetchall()]
        cur = (me["username"] or "").lower()
        alt = (me["alt_username"] or "").lower() or None
        valid = []
        for n in owned + [cur] + ([alt] if alt else []):
            if n and n not in valid:
                valid.append(n)
        want = []
        for n in order:
            n = ascii_username(str(n))
            if n in valid and n not in want:
                want.append(n)
        final = want + [n for n in valid if n not in want]
        first = final[0]
        new_alt = alt
        if first != cur:
            if first in owned:
                if cur not in owned:
                    new_alt = cur            # обычное имя -> «также»
            else:                            # наверх вернули обычное имя
                new_alt = None
            db.execute("UPDATE users SET username=? WHERE id=?", (first, me["id"]))
        rest = final[1:]
        alt_pos = rest.index(new_alt) if new_alt in rest else 0
        db.execute("UPDATE users SET alt_username=?, alt_pos=? WHERE id=?", (new_alt, alt_pos, me["id"]))
        for i, n in enumerate([n for n in final if n in owned]):
            db.execute("UPDATE nft_usernames SET pos=? WHERE username=?", (i + 1, n))
        db.commit()
    return user_json(get_user(me["id"]))


def nft_give(name, user, ton=0.0, xtr=0):
    """Выдаёт коллекционное имя пользователю (появляется в профиле под основным: «а также @…»). Цена > 0 — куплено."""
    name = ascii_username(name)
    if not re.fullmatch(r"[a-z0-9_]{3,32}", name):
        raise NftError("Имя: 3–32 символа, латиница, цифры и _")
    if ton < 0 or xtr < 0:
        raise NftError("Цена не может быть отрицательной")
    with _lock:
        r = db.execute("SELECT * FROM nft_usernames WHERE username=?", (name,)).fetchone()
        if r and r["owner_id"]:
            raise NftError("@%s уже принадлежит %s" % (name, "этому пользователю" if r["owner_id"] == user["id"] else "другому пользователю"))
        holder = db.execute("SELECT id FROM users WHERE username=? OR alt_username=?", (name, name)).fetchone()
        if holder and holder["id"] != user["id"]:
            raise NftError("@%s сейчас занято обычным пользователем" % name)
        how = "bought" if (ton > 0 or xtr > 0) else "given"
        pos = db.execute("SELECT COALESCE(MAX(pos),0)+1 FROM nft_usernames WHERE owner_id=?", (user["id"],)).fetchone()[0]
        db.execute("INSERT OR REPLACE INTO nft_usernames(username,owner_id,price_ton,price_xtr,how,acquired,created,pos)"
                   " VALUES(?,?,?,?,?,?,?,?)", (name, user["id"], float(ton), int(xtr), how, now(), now(), pos))
        db.commit()
    return name, how


def nft_revoke(name):
    name = ascii_username(name)
    with _lock:
        r = db.execute("SELECT * FROM nft_usernames WHERE username=?", (name,)).fetchone()
        if not r:
            raise NftError("@%s — не коллекционное имя" % name)
        owner, new = r["owner_id"], None
        db.execute("DELETE FROM nft_usernames WHERE username=?", (name,))
        if owner:
            u = db.execute("SELECT username FROM users WHERE id=?", (owner,)).fetchone()
            if u and u["username"].lower() == name:   # имя было активным — вернём владельцу обычное
                al = db.execute("SELECT alt_username FROM users WHERE id=?", (owner,)).fetchone()
                if al and al["alt_username"]:
                    new = al["alt_username"]
                    db.execute("UPDATE users SET alt_username=NULL WHERE id=?", (owner,))
                while not new:
                    new = "user%d" % random.randint(100000, 99999999)
                    if not db.execute("SELECT 1 FROM users WHERE username=?", (new,)).fetchone():
                        break
                db.execute("UPDATE users SET username=? WHERE id=?", (new, owner))
            elif u:
                db.execute("UPDATE users SET alt_username=NULL, alt_pos=0 WHERE id=? AND lower(alt_username)=?", (owner, name))
        db.commit()
    return owner, new


def nft_tg_id(user_id):
    u = q1("SELECT phone FROM users WHERE id=?", (user_id,))
    r = q1("SELECT tg_id FROM phones WHERE phone=?", (u["phone"],)) if u and u["phone"] else None
    return r["tg_id"] if r else None


def nft_resolve_user(t):
    t = (t or "").strip()
    if not t.startswith("@") and t.isdigit() and len(t) >= 5:   # Telegram ID
        u = q1("SELECT u.* FROM phones p JOIN users u ON u.phone=p.phone WHERE p.tg_id=? AND u.is_bot=0", (int(t),))
        return (u, None) if u else (None, "❌ У Telegram ID %s нет аккаунта Vexis" % t)
    uname = ascii_username(t)
    u = q1("SELECT * FROM users WHERE username=? AND is_bot=0", (uname,)) if uname else None
    return (u, None) if u else (None, "❌ @%s не найден" % uname)


def _num(x, cast=float):
    return cast(str(x).replace(",", "."))


def nft_owner_label(uid):
    u = q1("SELECT username FROM users WHERE id=?", (uid,)) if uid else None
    return ("@" + u["username"]) if u else "—"


def nft_admin(cmd, args):
    U = lambda x: "<code>@%s</code>" % _html.escape(x)
    try:
        if cmd == "/nft_give":
            if len(args) < 2:
                return ("Формат: /nft_give true @user [цена] [XTR]\n"
                        "Без цены — имя «выдано», с ценой — «куплено».\nПример: /nft_give true @vasya 0 14")
            user, err = nft_resolve_user(args[1])
            if err:
                return err
            ton = _num(args[2]) if len(args) > 2 else 0.0
            xtr = _num(args[3], int) if len(args) > 3 else 0
            name, how = nft_give(args[0], user, ton, xtr)
            tid = nft_tg_id(user["id"])
            if tid:
                try:
                    bot_send(tid, ("🛒 Вы приобрели коллекционное имя %s за %s" % (U(name), fmt_nft_price(ton, xtr))) if how == "bought"
                             else "🎁 Вам выдано коллекционное имя %s" % U(name), KB_MAIN)
                except Exception:
                    pass
            return "✅ %s %s @%s%s" % (U(name), "куплен" if how == "bought" else "выдан →", _html.escape(user["username"]),
                                      (" за " + fmt_nft_price(ton, xtr)) if how == "bought" else "")
        if cmd == "/nft_revoke":
            if not args:
                return "Формат: /nft_revoke true"
            owner, new = nft_revoke(args[0])
            return "✅ %s забран у %s%s" % (U(ascii_username(args[0])), _html.escape(nft_owner_label(owner)),
                                           ("\nЕму выдан обычный юзернейм @%s" % new) if new else "")
        if cmd == "/nft_price":
            if len(args) < 2:
                return "Формат: /nft_price true 0 14   (цена, XTR)"
            name = ascii_username(args[0])
            if not q1("SELECT 1 FROM nft_usernames WHERE username=?", (name,)):
                return "❌ %s — не коллекционное имя" % U(name)
            ton = _num(args[1]); xtr = _num(args[2], int) if len(args) > 2 else 0
            ex("UPDATE nft_usernames SET price_ton=?, price_xtr=? WHERE username=?", (ton, xtr, name))
            return "✅ %s: цена %s" % (U(name), fmt_nft_price(ton, xtr))
        if cmd == "/nft_info":
            if not args:
                return "Формат: /nft_info true"
            r = q1("SELECT * FROM nft_usernames WHERE username=?", (ascii_username(args[0]),))
            if not r:
                return "❌ Такого коллекционного имени нет."
            return "%s\nВладелец: %s\n%s: %s\nЦена: %s" % (
                U(r["username"]), _html.escape(nft_owner_label(r["owner_id"])),
                "Куплено" if r["how"] == "bought" else "Выдано", fmt_nft_date(r["acquired"]),
                fmt_nft_price(r["price_ton"], r["price_xtr"]))
        if cmd == "/nft_list":
            total = q1("SELECT COUNT(*) n FROM nft_usernames")["n"]
            rows = q("SELECT * FROM nft_usernames ORDER BY acquired DESC LIMIT 40")
            if not rows:
                return "Коллекционных имён пока нет. Выдать: /nft_give true @user"
            return "Всего: %d\n\n%s%s" % (total, "\n".join("%s — %s · %s · %s" % (
                U(r["username"]), _html.escape(nft_owner_label(r["owner_id"])),
                "куплено" if r["how"] == "bought" else "выдано", fmt_nft_date(r["acquired"])) for r in rows),
                "\n…" if total > 40 else "")
    except NftError as e:
        return "❌ " + _html.escape(str(e))
    except ValueError:
        return "❌ Цена должна быть числом."
    return "?"


