        if not args:
            bot_send(cid, "Использование: <code>%s @username%s</code>" % (cmd, "" if cmd == "/stars_balance" else " 100"), KB_MAIN)
            return
        u, err = nft_resolve_user(args[0])
        if not u:
            bot_send(cid, err, KB_MAIN)
