INVITE_RE = re.compile(r"^\+[A-Za-z0-9_-]{16}$")


def _plural(n, one, few, many):
    n = abs(int(n))
    if n % 10 == 1 and n % 100 != 11:
        return one
    if 2 <= n % 10 <= 4 and not 12 <= n % 100 <= 14:
        return few
    return many


def sub_text(kind, n):
    k = 5 if n >= 1000 else n   # после сокращения (1.4K) — всегда «подписчиков»
    if kind == "channel":
        return "%s %s" % (fmt_count(n), _plural(k, "подписчик", "подписчика", "подписчиков"))
    return "%s %s" % (fmt_count(n), _plural(k, "участник", "участника", "участников"))


def my_role(chat_id, uid):
    r = q1("SELECT role FROM members WHERE chat_id=? AND user_id=?", (chat_id, uid))
    return None if not r else (r["role"] or "member")


def is_chat_admin(chat_id, uid):
    return my_role(chat_id, uid) in ("owner", "admin")


def get_chat_row(chat_id):
    try:
        chat_id = int(chat_id)
    except (TypeError, ValueError):
        raise ApiError("chat_id обязателен")
    c = q1("SELECT * FROM chats WHERE id=? AND type IN ('channel','group')", (chat_id,))
    if not c:
        raise ApiError("Канал не найден", 404)
    return c


def link_problem(link, chat_id=None):
    """None — ссылку можно занять, иначе текст ошибки."""
    if not link:
        return "Введите ссылку."
    if not re.fullmatch(r"[a-z0-9_]+", link):
        return "Недопустимые символы. Можно использовать латиницу (a-z), цифры (0-9) и подчёркивание."
    if len(link) < 5:
        return "Слишком короткая ссылка. Минимальная длина — 5 символов."
    if len(link) > 32:
        return "Слишком длинная ссылка. Максимум — 32 символа."
    if q1("SELECT id FROM chats WHERE link=? AND id IS NOT ?", (link, chat_id)):
        return "Ссылка занята."
    if q1("SELECT id FROM users WHERE username=?", (link,)):
        return "Ссылка занята."
    try:
        if q1("SELECT id FROM users WHERE alt_username=?", (link,)):
            return "Ссылка занята."
        if q1("SELECT 1 FROM nft_usernames WHERE username=?", (link,)):
            return "Ссылка занята."
    except sqlite3.OperationalError:
        pass
    return None


def _norm_link(s):
    return (s or "").strip().lstrip("@").lower()


def _new_tg_id():
    while True:
        v = "-100" + str(random.randint(1000000000, 3999999999))
        if not q1("SELECT 1 FROM chats WHERE tg_id=?", (v,)):
            return v


def _new_invite():
    while True:
        v = "+" + secrets.token_urlsafe(12)[:16]
        if INVITE_RE.match(v) and not q1("SELECT 1 FROM chats WHERE invite=?", (v,)):
            return v


def _members_count(chat_id):
    real = q1("SELECT COUNT(*) n FROM members WHERE chat_id=?", (chat_id,))["n"]
    b = q1("SELECT sub_boost FROM chats WHERE id=?", (chat_id,))
    return max(0, real + ((b["sub_boost"] or 0) if b else 0))


def _clean_photo(s):
    s = (s or "").strip()
    if s.startswith("data:image/") and len(s) < 900000:
        return s
    return None


def chat_url(c):
    tail = c["link"] if c["is_public"] and c["link"] else (c["invite"] or c["link"] or "")
    return LINK_HOST + "/" + tail


def group_chat_item(c, me_id):
    """Строка для списка чатов (канал или группа)."""
    cid = c["id"]
    last = q1("""SELECT m.*, u.display_name AS dn, u.username AS un FROM messages m
                 JOIN users u ON u.id=m.sender_id WHERE m.chat_id=? ORDER BY m.id DESC LIMIT 1""", (cid,))
    mem = q1("SELECT last_read, role FROM members WHERE chat_id=? AND user_id=?", (cid, me_id))
    last_read = mem["last_read"] if mem else 0
    unread = q1("SELECT COUNT(*) n FROM messages WHERE chat_id=? AND id>? AND sender_id!=?",
                (cid, last_read, me_id))["n"]
    text, ts = "", c["created"]
    if last:
        text, ts = last["text"], last["ts"]
        if c["type"] == "group" and not last["service"]:
            who = "Вы" if last["sender_id"] == me_id else ((last["dn"] or last["un"] or "").split(" ")[0])
            text = who + ": " + text
    title = c["title"] or ""
    fz = bool(c["frozen"])
    if fz:
        title = "Удалённый канал" if c["type"] == "channel" else "Удалённая группа"
    n = _members_count(cid)
    return {
        "id": cid, "type": c["type"], "kind": c["type"], "title": title,
        "initials": title[:2].upper(), "avatar_color": "#8e9aa6" if fz else (c["avatar_color"] or "#65aadd"),
        "avatar_data": GHOST_AVATAR if fz else (c["avatar_data"] or None), "username": "" if fz else (c["link"] or ""),
        "last_message": "" if fz else text, "time": fmt_list_time(ts), "_ts": ts, "unread": 0 if fz else unread,
        "muted": False, "verified": False, "badge": "" if fz else _col(c, "badge"), "scam": False, "frozen": fz,
        "online": False, "is_bot": False, "is_public": bool(c["is_public"]),
        "role": (mem["role"] or "member") if mem else None,
        "subscribers": n, "sub_text": sub_text(c["type"], n),
    }


def _chats_with_groups(me, out):
    rows = q("""SELECT c.* FROM chats c JOIN members m ON m.chat_id=c.id
                WHERE m.user_id=? AND c.type IN ('channel','group')""", (me["id"],))
    for c in rows:
        out.append(group_chat_item(c, me["id"]))
    out.sort(key=lambda x: x["_ts"], reverse=True)
    for i in out:
        i.pop("_ts", None)
    return out


def chat_info(c, me_id):
    cid = c["id"]
    role = my_role(cid, me_id) if me_id else None
    if not c["is_public"] and not role:
        raise ApiError("Нет доступа", 403)
    n = _members_count(cid)
    admins = q1("SELECT COUNT(*) n FROM members WHERE chat_id=? AND role IN ('owner','admin')", (cid,))["n"]
    if c["frozen"]:
        ft = "Удалённый канал" if c["type"] == "channel" else "Удалённая группа"
        return {
            "id": cid, "kind": c["type"], "title": ft, "descr": "", "is_public": False, "link": "",
            "invite": "", "url": "", "tg_id": "", "subscribers": n, "admins": admins, "blacklist": 0,
            "role": role, "avatar_color": "#8e9aa6", "avatar_data": GHOST_AVATAR, "name_color": "",
            "profile_color": "", "sub_text": sub_text(c["type"], n), "created": c["created"], "frozen": True,
        }
    return {
        "id": cid, "kind": c["type"], "title": c["title"] or "", "descr": c["descr"] or "",
        "is_public": bool(c["is_public"]), "link": c["link"] or "",
        "invite": (c["invite"] or "") if role else "",
        "url": chat_url(c), "tg_id": c["tg_id"] or "",
        "subscribers": n, "admins": admins, "blacklist": 0, "role": role,
        "avatar_color": c["avatar_color"] or "#65aadd", "avatar_data": c["avatar_data"] or None,
        "name_color": c["name_color"] or "", "profile_color": c["profile_color"] or "",
        "badge": _col(c, "badge"),
        "sub_text": sub_text(c["type"], n), "created": c["created"], "frozen": False,
    }


def api_chat_link_check(_body, qs):
    me = get_human(qs.get("user_id"))
    link = _norm_link(qs.get("q"))
    cid = None
    try:
        cid = int(qs.get("chat_id")) if qs.get("chat_id") else None
    except (TypeError, ValueError):
        pass
    err = link_problem(link, cid)
    return {"ok": err is None, "error": err, "link": link}


def api_chat_create(body, _qs):
    me = get_human(body.get("user_id"))
    kind = body.get("kind")
    if kind not in CHAT_KINDS:
        raise ApiError("Неверный тип чата")
    title = (body.get("title") or "").strip()[:128]
    if not title:
        raise ApiError("Введите название")
    descr = (body.get("descr") or "").strip()[:255]
    is_public = bool(body.get("is_public"))
    link = invite = None
    if is_public:
        link = _norm_link(body.get("link"))
        err = link_problem(link)
        if err:
            raise ApiError(err)
    else:
        invite = body.get("invite") or ""
        if not INVITE_RE.match(invite) or q1("SELECT 1 FROM chats WHERE invite=?", (invite,)):
            invite = _new_invite()
    try:
        cur = ex("""INSERT INTO chats(type,created,title,descr,link,invite,is_public,owner_id,
                                      avatar_data,avatar_color,tg_id) VALUES(?,?,?,?,?,?,?,?,?,?,?)""",
                 (kind, now(), title, descr, link, invite, 1 if is_public else 0, me["id"],
                  _clean_photo(body.get("avatar_data")), random.choice(COLORS), _new_tg_id()))
    except sqlite3.IntegrityError:
        raise ApiError("Ссылка занята.")
    cid = cur.lastrowid
    ex("INSERT INTO members(chat_id,user_id,role) VALUES(?,?,'owner')", (cid, me["id"]))
    if kind == "group":
        for uid in (body.get("member_ids") or [])[:200]:
            try:
                uid = int(uid)
            except (TypeError, ValueError):
                continue
            u = q1("SELECT id, is_bot FROM users WHERE id=?", (uid,))
            if u and not u["is_bot"] and uid != me["id"]:
                ex("INSERT OR IGNORE INTO members(chat_id,user_id,role) VALUES(?,?,'member')", (cid, uid))
    mid = add_message(cid, me["id"], "Канал создан" if kind == "channel" else "Группа создана")
    ex("UPDATE messages SET service=1 WHERE id=?", (mid,))
    ex("UPDATE members SET last_read=? WHERE chat_id=?", (mid, cid))
    touch(me["id"])
    item = group_chat_item(q1("SELECT * FROM chats WHERE id=?", (cid,)), me["id"])
    item.pop("_ts", None)
    return item


def api_chat_info(_body, qs):
    c = get_chat_row(qs.get("chat_id"))
    uid = None
    if qs.get("user_id"):
        uid = get_human(qs.get("user_id"))["id"]
    return chat_info(c, uid)


def api_chat_update(body, _qs):
    me = get_human(body.get("user_id"))
    c = get_chat_row(body.get("chat_id"))
    cid = c["id"]
    if my_role(cid, me["id"]) != "owner":
        raise ApiError("Только владелец может менять настройки", 403)
    sets, args = [], []
    if "title" in body:
        t = (body.get("title") or "").strip()[:128]
        if not t:
            raise ApiError("Введите название")
        sets.append("title=?"); args.append(t)
    if "descr" in body:
        sets.append("descr=?"); args.append((body.get("descr") or "").strip()[:255])
    if "avatar_data" in body:
        sets.append("avatar_data=?"); args.append(_clean_photo(body.get("avatar_data")))
    for k in ("name_color", "profile_color"):
        if k in body:
            v = (body.get(k) or "").strip()
            if v and not re.fullmatch(r"#[0-9a-fA-F]{6}(,#[0-9a-fA-F]{6})?", v):
                raise ApiError("Неверный цвет")
            sets.append(k + "=?"); args.append(v or None)
    if "is_public" in body:
        if body.get("is_public"):
            link = _norm_link(body.get("link"))
            err = link_problem(link, cid)
            if err:
                raise ApiError(err)
            sets += ["is_public=1", "link=?"]; args.append(link)
            if not c["invite"]:
                sets.append("invite=?"); args.append(_new_invite())
        else:
            sets += ["is_public=0", "link=NULL"]
            if not c["invite"] or body.get("reset_invite"):
                sets.append("invite=?"); args.append(_new_invite())
    if sets:
        try:
            ex("UPDATE chats SET " + ", ".join(sets) + " WHERE id=?", tuple(args) + (cid,))
        except sqlite3.IntegrityError:
            raise ApiError("Ссылка занята.")
    return chat_info(get_chat_row(cid), me["id"])


def api_chat_delete(body, _qs):
    me = get_human(body.get("user_id"))
    c = get_chat_row(body.get("chat_id"))
    if my_role(c["id"], me["id"]) != "owner":
        raise ApiError("Удалить может только владелец", 403)
    ex("DELETE FROM chats WHERE id=?", (c["id"],))
    return {"ok": True}


def api_chat_leave(body, _qs):
    me = get_human(body.get("user_id"))
    c = get_chat_row(body.get("chat_id"))
    role = my_role(c["id"], me["id"])
    if not role:
        raise ApiError("Вы не состоите в этом чате", 403)
    if role == "owner":
        if _members_count(c["id"]) > 1:
            raise ApiError("Владелец не может выйти. Удалите канал или передайте владение.", 403)
        ex("DELETE FROM chats WHERE id=?", (c["id"],))
    else:
        ex("DELETE FROM members WHERE chat_id=? AND user_id=?", (c["id"], me["id"]))
    return {"ok": True}


def api_chat_join(body, _qs):
    me = get_human(body.get("user_id"))
    ref = (body.get("ref") or "").strip()
    _fz = q1("SELECT frozen FROM chats WHERE id=?", (body.get("chat_id"),)) if body.get("chat_id") else None
    if _fz and _fz["frozen"]:
        raise ApiError("Чат заморожен", 403)
    if ref.startswith("http"):
        ref = ref.split("/", 3)[-1]
    ref = ref.replace(LINK_HOST + "/", "")
    c = None
    if body.get("chat_id"):
        c = get_chat_row(body.get("chat_id"))
        if not c["is_public"]:
            raise ApiError("Это частный чат — нужна ссылка-приглашение", 403)
    elif ref.startswith("+"):
        c = q1("SELECT * FROM chats WHERE invite=? AND type IN ('channel','group')", (ref,))
    elif ref:
        c = q1("SELECT * FROM chats WHERE link=? AND type IN ('channel','group')", (ref.lower().lstrip("@"),))
    if not c:
        raise ApiError("Ссылка недействительна", 404)
    if not my_role(c["id"], me["id"]):
        last = q1("SELECT MAX(id) m FROM messages WHERE chat_id=?", (c["id"],))["m"] or 0
        ex("INSERT OR IGNORE INTO members(chat_id,user_id,role,last_read) VALUES(?,?,'member',?)",
           (c["id"], me["id"], last))
    item = group_chat_item(c, me["id"])
    item.pop("_ts", None)
    return item


def api_chat_members(_body, qs):
    me = get_human(qs.get("user_id"))
    c = get_chat_row(qs.get("chat_id"))
    if not c["is_public"] and not my_role(c["id"], me["id"]):
        raise ApiError("Нет доступа", 403)
    only_admins = qs.get("admins") == "1"
    rows = q("""SELECT u.id, u.display_name, u.username, u.avatar_color, u.avatar_data, m.role
                FROM members m JOIN users u ON u.id=m.user_id WHERE m.chat_id=?
                ORDER BY CASE m.role WHEN 'owner' THEN 0 WHEN 'admin' THEN 1 ELSE 2 END, u.display_name
                LIMIT 300""", (c["id"],))
    out = []
    for r in rows:
        role = r["role"] or "member"
        if only_admins and role == "member":
            continue
        out.append({"id": r["id"], "name": r["display_name"] or r["username"], "username": r["username"],
                    "avatar_color": r["avatar_color"], "avatar_data": r["avatar_data"] or None, "role": role})
    return out


def api_chat_search(_body, qs):
    me = get_human(qs.get("user_id"))
    needle = (qs.get("q") or "").strip()
    if not needle:
        return []
    ref = needle.replace("https://", "").replace("http://", "").replace(LINK_HOST + "/", "")
    rows = []
    if ref.startswith("+"):
        rows = q("SELECT * FROM chats WHERE invite=? AND frozen=0 AND type IN ('channel','group')", (ref,))
    else:
        like = "%" + ref.lstrip("@").replace("%", "").replace("_", r"\_") + "%"
        rows = q("""SELECT * FROM chats WHERE is_public=1 AND frozen=0 AND type IN ('channel','group')
                    AND (link LIKE ? ESCAPE '\\' OR title LIKE ? ESCAPE '\\') ORDER BY title LIMIT 30""",
                 (like, like))
    out = []
    for c in rows:
        item = group_chat_item(c, me["id"])
        item.pop("_ts", None)
        out.append(item)
    return out



