def _static_icon(svg):
    """Маленькая статичная иконка вместо звезды Premium: без анимации, тени, блика и искры."""
    t = re.sub(r"<animate(Transform)?[^>]*?(/>|>.*?</animate(Transform)?>)", "", svg, flags=re.S)
    t = re.sub(r'<ellipse[^>]*filter="url\(#ikBlur\)"/>', "", t)
    t = re.sub(r'<g clip-path="url\(#ikClip\)">.*?</g>', "", t, flags=re.S)
    t = re.sub(r'<path style="transform-box[^>]*?</path>', "", t, flags=re.S)
    t = re.sub(r"<path style=\"transform-box[^>]*?/>", "", t)
    t = t.replace("ik", "ie").replace('class="ie-svg"', 'class="tg-star-icon nfg-ico"')
    return t.replace('viewBox="0 0 240 240"', 'viewBox="38 40 164 168" width="20" height="20"', 1)


