@_sa_lru(maxsize=4)
def _sa_embedded(tag="SPYAGARIC_BLOB"):
    """Грибы, вшитые в конец этого файла (блоки SPYAGARIC_BLOB — 512 px и SPYAGARIC_THUMB_BLOB — 256 px для плиток):
    отдаются, даже если папки gifts/spyagaric/ нет."""
    import base64, io, lzma, tarfile
    try:
        with open(os.path.abspath(__file__), encoding="utf-8") as f:
            text = f.read()
        a = text.rindex("# %s_BEGIN\n" % tag) + len("# %s_BEGIN\n" % tag)
        b = text.index("# %s_END" % tag, a)
        data = "".join(l[2:] for l in text[a:b].splitlines() if l.startswith("# "))
        out = {}
        with tarfile.open(fileobj=io.BytesIO(lzma.decompress(base64.b64decode(data)))) as t:
            for m in t.getmembers():
                if m.isfile():
                    out[_mm_norm(m.name)] = t.extractfile(m).read()
        return out
    except Exception:
        traceback.print_exc()
        return {}


def _sa_fname(name, sub=""):
    """Имя файла гриба на диске: у части файлов в архиве ’ превратился в #U2019, а 'Liquid Metal 1' лежит как 'Liquid Metal'."""
    base = os.path.join(GIFT_DIR, "spyagaric", sub)
    ext = ".json" if sub == "anim" else ".png"
    for cand in (name, name.replace("\u2019", "#U2019"), re.sub(r"\s+\d+$", "", name),
                 re.sub(r"\s+\d+$", "", name).replace("\u2019", "#U2019")):
        if os.path.isfile(os.path.join(base, cand + ext)):
            return cand
    return name


def _sa_url(name):
    return "/gifts/spyagaric/%s.png" % _sa_quote(_sa_fname(name))


def sa_lottie_url(name):
    """Lottie-анимация гриба (gifts/spyagaric/anim/<Название>.json) — та же, что в Telegram."""
    return "/gifts/spyagaric/anim/%s.json" % _sa_quote(_sa_fname(name, "anim"), safe="")


_THUMBS = {}


def _gift_thumb(name):
    """Миниатюра 256 px любой картинки из gifts/ (нужна библиотека Pillow; без неё отдаётся оригинал). Кэшируется в памяти."""
    key = _mm_norm(name)
    if key in _THUMBS:
        return _THUMBS[key]
    found = _mm_find_file(name)
    if not found:
        return None
    mime = GIFT_MIME[os.path.splitext(found)[1].lower()]
    with open(found, "rb") as f:
        data = f.read()
    try:
        import io as _io
        from PIL import Image as _Img
        im = _Img.open(_io.BytesIO(data)).convert("RGBA")
        im.thumbnail((256, 256))
        out = _io.BytesIO()
        im.save(out, "PNG", optimize=True)
        data, mime = out.getvalue(), "image/png"
    except Exception:
        pass
    _THUMBS[key] = (data, mime)
    return _THUMBS[key]


def _sa_turl(name):
    """Лёгкая миниатюра 256 px — для плиток, списков и иконок (большая картинка в десятках плиток тормозит телефон)."""
    return "/gifts/spyagaric/t/%s.png" % _sa_quote(name)


@_sa_lru(maxsize=8192)
def sa_traits(num):
    """Модель / узор / фон для номера: случайно с учётом шансов, но один и тот же номер всегда даёт одно и то же."""
    rng = random.Random("spyagaric:%d" % num)
    p = _rd_pick(rng, SA_PATTERNS)      # порядок розыгрыша сохранён: узор и фон у уже выпущенных номеров не меняются
    bg = _rd_pick(rng, SA_BGS)
    m = _rd_pick(rng, SA_MODELS)        # новая часть: случайный гриб
    if SA_ONLY_BLACK:
        bg = SA_BGS[0]
    prob = (m[1] / 100.0) * (p[1] / 100.0) * (bg[1] / 100.0)
    value = max(3000, int(round(300 * (1.0 / prob) ** 0.3, -2)))
    return {"model": (m[0], "%g%%" % m[1]), "pattern": (p[0], "%g%%" % p[1]), "bg": (bg[0], "%g%%" % bg[1]),
            "value_rub": value, "_m": m, "_p": p, "_b": bg}



def sa_hero_css(num):
    b = sa_traits(num)["_b"]
    return "radial-gradient(circle at 50%% 30%%,%s 0,%s 100%%)" % (b[2], b[3])


def sa_look(num):
    b = sa_traits(num)["_b"]
    return {"css": sa_hero_css(num), "top": b[2], "bot": b[3]}


def _sa_particles(kind, col, rng):
    """Частицы вокруг гриба: споры, пузырьки, снег, искры/угольки, мерцающие звёздочки."""
    o = []
    if kind == "stars":
        for i in range(6):
            x, y, sz = 62 + rng.random() * 116, 36 + rng.random() * 54, .7 + rng.random() * .7
            o.append('<g transform="translate(%.1f %.1f)"><path d="M0-6C.6-2 2-.6 6 0C2 .6 .6 2 0 6C-.6 2-2 .6-6 0C-2-.6-.6-2 0-6Z" fill="%s" opacity="0">'
                     '<animate attributeName="opacity" values="0;1;0" dur="2.2s" begin="%.2fs" repeatCount="indefinite"/>'
                     '<animateTransform attributeName="transform" type="scale" values="0;%.2f;0" dur="2.2s" begin="%.2fs" repeatCount="indefinite"/></path></g>' % (
                         x, y, col if i % 2 else "#ffffff", i * .37, sz, i * .37))
        return "".join(o)
    # (кол-во, диапазон x, диапазон y старта, смещение по y, длительность, r от, r до, кольцо вместо точки)
    n, xr, yr, dist, dur, r0, r1, ring = {
        "spores": (8, (64, 176), (60, 92), -48, 4.6, 1.2, 2.6, False),
        "bubbles": (6, (84, 156), (168, 196), -112, 4.2, 2.4, 5.0, True),
        "snow": (9, (50, 190), (12, 40), 150, 4.0, 1.2, 2.4, False),
        "embers": (8, (86, 154), (150, 190), -120, 3.4, 1.2, 2.8, False),
    }[kind]
    for i in range(n):
        x, y = xr[0] + rng.random() * (xr[1] - xr[0]), yr[0] + rng.random() * (yr[1] - yr[0])
        r, dx, bg_t = r0 + rng.random() * (r1 - r0), (rng.random() - .5) * 24, i * dur / n
        fill = ('fill="none" stroke="%s" stroke-width="1.2"' if ring else 'fill="%s"') % col
        o.append('<circle cx="%.1f" cy="%.1f" r="%.1f" %s opacity="0">'
                 '<animateTransform attributeName="transform" type="translate" values="0 0;%.1f %.1f" dur="%.1fs" begin="%.2fs" repeatCount="indefinite"/>'
                 '<animate attributeName="opacity" values="0;.9;.9;0" keyTimes="0;.15;.7;1" dur="%.1fs" begin="%.2fs" repeatCount="indefinite"/></circle>' % (
                     x, y, r, fill, dx, dist, dur, bg_t, dur, bg_t))
    return "".join(o)


@_sa_lru(maxsize=2048)
def sa_svg(num=1, animated=True, backdrop=False, u=None):
    """SVG гриба: PNG случайной модели + фон + кольца узора + собственная анимация гриба. backdrop=False — фон рисует окно подарка."""
    u = u or "sa%d" % num
    t = sa_traits(num)
    b = t["_b"]
    name = t["_m"][0]
    img = _sa_url(name) if animated else _sa_turl(name)
    mo, ef, col = SA_ANIM.get(name, ("bob", "none", "#ffffff"))
    rng = random.Random("saanim:" + name)
    d = 2.6 + rng.random() * 1.8      # темп: свой у каждого гриба
    k = .8 + rng.random() * .5        # размах: свой у каждого гриба
    fx = set(ef.split("+"))
    A = (lambda s: s) if animated else (lambda s: "")
    extra = ""
    if animated and fx & {"glow", "flicker"}:
        extra += ('<filter id="%sGl" x="-30%%" y="-30%%" width="160%%" height="160%%"><feGaussianBlur in="SourceAlpha" stdDeviation="7" result="bl"/>'
                  '<feFlood flood-color="%s"/><feComposite in2="bl" operator="in"/></filter>' % (u, col))
    if animated and "hue" in fx:
        extra += ('<filter id="%sHu"><feColorMatrix type="hueRotate" values="0"><animate attributeName="values" from="0" to="360" dur="%.1fs" '
                  'repeatCount="indefinite"/></feColorMatrix></filter>' % (u, d * 2))
    if animated and fx & {"shine", "scan"}:
        extra += ('<mask id="%sM" maskUnits="userSpaceOnUse" x="0" y="0" width="240" height="240" style="mask-type:alpha">'
                  '<image href="%s" x="36" y="28" width="168" height="168"/></mask>' % (u, img))
    if animated and "shine" in fx:
        extra += ('<linearGradient id="%sS" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stop-color="#fff" stop-opacity="0"/>'
                  '<stop offset=".5" stop-color="#fff" stop-opacity=".75"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></linearGradient>' % u)
    if animated and "scan" in fx:
        extra += ('<linearGradient id="%sC" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="%s" stop-opacity="0"/>'
                  '<stop offset=".5" stop-color="%s" stop-opacity=".8"/><stop offset="1" stop-color="%s" stop-opacity="0"/></linearGradient>' % (u, col, col, col))
    if animated and "spots" in fx:
        extra += ('<radialGradient id="%sG"><stop offset="0" stop-color="#fff8c0" stop-opacity=".95"/><stop offset=".55" stop-color="#ffc400" stop-opacity=".35"/>'
                  '<stop offset="1" stop-color="#ffc400" stop-opacity="0"/></radialGradient>' % u)
    o = ['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 240 240" class="rd-svg"><defs>'
         '<radialGradient id="%sK" cx=".5" cy=".3" r=".85"><stop offset="0" stop-color="%s"/><stop offset="1" stop-color="%s"/></radialGradient>'
         '<radialGradient id="%sW"><stop offset="0" stop-color="#fff" stop-opacity=".3"/><stop offset=".6" stop-color="#fff" stop-opacity=".08"/>'
         '<stop offset="1" stop-color="#fff" stop-opacity="0"/></radialGradient>'
         '<filter id="%sB" x="-30%%" y="-60%%" width="160%%" height="220%%"><feGaussianBlur stdDeviation="5"/></filter>'
         '<path id="%sP" d="%s" fill-rule="evenodd"/>%s</defs>' % (u, b[2], b[3], u, u, u, _sa_glyph(t["_p"][0]), extra)]
    if backdrop:
        o.append('<rect width="240" height="240" fill="url(#%sK)"/>' % u)
    o.append('<circle cx="120" cy="108" r="92" fill="url(#%sW)"/>' % u)      # мягкое свечение за грибом
    # узор (случайный по номеру): два кольца вокруг героя
    o.append('<g fill="%s" opacity=".2">' % b[4])
    o.append(A('<animate attributeName="opacity" values=".14;.26;.14" dur="4s" repeatCount="indefinite"/>'))
    for r, n, sc, off in ((106, 12, 1.0, 0), (78, 9, .85, 14)):
        for i in range(n):
            a = math.radians(off + i * 360.0 / n)
            o.append('<use href="#%sP" transform="translate(%.1f %.1f) rotate(%d) scale(%.2f)"/>' % (
                u, 120 + r * math.cos(a), 120 + r * math.sin(a), (i * 37) % 60 - 30, sc))
    o.append('</g>')
    o.append('<ellipse cx="120" cy="206" rx="46" ry="7" fill="#000" opacity=".5" filter="url(#%sB)"/>' % u)
    if not animated:
        o.append('<image href="%s" x="36" y="28" width="168" height="168"/></svg>' % img)
        return "".join(o)
    m = _mm_motion(mo, d, k)
    # герой: движение вокруг основания ножки (сдвиг → поворот → масштаб), у каждого гриба своё
    o.append('<g transform="translate(120 196)"><g>%s<g>%s<g>%s<g transform="translate(-120 -196)">%s' % (
        m.get("t", ""), m.get("r", ""), m.get("s", ""), m.get("o", "")))
    if fx & {"glow", "flicker"}:
        if "flicker" in fx:
            an = '<animate attributeName="opacity" values=".7;.25;.9;.35;.8;.3;.75;.6" dur="%.2fs" repeatCount="indefinite"/>' % (d * .45)
        else:
            an = '<animate attributeName="opacity" values=".25;.8;.25" dur="%.2fs" repeatCount="indefinite"/>' % (d * .8)
        o.append('<image href="%s" x="36" y="28" width="168" height="168" filter="url(#%sGl)" opacity=".5">%s</image>' % (img, u, an))
    o.append('<image href="%s" x="36" y="28" width="168" height="168"%s/>' % (img, ' filter="url(#%sHu)"' % u if "hue" in fx else ""))
    if "spots" in fx:     # золотые пятна Royal Gold пульсируют светом
        for i, (cx, cy, r) in enumerate(((116.4, 43.6, 11), (130.3, 72, 7), (159, 85.4, 13), (94.2, 108.4, 15), (85.2, 80.5, 8))):
            o.append('<circle cx="%.1f" cy="%.1f" r="%g" fill="url(#%sG)" style="mix-blend-mode:screen" opacity=".3">'
                     '<animate attributeName="opacity" values=".1;1;.1" dur="2.4s" begin="%.1fs" repeatCount="indefinite"/>'
                     '<animate attributeName="r" values="%g;%g;%g" dur="2.4s" begin="%.1fs" repeatCount="indefinite"/></circle>' % (
                         cx, cy, r, u, i * .5, r * .8, r * 1.15, r * .8, i * .5))
    if "shine" in fx:
        o.append('<g mask="url(#%sM)"><rect x="-70" y="20" width="46" height="190" fill="url(#%sS)" transform="rotate(25 120 120)">'
                 '<animateTransform attributeName="transform" type="translate" values="-60 0;300 0;300 0" keyTimes="0;.45;1" dur="%.2fs" '
                 'repeatCount="indefinite" additive="sum"/></rect></g>' % (u, u, d * 1.3))
    if "scan" in fx:
        o.append('<g mask="url(#%sM)"><rect x="30" y="0" width="180" height="26" fill="url(#%sC)">'
                 '<animateTransform attributeName="transform" type="translate" values="0 10;0 185;0 185" keyTimes="0;.7;1" dur="%.2fs" '
                 'repeatCount="indefinite"/></rect></g>' % (u, u, d * 1.2))
    if "sparkle" in fx:
        for i in range(4):
            x, y, sz = 58 + rng.random() * 124, 40 + rng.random() * 130, .8 + rng.random() * .7
            o.append('<g transform="translate(%.1f %.1f)"><path d="M0-6C.6-2 2-.6 6 0C2 .6 .6 2 0 6C-.6 2-2 .6-6 0C-2-.6-.6-2 0-6Z" fill="%s" opacity="0">'
                     '<animate attributeName="opacity" values="0;1;0" dur="2.2s" begin="%.1fs" repeatCount="indefinite"/>'
                     '<animateTransform attributeName="transform" type="scale" values="0;%.2f;0" dur="2.2s" begin="%.1fs" repeatCount="indefinite"/></path></g>' % (
                         x, y, "#ffffff" if i % 2 else col, i * .55, sz, i * .55))
    o.append('</g></g></g></g></g>')
    for kind in ("spores", "bubbles", "snow", "embers", "stars"):
        if kind in fx:
            o.append(_sa_particles(kind, col, rng))
    o.append('</svg>')
    return "".join(o)



def sa_pattern_svg(num=1):
    """Узор Human Skull для фона шапки профиля, где подарок надет: кольца черепов вокруг аватарки."""
    o = ['<svg xmlns="http://www.w3.org/2000/svg" viewBox="-300 0 600 400" class="rd-pat"><defs><path id="saPP" d="%s" fill-rule="evenodd"/></defs>'
         '<g fill="%s" opacity=".2"><animate attributeName="opacity" values=".15;.26;.15" dur="4s" repeatCount="indefinite"/>' % (_sa_glyph(sa_traits(num)["_p"][0]), sa_traits(num)["_b"][4])]
    for ri, (r, n) in enumerate(((78, 9), (130, 15), (184, 21), (238, 27), (292, 33))):
        for i in range(n):
            a = math.radians(i * 360.0 / n + ri * 11)
            x, y = r * math.cos(a), 80 + r * math.sin(a) * 0.9
            if y < 4 or y > 396 or abs(x) > 296:
                continue
            o.append('<use href="#saPP" transform="translate(%.1f %.1f) rotate(%d) scale(%.2f)"/>' % (
                x, y, (i * 41 + ri * 17) % 70 - 35, 1.15 + 0.12 * ((i + ri) % 3)))
    o.append('</g></svg>')
    return "".join(o)


def sa_icon(num):
    t = sa_traits(num)
    return ('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="20" height="20" class="tg-star-icon nfg-ico">'
            '<circle cx="12" cy="12" r="12" fill="%s"/><image href="%s" x="3" y="2.5" width="18" height="18"/></svg>') % (
                t["_b"][2], _sa_turl(t["_m"][0]))



