def _ws_url(name):
    return "/gifts/westsidesign/%s.png" % _ws_quote(name)

def _ws_turl(name):
    return "/gifts/westsidesign/t/%s.png" % _ws_quote(name)

def ws_traits(num):
    """Модель / узор / фон для номера: случайно с учётом шансов, стабильно по номеру."""
    rng = random.Random("westsidesign:%d" % num)
    p = _rd_pick(rng, WS_PATTERNS)
    bg = _rd_pick(rng, WS_BGS)
    m = _rd_pick(rng, WS_MODELS)
    return {"model": (m[0], "%g%%" % m[1]), "pattern": (p[0], "%g%%" % p[1]), "bg": (bg[0], "%g%%" % bg[1]),
            "value_rub": 3500, "_m": m, "_p": p, "_b": bg}

def ws_hero_css(num):
    t = ws_traits(num)
    b = t["_b"]
    return "radial-gradient(circle at 50%% 25%%, %s 0, %s 100%%)" % (b[2], b[3])

def ws_look(num):
    t = ws_traits(num)
    b = t["_b"]
    return {"css": ws_hero_css(num), "top": b[2], "bot": b[3]}

@_ws_lru(maxsize=2048) if False else (lambda f: f)  # no lru for simplicity if not imported
def ws_svg(num=1, animated=True, backdrop=False, u=None):
    """SVG Westside Sign: PNG модели + фон + кольца узора. Анимация — простой bob (Lottie в anim/ для клиента)."""
    u = u or "ws%d" % num
    t = ws_traits(num)
    b = t["_b"]
    name = t["_m"][0]
    img = _ws_url(name) if animated else _ws_turl(name)
    o = ['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 240 240" class="nfg">']
    if backdrop:
        o.append('<defs><radialGradient id="%sBg" cx="50%%" cy="40%%" r="60%%"><stop offset="0%%" stop-color="%s"/><stop offset="100%%" stop-color="%s"/></radialGradient></defs>' % (u, b[2], b[3]))
        o.append('<rect width="240" height="240" rx="28" fill="url(#%sBg)"/>' % u)
    # pattern rings
    o.append('<g fill="%s" opacity=".18">' % b[4])
    for ri, (r, n) in enumerate(((55, 8), (85, 12), (115, 16))):
        for i in range(n):
            a = math.radians(i * 360.0 / n + ri * 9)
            x, y = 120 + r * math.cos(a), 120 + r * math.sin(a)
            o.append('<circle cx="%.1f" cy="%.1f" r="3.2"/>' % (x, y))
    o.append('</g>')
    if not animated:
        o.append('<image href="%s" x="36" y="28" width="168" height="168"/></svg>' % img)
        return "".join(o)
    # simple bob
    o.append('<g transform="translate(120 196)"><animateTransform attributeName="transform" type="translate" values="0 0;0 -5;0 0" dur="2.4s" repeatCount="indefinite" additive="sum"/>')
    o.append('<g transform="translate(-120 -196)"><image href="%s" x="36" y="28" width="168" height="168"/></g></g></svg>' % img)
    return "".join(o)

def ws_pattern_svg(num=1):
    t = ws_traits(num)
    o = ['<svg xmlns="http://www.w3.org/2000/svg" viewBox="-300 0 600 400" class="rd-pat"><g fill="%s" opacity=".2"><animate attributeName="opacity" values=".15;.26;.15" dur="4s" repeatCount="indefinite"/>' % t["_b"][4]]
    for ri, (r, n) in enumerate(((78, 9), (130, 15), (184, 21), (238, 27), (292, 33))):
        for i in range(n):
            a = math.radians(i * 360.0 / n + ri * 11)
            x, y = r * math.cos(a), 80 + r * math.sin(a) * 0.9
            if y < 4 or y > 396 or abs(x) > 296: continue
            o.append('<circle cx="%.1f" cy="%.1f" r="4"/>' % (x, y))
    o.append('</g></svg>')
    return "".join(o)

