def _mm_shade(c, k):
    r, g, b = (int(c[i:i + 2], 16) for i in (1, 3, 5))
    return "#%02x%02x%02x" % tuple(int(v * k) for v in (r, g, b))


def _mm_bg(n, p, c):
    if n == "Black":
        return (n, p, "#343536", "#0e0f0f", "#ffffff")
    if n == "Onyx Black":
        return (n, p, c, "#0a0a0b", "#d0d0d8")
    r, g, b = (int(c[i:i + 2], 16) for i in (1, 3, 5))
    lum = (0.299 * r + 0.587 * g + 0.114 * b) / 255
    return (n, p, c, _mm_shade(c, .5), _mm_shade(c, .45) if lum > .62 else _sa_tint(c))


