def _mm_glyph(name):
    g = MM_GLYPHS.get(name)
    return g or _sa_glyph(MM_FALLBACK[sum(map(ord, name)) % len(MM_FALLBACK)])


def _mm_url(name):
    return "/gifts/mythmask/%s.png" % _mm_quote(name)


def _mm_turl(name):
    return "/gifts/t/mythmask/%s.png" % _mm_quote(name)


def _mm_pick(rng, items):
    tot = sum(i[1] for i in items)
    x, acc = rng.random() * tot, 0.0
    for it in items:
        acc += it[1]
        if x < acc:
            return it
    return items[-1]


@_mm_lru(maxsize=8192)
def mm_traits(num):
    """Модель / узор / фон для номера: случайно с учётом шансов, но один и тот же номер всегда даёт одно и то же."""
    rng = random.Random("mythmask:%d" % num)
    m, p, b = _mm_pick(rng, MM_MODELS), _mm_pick(rng, MM_PATTERNS), _mm_pick(rng, MM_BGS)
    tm, tp = sum(x[1] for x in MM_MODELS), sum(x[1] for x in MM_PATTERNS)
    prob = (m[1] / tm) * (p[1] / tp) * (b[1] / 100.0)
    value = max(300, int(round(40 * (1.0 / prob) ** 0.3, -2)))
    return {"model": (m[0], "%g%%" % m[1]), "pattern": (p[0], "%g%%" % p[1]), "bg": (b[0], "%g%%" % b[1]),
            "value_rub": value, "_m": m, "_p": p, "_b": b}


def mm_hero_css(num):
    b = mm_traits(num)["_b"]
    return "radial-gradient(circle at 50%% 30%%,%s 0,%s 100%%)" % (b[2], b[3])


def mm_look(num):
    b = mm_traits(num)["_b"]
    return {"css": mm_hero_css(num), "top": b[2], "bot": b[3]}


