def _gift_view(slug, num):
    """Параметры конкретного экземпляра: для генерируемых подарков (resistdog) — случайные по номеру, для остальных — общие."""
    c = COLLECTIBLES[slug]
    if c.get("gen") and slug == "resistdog":
        t = rd_traits(num)
        lottie = "/gifts/resistdog/anim/%s.json" % quote(t["model"][0], safe="")
        return {"model": t["model"], "pattern": t["pattern"], "bg": t["bg"], "value_rub": t["value_rub"],
                "svg": rd_svg(num, True, False), "thumb": rd_svg(num, False, True), "hero_css": rd_hero_css(num),
                "lottie": lottie}
    if slug == "mythmask":
        t = mm_traits(num)
        return {"model": t["model"], "pattern": t["pattern"], "bg": t["bg"], "value_rub": t["value_rub"],
                "svg": mm_svg(num, True, False), "thumb": mm_svg(num, False, True), "hero_css": mm_hero_css(num)}
    if slug == "spyagaric":
        t = sa_traits(num)
        return {"model": t["model"], "pattern": t["pattern"], "bg": t["bg"], "value_rub": t["value_rub"],
                "svg": sa_svg(num, True, False), "thumb": sa_svg(num, False, True), "hero_css": sa_hero_css(num),
                "lottie": sa_lottie_url(t["_m"][0])}
    if slug == "westsidesign":
        t = ws_traits(num)
        lottie = "/gifts/westsidesign/anim/%s.json" % _ws_quote(t["_m"][0])
        return {"model": t["model"], "pattern": t["pattern"], "bg": t["bg"], "value_rub": t["value_rub"],
                "svg": ws_svg(num, True, False), "thumb": ws_svg(num, False, True), "hero_css": ws_hero_css(num),
                "lottie": lottie}
    return {"model": c["model"], "pattern": c["pattern"], "bg": c["bg"], "value_rub": c["value_rub"],
            "svg": c["svg"], "thumb": c.get("thumb", c["svg"]), "hero_css": ""}


def _gift_tile(slug, num):
    """Данные карточки подарка в сетке (как на карточках Telegram): градиент-фон, картинка без фона, подписи."""
    c = COLLECTIBLES[slug]
    v = _gift_view(slug, num)
    svg = (mm_svg(num, False, False) if slug == "mythmask" else
           sa_svg(num, False, False) if slug == "spyagaric" else
           rd_svg(num, False, False) if slug == "resistdog" else v["thumb"])
    return {"title": c["title"], "model": v["model"][0], "price": "{:,} ₽".format(v["value_rub"]).replace(",", " "),
            "bd": v["hero_css"], "tsvg": svg}


def _worn(u):
    """Надетый подарок пользователя (только пока у него есть Premium) или None."""
    try:
        wid = u["worn_gift"] if "worn_gift" in u.keys() else None
        if not wid or not is_premium(u):
            return None
        r = q1("SELECT id, slug, num FROM nft_gifts WHERE id=? AND owner_id=?", (wid, u["id"]))
        if not r or r["slug"] not in COLLECTIBLES:
            return None
        w = {"id": r["id"], "slug": r["slug"], "num": r["num"]}
        if COLLECTIBLES[r["slug"]].get("gen") and r["slug"] == "resistdog":
            w.update(rd_look(r["num"]))
            w["ic"] = rd_icon(r["num"])
            try:
                w["lottie"] = "/gifts/resistdog/anim/%s.json" % quote(rd_traits(r["num"])["model"][0], safe="")
            except Exception:
                pass
        elif r["slug"] == "spyagaric":
            w.update(sa_look(r["num"]))
            w["ic"] = sa_icon(r["num"])
            try:
                w["lottie"] = sa_lottie_url(sa_traits(r["num"])["_m"][0])
            except Exception:
                pass
        elif r["slug"] == "mythmask":
            w.update(mm_look(r["num"]))
            w["ic"] = mm_icon(r["num"])
        elif r["slug"] == "westsidesign":
            w.update(ws_look(r["num"]))
            w["ic"] = ('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="20" height="20" class="tg-star-icon nfg-ico">'
                       '<circle cx="12" cy="12" r="12" fill="%s"/><image href="%s" x="3" y="2.5" width="18" height="18"/></svg>') % (
                           ws_traits(r["num"])["_b"][2], _ws_turl(ws_traits(r["num"])["_m"][0]))
        return w
    except Exception:
        return None


def nft_gift_json(r):
    c = COLLECTIBLES[r["slug"]]
    v = _gift_view(r["slug"], r["num"])
    owner = q1("SELECT * FROM users WHERE id=?", (r["owner_id"],))
    issued = q1("SELECT COUNT(*) n FROM nft_gifts WHERE slug=?", (r["slug"],))["n"]
    o = user_json(owner) if owner else {}
    return {
        "id": r["id"], "slug": r["slug"], "title": c["title"], "num": r["num"],
        "from": r["from_label"] or "", "hidden": bool(r["hidden"]), "ts": r["ts"],
        "worn": bool(o.get("worn_gift") and o["worn_gift"]["id"] == r["id"]),
        "model": v["model"][0], "model_pct": v["model"][1],
        "pattern": v["pattern"][0], "pattern_pct": v["pattern"][1],
        "bg": v["bg"][0], "bg_pct": v["bg"][1], "hero_css": v["hero_css"],
        "supply": c["supply"], "minted": min(c["supply"], c["minted_base"] + issued),
        "value_rub": v["value_rub"], "svg": v["svg"],
        "lottie": v.get("lottie") or "",
        "can_sell": market_open(r["slug"]),
        "sell_note": "" if market_open(r["slug"]) else "Продажа на маркете откроется, когда весь тираж будет распродан (осталось %d)" % sale_state(r["slug"])["left"],
        "owner": {"id": o.get("id"), "username": o.get("username", ""), "display_name": o.get("display_name", ""),
                  "avatar_data": o.get("avatar_data"), "avatar_color": o.get("avatar_color"),
                  "avatar_text": o.get("avatar_text"), "premium": o.get("premium", False),
                  "verified": o.get("verified", False), "badge": o.get("badge", "")},
    }


def nft_gift_give(user_id, slug="inputkey", num=None, from_label=""):
    c = COLLECTIBLES.get(slug)
    if not c:
        raise NftError("Неизвестный подарок. Доступно: " + ", ".join(COLLECTIBLES))
    used = {r["num"] for r in q("SELECT num FROM nft_gifts WHERE slug=?", (slug,))} | \
           {r["num"] for r in q("SELECT num FROM nft_market WHERE slug=?", (slug,))}
    if num is None:
        free = [n for n in range(1, c["supply"] + 1) if n not in used]
        if not free:
            raise NftError("Весь тираж выдан")
        num = random.choice(free)
    elif not 1 <= num <= c["supply"] or num in used:
        raise NftError("Номер #%s занят или вне тиража 1–%s" % (num, c["supply"]))
    cur = ex("INSERT INTO nft_gifts(owner_id,slug,num,from_label,ts) VALUES(?,?,?,?,?)",
             (user_id, slug, num, (from_label or "")[:40], now()))
    return cur.lastrowid, num


def _parse_nftgift_args(rest):
    """[slug] [#номер] [от кого…]"""
    slug, num, rest = "inputkey", None, list(rest)
    if rest and rest[0].lower() in COLLECTIBLES:
        slug = rest.pop(0).lower()
    if rest and re.fullmatch(r"#?\d{1,6}", rest[0]):
        num = int(rest.pop(0).lstrip("#"))
    return slug, num, " ".join(rest).strip()


def nft_market_mint(slug, qty, price):
    """Выпускает qty экземпляров на маркет по цене price ⭐ (случайные свободные номера)."""
    c = COLLECTIBLES.get(slug)
    if not c:
        raise NftError("Неизвестный подарок. Доступно: " + ", ".join(COLLECTIBLES))
    if not 1 <= qty <= c["supply"]:
        raise NftError("Количество: от 1 до %s" % c["supply"])
    if not 1 <= price <= 10_000_000:
        raise NftError("Цена: от 1 до 10 000 000 ⭐")
    with _lock:
        used = {r["num"] for r in db.execute("SELECT num FROM nft_gifts WHERE slug=?", (slug,))} | \
               {r["num"] for r in db.execute("SELECT num FROM nft_market WHERE slug=?", (slug,))}
        free = [n for n in range(1, c["supply"] + 1) if n not in used]
        if qty > len(free):
            raise NftError("Свободных номеров осталось: %s" % len(free))
        nums = sorted(random.sample(free, qty))
        db.executemany("INSERT INTO nft_market(slug,num,price,ts) VALUES(?,?,?,?)",
                       [(slug, n, price, now()) for n in nums])
        db.commit()
    return nums


def nft_market_stats(slug):
    c = COLLECTIBLES[slug]
    owned = q1("SELECT COUNT(*) n FROM nft_gifts WHERE slug=?", (slug,))["n"]
    listed = q1("SELECT COUNT(*) n, MIN(price) lo, MAX(price) hi FROM nft_market WHERE slug=?", (slug,))
    return {"supply": c["supply"], "owned": owned, "listed": listed["n"], "lo": listed["lo"], "hi": listed["hi"],
            "free": c["supply"] - owned - listed["n"]}


def api_nft_market(_body, qs):
    me = get_human(qs.get("user_id"))
    # сортировка как в ResaleGiftsFragment: по цене, по номеру, по дате выставления
    order = {"price": "price, num", "num": "num", "date": "ts DESC, id DESC"}.get(qs.get("sort") or "price", "price, num")
    out = []
    only = (qs.get("slug") or "").lower()
    for slug, c in COLLECTIBLES.items():
        if only and slug != only:
            continue
        rows = q("SELECT id, num, price, seller_id FROM nft_market WHERE slug=? ORDER BY %s LIMIT %d" % (order, 400 if only else 150), (slug,))
        st = nft_market_stats(slug)
        out.append({"slug": slug, "title": c["title"], "count": st["listed"], "floor": st["lo"], "supply": c["supply"],
                    "model": c["model"], "pattern": c["pattern"], "bg": c["bg"],
                    "svg": _gift_view(slug, rows[0]["num"] if rows else 76)["thumb"],
                    "items": [dict(id=r["id"], num=r["num"], price=r["price"], mine=(r["seller_id"] == me["id"]),
                                   bd=_gift_tile(slug, r["num"])["bd"], tsvg=_gift_tile(slug, r["num"])["tsvg"],
                                   tr=[_gift_view(slug, r["num"])[k][0] for k in ("model", "pattern", "bg")]) for r in rows]})
    return {"stars": me["stars"] or 0, "collections": out}


def api_nft_market_buy(body, _qs):
    me = get_human(body.get("user_id"))
    try:
        lid = int(body.get("id"))
    except (TypeError, ValueError):
        raise ApiError("Лот не найден", 404)
    with _lock:
        r = db.execute("SELECT * FROM nft_market WHERE id=?", (lid,)).fetchone()
        if not r:
            raise ApiError("Этот подарок уже продан", 404)
        if r["seller_id"] == me["id"]:
            raise ApiError("Это ваш лот: снимите его с продажи", 400)
        cur = db.execute("UPDATE users SET stars=stars-? WHERE id=? AND stars>=?", (r["price"], me["id"], r["price"]))
        if cur.rowcount != 1:
            db.rollback()
            raise ApiError("Недостаточно ⭐ — нужно %s" % r["price"], 402)
        if r["seller_id"]:
            db.execute("UPDATE users SET stars=stars+? WHERE id=?",
                       (r["price"] * (1000 - RESALE_FEE_PERMILLE) // 1000, r["seller_id"]))
        db.execute("DELETE FROM nft_market WHERE id=?", (lid,))
        cur = db.execute("INSERT INTO nft_gifts(owner_id,slug,num,from_label,ts) VALUES(?,?,?,?,?)",
                         (me["id"], r["slug"], r["num"], "Маркет", now()))
        db.commit()
        gid = cur.lastrowid
    touch(me["id"])
    return {"ok": True, "gift_id": gid, "stars": q1("SELECT stars FROM users WHERE id=?", (me["id"],))["stars"]}


RESALE_FEE_PERMILLE = 0   # комиссия маркета с перепродажи, в промилле (0 — без комиссии; 200 = 20%)


def _own_gift(body, me):
    try:
        r = q1("SELECT * FROM nft_gifts WHERE id=? AND owner_id=?", (int(body.get("id")), me["id"]))
    except (TypeError, ValueError):
        r = None
    if not r or r["slug"] not in COLLECTIBLES:
        raise ApiError("Подарок не найден", 404)
    return r


def api_nft_gift_resale(body, _qs):
    """Выставить свой подарок на маркет по цене в ⭐ (экран перепродажи)."""
    me = get_human(body.get("user_id"))
    r = _own_gift(body, me)
    if not market_open(r["slug"]):
        raise ApiError("Продажа на маркете откроется, когда весь тираж будет распродан (осталось %d)" % sale_state(r["slug"])["left"], 403)
    try:
        price = int(body.get("price"))
    except (TypeError, ValueError):
        raise ApiError("Укажите цену в ⭐")
    if not 1 <= price <= 10_000_000:
        raise ApiError("Цена: от 1 до 10 000 000 ⭐")
    with _lock:
        db.execute("UPDATE users SET worn_gift=NULL WHERE id=? AND worn_gift=?", (me["id"], r["id"]))
        db.execute("DELETE FROM nft_gifts WHERE id=?", (r["id"],))
        db.execute("INSERT INTO nft_market(slug,num,price,ts,seller_id) VALUES(?,?,?,?,?)",
                   (r["slug"], r["num"], price, now(), me["id"]))
        db.commit()
    return {"ok": True, "price": price,
            "fee_permille": RESALE_FEE_PERMILLE, "you_get": price * (1000 - RESALE_FEE_PERMILLE) // 1000}


def api_nft_market_cancel(body, _qs):
    """Снять свой лот с продажи — подарок возвращается владельцу."""
    me = get_human(body.get("user_id"))
    with _lock:
        try:
            r = db.execute("SELECT * FROM nft_market WHERE id=? AND seller_id=?", (int(body.get("id")), me["id"])).fetchone()
        except (TypeError, ValueError):
            r = None
        if not r:
            raise ApiError("Лот не найден", 404)
        db.execute("DELETE FROM nft_market WHERE id=?", (r["id"],))
        cur = db.execute("INSERT INTO nft_gifts(owner_id,slug,num,from_label,ts,seen) VALUES(?,?,?,?,?,1)",
                         (me["id"], r["slug"], r["num"], "Снят с продажи", now()))
        db.commit()
    return {"ok": True, "gift_id": cur.lastrowid}


def api_nft_gift_transfer(body, _qs):
    """Передать подарок другому пользователю (по @username), можно с сообщением и анонимно."""
    me = get_human(body.get("user_id"))
    r = _own_gift(body, me)
    uname = ascii_username(body.get("username"))
    to = q1("SELECT * FROM users WHERE (username=? OR alt_username=?) AND is_bot=0", (uname, uname)) if uname else None
    if not to:
        raise ApiError("Пользователь не найден", 404)
    if to["id"] == me["id"]:
        raise ApiError("Нельзя передать подарок самому себе")
    text = (body.get("text") or "").strip()[:255]
    anon = bool(body.get("anonymous"))
    label = "" if anon else (me["display_name"] or me["username"])
    with _lock:
        db.execute("UPDATE users SET worn_gift=NULL WHERE id=? AND worn_gift=?", (me["id"], r["id"]))
        db.execute("DELETE FROM gift_collection_items WHERE gift_id=?", (r["id"],))
        db.execute("UPDATE nft_gifts SET owner_id=?, from_label=?, seen=0, hidden=0, ts=? WHERE id=?",
                   (to["id"], label, now(), r["id"]))
        db.commit()
    chat = q1("""SELECT c.id FROM chats c
                 JOIN members a ON a.chat_id=c.id AND a.user_id=?
                 JOIN members b ON b.chat_id=c.id AND b.user_id=?
                 WHERE c.type='private'""", (me["id"], to["id"]))
    if chat:
        c = COLLECTIBLES[r["slug"]]
        add_message(chat["id"], me["id"], "🎁 Подарок «%s #%d»%s" % (c["title"], r["num"], ("\n" + text) if text else ""))
    return {"ok": True}



# ───────── Выпуск подарка: покупка → улучшение (случайные модель / узор / фон) → маркет после распродажи ─────────
# 1) Подарок выпускается ограниченным тиражом (supply). Люди покупают ОБЫЧНЫЙ подарок (nft_plain) за price ⭐ и дарят его себе или другу.
# 2) Владелец улучшает его за upgrade ⭐ (или бесплатно, если отправитель оплатил улучшение сразу): подарок становится коллекционным —
#    получает свободный номер, а вместе с ним случайные модель, узор и фон (анимация «рулетки», как в Telegram).
# 3) Пока тираж не распродан, продавать улучшенные подарки на маркете нельзя. Когда купили все — открывается маркет, в магазине у подарка
#    появляется плитка с лентой «Маркет», а по нажатию открываются все NFT этого подарка.
db.execute("""CREATE TABLE IF NOT EXISTS nft_plain(
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  owner_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  slug TEXT NOT NULL, from_label TEXT NOT NULL DEFAULT '', price INTEGER NOT NULL DEFAULT 0,
  prepaid INTEGER NOT NULL DEFAULT 0, ts INTEGER NOT NULL)""")
db.commit()

def _art_uri(svg):
    return "data:image/svg+xml;charset=utf-8," + _sa_quote(svg)


SALE = {   # ВСЕ коллекционные подарки выпускаются по схеме «покупка → улучшение → маркет после распродажи»
    # price — цена обычного подарка, upgrade — цена улучшения (оба в ⭐), art — как выглядит ещё не улучшенный подарок
    "spyagaric": {"price": 100, "upgrade": 50, "art": lambda: _sa_turl("Die Agaric")},
    "westsidesign": {"price": 80, "upgrade": 40, "art": lambda: _ws_turl("Signature")},
    "mythmask": {"price": 50, "upgrade": 25, "art": lambda: _mm_turl("Liquid Metal")},
    "inputkey": {"price": 100, "upgrade": 50, "art": lambda: _art_uri(COLLECTIBLES["inputkey"]["svg"])},
    "resistdog": {"price": 150, "upgrade": 75, "art": lambda: _art_uri(rd_svg(1, False, False))},
}


def _sale_art(slug):
    return SALE[slug]["art"]()


def sale_state(slug):
    c = COLLECTIBLES[slug]
    n = lambda t: q1("SELECT COUNT(*) n FROM %s WHERE slug=?" % t, (slug,))["n"]
    plain, up, mk = n("nft_plain"), n("nft_gifts"), n("nft_market")
    sold = c.get("minted_base", 0) + plain + up + mk
    return {"sold": sold, "left": max(0, c["supply"] - sold), "supply": c["supply"], "sold_out": sold >= c["supply"]}


def market_open(slug):
    """Продавать улучшенные подарки на маркете можно только когда весь тираж распродан."""
    return slug not in SALE or sale_state(slug)["sold_out"]


def sale_item(slug):
    c, sc, st = COLLECTIBLES[slug], SALE[slug], sale_state(slug)
    lo = q1("SELECT MIN(price) lo FROM nft_market WHERE slug=?", (slug,))["lo"]
    return {"k": slug, "name": c["title"], "price": sc["price"], "upgrade": sc["upgrade"], "col": 1, "limited": 1,
            "left": st["left"], "supply": st["supply"], "sold_out": st["sold_out"], "floor": lo or 0, "img": _sale_art(slug)}


def _sale_buy(me, body):
    """Покупка обычного подарка из выпуска: себе (Избранное) или другу в личный чат."""
    slug = body.get("gift")
    sc, c = SALE[slug], COLLECTIBLES[slug]
    try:
        chat_id = int(body.get("chat_id"))
    except (TypeError, ValueError):
        raise ApiError("chat_id обязателен")
    require_member(chat_id, me["id"])
    ch = q1("SELECT * FROM chats WHERE id=?", (chat_id,))
    if not ch or ch["type"] not in ("private", "saved"):
        raise ApiError("Подарки можно отправлять только в личные чаты")
    if ch["type"] == "private":
        other = q1("SELECT user_id FROM members WHERE chat_id=? AND user_id!=?", (chat_id, me["id"]))
        if not other:
            raise ApiError("Получатель не найден")
        owner = other["user_id"]
    else:
        owner = me["id"]
    pre = 1 if body.get("upgrade") else 0
    cost = sc["price"] + (sc["upgrade"] if pre else 0)
    with _lock:
        st = sale_state(slug)
        if st["sold_out"]:
            raise ApiError("Этот подарок распродан — его можно купить на маркете", 409)
        cur = db.execute("UPDATE users SET stars=stars-? WHERE id=? AND stars>=?", (cost, me["id"], cost))
        if cur.rowcount != 1:
            db.rollback()
            raise ApiError("Недостаточно ⭐ — нужно %s" % cost, 402)
        label = "" if owner == me["id"] else (me["display_name"] or me["username"])
        db.execute("INSERT INTO nft_plain(owner_id,slug,from_label,price,prepaid,ts) VALUES(?,?,?,?,?,?)",
                   (owner, slug, label[:40], sc["price"], pre, now()))
        db.commit()
    add_message(chat_id, me["id"], "🎁 Подарок «%s» (%d из %d)\nМожно улучшить до коллекционного: профиль → «Подарки»%s" % (
        c["title"], st["sold"] + 1, st["supply"], " — улучшение уже оплачено" if pre else ""))
    touch(me["id"])
    return {"ok": True, "stars": q1("SELECT stars FROM users WHERE id=?", (me["id"],))["stars"], "left": st["left"] - 1}


def _upgrade_reel(slug, num):
    """Кадры «рулетки» улучшения: случайные экземпляры (картинка + название модели / узора / фона). Финал рисует клиент по карточке.
    У подарков с фиксированным видом (Input Key) рулетки нет — сразу показывается результат."""
    c = COLLECTIBLES[slug]
    if not (c.get("gen") or slug in ("spyagaric", "mythmask", "westsidesign")):
        return []
    out = []
    for n in random.sample(range(1, min(c["supply"], 100000) + 1), 14):
        v = _gift_view(slug, n)
        out.append({"svg": v["thumb"], "hero": v["hero_css"], "model": v["model"][0], "pattern": v["pattern"][0], "bg": v["bg"][0]})
    return out


def api_nft_gift_upgrade(body, _qs):
    """Улучшить обычный подарок до коллекционного: свободный номер + случайные модель / узор / фон."""
    me = get_human(body.get("user_id"))
    try:
        pid = int(body.get("id"))
    except (TypeError, ValueError):
        raise ApiError("Подарок не найден", 404)
    with _lock:
        r = db.execute("SELECT * FROM nft_plain WHERE id=? AND owner_id=?", (pid, me["id"])).fetchone()
        if not r or r["slug"] not in SALE:
            raise ApiError("Подарок не найден", 404)
        slug = r["slug"]
        cost = 0 if r["prepaid"] else SALE[slug]["upgrade"]
        if cost:
            cur = db.execute("UPDATE users SET stars=stars-? WHERE id=? AND stars>=?", (cost, me["id"], cost))
            if cur.rowcount != 1:
                db.rollback()
                raise ApiError("Недостаточно ⭐ — улучшение стоит %s" % cost, 402)
        free = _free_nums(slug)
        if not free:
            db.rollback()
            raise ApiError("Свободных номеров не осталось")
        num = random.choice(free)
        db.execute("DELETE FROM nft_plain WHERE id=?", (pid,))
        cur = db.execute("INSERT INTO nft_gifts(owner_id,slug,num,from_label,ts,seen) VALUES(?,?,?,?,?,1)",
                         (me["id"], slug, num, r["from_label"], now()))
        gid = cur.lastrowid
        db.commit()
    touch(me["id"])
    return {"ok": True, "gift": nft_gift_json(q1("SELECT * FROM nft_gifts WHERE id=?", (gid,))), "reel": _upgrade_reel(slug, num),
            "stars": q1("SELECT stars FROM users WHERE id=?", (me["id"],))["stars"]}


# ───────── Аукционы подарков (по мотивам StarGiftAuctionState / AuctionBidSheet из TDLib и Telegram) ─────────
# Раунд длится round_sec секунд. В конце раунда лучшие per_round ставок выигрывают по подарку (случайный свободный номер),
# ставка списывается. Остальные ставки (⭐ заморожены) переходят в следующий раунд. После последнего раунда
# непобедившие ставки возвращаются. Ставку можно только повышать.
def _free_nums(slug):
    c = COLLECTIBLES[slug]
    used = {r["num"] for r in db.execute("SELECT num FROM nft_gifts WHERE slug=?", (slug,))} | \
           {r["num"] for r in db.execute("SELECT num FROM nft_market WHERE slug=?", (slug,))}
    return [n for n in range(1, c["supply"] + 1) if n not in used]


def auction_create(slug, rounds, per_round, min_bid, round_sec):
    c = COLLECTIBLES.get(slug)
    if not c:
        raise NftError("Неизвестный подарок. Доступно: " + ", ".join(COLLECTIBLES))
    if not (1 <= rounds <= 50 and 1 <= per_round <= 100 and 1 <= min_bid <= 10_000_000 and 10 <= round_sec <= 7 * 86400):
        raise NftError("Раунды 1–50, подарков в раунде 1–100, мин. ставка ≥1 ⭐, раунд от 10 сек до 7 дней")
    with _lock:
        if len(_free_nums(slug)) < rounds * per_round:
            raise NftError("Не хватает свободных номеров в тираже")
        cur = db.execute("""INSERT INTO auctions(slug,rounds,per_round,min_bid,round_sec,round_end,created)
                            VALUES(?,?,?,?,?,?,?)""", (slug, rounds, per_round, min_bid, round_sec, now() + round_sec, now()))
        db.commit()
    return cur.lastrowid


def auction_end_refund(aid, reason="Аукцион завершён"):
    """Закрывает аукцион, возвращает ⭐ по всем оставшимся ставкам."""
    with _lock:
        a = db.execute("SELECT * FROM auctions WHERE id=?", (aid,)).fetchone()
        if not a or a["status"] != "active":
            return 0
        bids = db.execute("SELECT user_id, amount FROM auction_bids WHERE auction_id=?", (aid,)).fetchall()
        for b in bids:
            db.execute("UPDATE users SET stars=stars+? WHERE id=?", (b["amount"], b["user_id"]))
        db.execute("DELETE FROM auction_bids WHERE auction_id=?", (aid,))
        db.execute("UPDATE auctions SET status='ended' WHERE id=?", (aid,))
        db.commit()
    for b in bids:
        try:
            notify_service(b["user_id"], "↩️ %s. Ставка %s ⭐ возвращена на баланс." % (reason, b["amount"]))
        except Exception:
            pass
    return len(bids)


def auction_sweep():
    """Подводит итоги раундов, у которых вышло время."""
    for a in q("SELECT * FROM auctions WHERE status='active' AND round_end<=?", (now(),)):
        won = []
        with _lock:
            top = db.execute("""SELECT user_id, amount FROM auction_bids WHERE auction_id=?
                                ORDER BY amount DESC, ts ASC LIMIT ?""", (a["id"], a["per_round"])).fetchall()
            free = _free_nums(a["slug"])
            random.shuffle(free)
            for b in top:
                if not free:
                    break
                num = free.pop()
                cur = db.execute("INSERT INTO nft_gifts(owner_id,slug,num,from_label,ts) VALUES(?,?,?,?,?)",
                                 (b["user_id"], a["slug"], num, "Аукцион", now()))
                db.execute("DELETE FROM auction_bids WHERE auction_id=? AND user_id=?", (a["id"], b["user_id"]))
                db.execute("INSERT INTO auction_wins(auction_id,user_id,gift_id,round,amount,ts) VALUES(?,?,?,?,?,?)",
                           (a["id"], b["user_id"], cur.lastrowid, a["cur_round"], b["amount"], now()))
                won.append((b["user_id"], b["amount"], num))
            db.execute("UPDATE auctions SET gifts_given=gifts_given+?, cur_round=cur_round+1, round_end=? WHERE id=?",
                       (len(won), now() + a["round_sec"], a["id"]))
            db.commit()
        for uid, amount, num in won:
            try:
                notify_service(uid, "🏆 Вы выиграли раунд %d аукциона: %s #%d за %s ⭐" % (
                    a["cur_round"], COLLECTIBLES[a["slug"]]["title"], num, amount))
            except Exception:
                pass
        if a["cur_round"] >= a["rounds"]:
            auction_end_refund(a["id"], "Аукцион завершён, вы не выиграли")


def _auction_loop():
    while True:
        time.sleep(5)
        try:
            auction_sweep()
        except Exception:
            traceback.print_exc()


def _auction_json(a, me_id=None, detail=False):
    c = COLLECTIBLES[a["slug"]]
    total = a["rounds"] * a["per_round"]
    out = {"id": a["id"], "slug": a["slug"], "title": c["title"], "status": a["status"],
           "rounds": a["rounds"], "current_round": a["cur_round"], "gifts_per_round": a["per_round"],
           "min_bid": a["min_bid"], "total_gifts": total, "gifts_left": max(0, total - a["gifts_given"]),
           "round_end": a["round_end"], "seconds_left": max(0, a["round_end"] - now()) if a["status"] == "active" else 0,
           "svg": _gift_view(a["slug"], 76)["thumb"]}
    if me_id is not None:
        mine = q1("SELECT amount FROM auction_bids WHERE auction_id=? AND user_id=?", (a["id"], me_id))
        out["my_bid"] = mine["amount"] if mine else 0
        out["acquired_count"] = q1("SELECT COUNT(*) n FROM auction_wins WHERE auction_id=? AND user_id=?", (a["id"], me_id))["n"]
    if detail:
        rows = q("""SELECT b.user_id, b.amount, u.username, u.display_name FROM auction_bids b JOIN users u ON u.id=b.user_id
                    WHERE b.auction_id=? ORDER BY b.amount DESC, b.ts ASC LIMIT 20""", (a["id"],))
        out["top_bidders"] = [{"user_id": r["user_id"], "name": r["display_name"] or r["username"], "amount": r["amount"],
                               "winning": i < a["per_round"]} for i, r in enumerate(rows)]
        # сколько нужно поставить, чтобы сейчас попасть в число победителей раунда
        out["cutoff"] = rows[a["per_round"] - 1]["amount"] if len(rows) >= a["per_round"] else 0
        out["my_rank"] = next((i + 1 for i, r in enumerate(rows) if me_id is not None and r["user_id"] == me_id), 0)
    return out


def api_auctions(_body, qs):
    me = get_human(qs.get("user_id"))
