def api_auction_bid(body, _qs):
    me = get_human(body.get("user_id"))
    try:
        aid, amount = int(body.get("id")), int(body.get("amount"))
    except (TypeError, ValueError):
        raise ApiError("Укажите ставку в ⭐")
    with _lock:
        a = db.execute("SELECT * FROM auctions WHERE id=?", (aid,)).fetchone()
        if not a:
            raise ApiError("Аукцион не найден", 404)
        if a["status"] != "active":
            raise ApiError("Аукцион завершён")
        if amount < a["min_bid"]:
            raise ApiError("Минимальная ставка — %s ⭐" % a["min_bid"])
        old = db.execute("SELECT amount FROM auction_bids WHERE auction_id=? AND user_id=?", (aid, me["id"])).fetchone()
        prev = old["amount"] if old else 0
        if amount <= prev:
            raise ApiError("Ставку можно только повысить (сейчас %s ⭐)" % prev)
        cur = db.execute("UPDATE users SET stars=stars-? WHERE id=? AND stars>=?", (amount - prev, me["id"], amount - prev))
        if cur.rowcount != 1:
            db.rollback()
            raise ApiError("Недостаточно ⭐ — нужно ещё %s" % (amount - prev), 402)
        db.execute("""INSERT INTO auction_bids(auction_id,user_id,amount,ts) VALUES(?,?,?,?)
                      ON CONFLICT(auction_id,user_id) DO UPDATE SET amount=excluded.amount, ts=excluded.ts""",
                   (aid, me["id"], amount, now()))
        db.commit()
    touch(me["id"])
    return {"ok": True, "stars": q1("SELECT stars FROM users WHERE id=?", (me["id"],))["stars"],
            "auction": _auction_json(q1("SELECT * FROM auctions WHERE id=?", (aid,)), me["id"], True)}


def auction_admin(cmd, args):
    """/auction slug раундов подарков_в_раунде мин_ставка минут_в_раунде | /auction_end id | /auction (список)"""
    try:
        if cmd == "/auction_end":
            if not args or not args[0].isdigit():
                return "Формат: <code>/auction_end номер</code>"
            n = auction_end_refund(int(args[0]), "Аукцион остановлен администратором")
            return "🛑 Аукцион остановлен, возвращено ставок: %s" % n
        if len(args) >= 5 and all(re.fullmatch(r"\d+", x) for x in args[1:5]):
            aid = auction_create(args[0].lower(), int(args[1]), int(args[2]), int(args[3]), int(args[4]) * 60)
            return "🔨 Аукцион #%s создан: %s, раундов %s × %s подарков, мин. ставка %s ⭐, раунд %s мин." % (
                aid, _html.escape(COLLECTIBLES[args[0].lower()]["title"]), args[1], args[2], args[3], args[4])
    except NftError as e:
        return "❌ " + _html.escape(str(e))
    rows = q("SELECT * FROM auctions WHERE status='active' ORDER BY id")
    lines = ["• #%s <b>%s</b>: раунд %s/%s, осталось подарков %s" % (a["id"], _html.escape(COLLECTIBLES[a["slug"]]["title"]),
             a["cur_round"], a["rounds"], a["rounds"] * a["per_round"] - a["gifts_given"]) for a in rows]
    return ("Активные аукционы:\n" + "\n".join(lines) if lines else "Активных аукционов нет.") + \
           "\n\nСоздать: <code>/auction inputkey 3 2 50 10</code> (подарок, раундов, подарков в раунде, мин. ставка ⭐, минут в раунде)\n" \
           "Остановить: <code>/auction_end 1</code>"



