def api_nft_gifts_of(_body, qs):
    me = get_human(qs.get("user_id"))
    if qs.get("username"):
        u = q1("SELECT id FROM users WHERE username=? OR alt_username=?",
               (ascii_username(qs.get("username")), ascii_username(qs.get("username"))))
    else:
        u = q1("SELECT id FROM users WHERE id=?", (me["id"],))
    if not u:
        return {"gifts": [], "plain": []}
    own = u["id"] == me["id"]
    plain = [{"id": r["id"], "k": r["gift"], "name": GIFT_BY_KEY[r["gift"]][1] if r["gift"] in GIFT_BY_KEY else "Подарок",
              "emoji": GIFT_EMOJI.get(r["gift"], "🎁"), "img": gift_img(r["gift"]), "ts": r["ts"]}
             for r in q("SELECT * FROM user_gifts WHERE owner_id=? ORDER BY id DESC LIMIT 60", (u["id"],))]
    rows = q("SELECT * FROM nft_gifts WHERE owner_id=? %s ORDER BY id DESC LIMIT 60" % ("" if own else "AND hidden=0"), (u["id"],))
    _ow = q1("SELECT username FROM users WHERE id=?", (u["id"],))
    pending = [{"id": r["id"], "slug": r["slug"], "title": COLLECTIBLES[r["slug"]]["title"], "img": _sale_art(r["slug"]),
                "from": r["from_label"], "upgrade": 0 if r["prepaid"] else SALE[r["slug"]]["upgrade"], "prepaid": bool(r["prepaid"])}
               for r in q("SELECT * FROM nft_plain WHERE owner_id=? ORDER BY id DESC LIMIT 60", (u["id"],))
               if r["slug"] in SALE] if own else []
    gifts_out = []
    for r in rows:
        if r["slug"] not in COLLECTIBLES:
            continue
        try:
            tile = _gift_tile(r["slug"], r["num"])
            gifts_out.append({"id": r["id"], "slug": r["slug"], "num": r["num"], "hidden": bool(r["hidden"]),
                              **tile, "collection_ids": _gift_collection_ids(r["id"])})
        except Exception:
            # не роняем весь список из-за одного битого подарка
            gifts_out.append({"id": r["id"], "slug": r["slug"], "num": r["num"], "hidden": bool(r["hidden"]),
                              "title": COLLECTIBLES[r["slug"]].get("title", r["slug"]),
                              "model": "?", "price": "", "bd": "", "tsvg": "", "collection_ids": []})
    return {"worn_gift": _worn(q1("SELECT * FROM users WHERE id=?", (u["id"],))), "plain": plain, "pending": pending,
            "owner": (_ow["username"] if _ow else "") or "",
            "gifts": gifts_out}


# ───────── Структура подарков по образцу TDLib (StarGift / StarGiftAttribute / StarGiftCollection) ─────────
def gift_rarity(pct):
    """Редкость атрибута. В TDLib это upgradedGiftAttributeRarity: либо permille, либо Uncommon/Rare/Epic/Legendary.
    Пороги уровней в архиве не заданы (их присылает сервер Telegram), поэтому здесь свои: ≤1% легендарный, ≤5% эпический, ≤15% редкий."""
    try:
        permille = int(round(float(str(pct).rstrip("%")) * 10))
    except ValueError:
        permille = 1000
    tier = ("legendary" if permille <= 10 else "epic" if permille <= 50 else
            "rare" if permille <= 150 else "uncommon")
    return {"type": "permille", "permille": permille, "tier": tier}


def _gift_backdrop(slug, num):
    """upgradedGiftBackdrop: id, name, colors{center, edge, pattern, text}, rarity."""
    v = _gift_view(slug, num)
    if COLLECTIBLES[slug].get("gen") and slug == "resistdog":
        b = rd_traits(num)["_b"]
        idx = next(i for i, x in enumerate(RD_BGS) if x[0] == b[0])
        return {"id": idx, "name": b[0], "rarity": gift_rarity(b[1]),
                "colors": {"center_color": b[2], "edge_color": b[3], "pattern_color": b[4], "text_color": "#ffffff"}}
    if slug == "mythmask":
        b = mm_traits(num)["_b"]
        idx = next(i for i, x in enumerate(MM_BGS) if x[0] == b[0])
        return {"id": idx, "name": b[0], "rarity": gift_rarity("%g%%" % b[1]),
                "colors": {"center_color": b[2], "edge_color": b[3], "pattern_color": b[4], "text_color": "#ffffff"}}
    if slug == "spyagaric":
        b = sa_traits(num)["_b"]
        idx = next(i for i, x in enumerate(SA_BGS) if x[0] == b[0])
        return {"id": idx, "name": b[0], "rarity": gift_rarity("%g%%" % b[1]),
                "colors": {"center_color": b[2], "edge_color": b[3], "pattern_color": b[4], "text_color": "#ffffff"}}
    if slug == "westsidesign":
        b = ws_traits(num)["_b"]
        idx = next(i for i, x in enumerate(WS_BGS) if x[0] == b[0])
        return {"id": idx, "name": b[0], "rarity": gift_rarity("%g%%" % b[1]),
                "colors": {"center_color": b[2], "edge_color": b[3], "pattern_color": b[4], "text_color": "#ffffff"}}
    look = COLLECTIBLES[slug].get("look") or {}
    return {"id": 0, "name": v["bg"][0], "rarity": gift_rarity(v["bg"][1]),
            "colors": {"center_color": look.get("top", "#1b1b1b"), "edge_color": look.get("bot", "#0e0e0e"),
                       "pattern_color": "#ffffff", "text_color": "#ffffff"}}


def _gift_collection_ids(gift_id):
    return [r["collection_id"] for r in q("SELECT collection_id FROM gift_collection_items WHERE gift_id=?", (gift_id,))]


def upgraded_gift_json(r):
    """Подарок в форме td_api.upgradedGift + userGift: id, title, name(slug-num), number, supply, model/symbol/backdrop, original_details, owner, collection_ids."""
    c = COLLECTIBLES[r["slug"]]
    v = _gift_view(r["slug"], r["num"])
    issued = q1("SELECT COUNT(*) n FROM nft_gifts WHERE slug=?", (r["slug"],))["n"]
    owner = q1("SELECT id, username, display_name FROM users WHERE id=?", (r["owner_id"],))
    return {
        "id": r["id"], "title": c["title"], "name": "%s-%d" % (c["title"].replace(" ", ""), r["num"]),
        "number": r["num"],
        "total_upgraded_count": min(c["supply"], c["minted_base"] + issued), "max_upgraded_count": c["supply"],
        "model": {"name": v["model"][0], "rarity": gift_rarity(v["model"][1])},
        "symbol": {"name": v["pattern"][0], "rarity": gift_rarity(v["pattern"][1])},
        "backdrop": _gift_backdrop(r["slug"], r["num"]),
        "original_details": {"sender": r["from_label"] or "", "receiver_user_id": r["owner_id"],
                             "text": "", "date": r["ts"]},
        "owner": ({"id": owner["id"], "username": owner["username"], "display_name": owner["display_name"]}
                  if owner else None),
        "value_rub": v["value_rub"],
        "is_hidden": bool(r["hidden"]), "collection_ids": _gift_collection_ids(r["id"]),
    }


def api_nft_gift_td(_body, qs):
    get_human(qs.get("user_id"))
    try:
        r = q1("SELECT * FROM nft_gifts WHERE id=?", (int(qs.get("id")),))
    except (TypeError, ValueError):
        r = None
    if not r or r["slug"] not in COLLECTIBLES:
        raise ApiError("Подарок не найден", 404)
    return {"gift": upgraded_gift_json(r)}


MAX_GIFT_COLLECTIONS, MAX_COLLECTION_ITEMS = 10, 100


def _coll_json(c):
    ids = [r["gift_id"] for r in q("SELECT gift_id FROM gift_collection_items WHERE collection_id=? ORDER BY rowid", (c["id"],))]
    return {"id": c["id"], "title": c["title"], "gift_ids": ids, "gift_count": len(ids)}


def _my_collection(body, me):
    try:
        c = q1("SELECT * FROM gift_collections WHERE id=? AND owner_id=?", (int(body.get("collection_id")), me["id"]))
    except (TypeError, ValueError):
        c = None
    if not c:
        raise ApiError("Коллекция не найдена", 404)
    return c


def api_gift_collections(_body, qs):
    me = get_human(qs.get("user_id"))
    uid = me["id"]
    if qs.get("username"):
        u = q1("SELECT id FROM users WHERE username=? OR alt_username=?",
               (ascii_username(qs.get("username")), ascii_username(qs.get("username"))))
        uid = u["id"] if u else 0
    rows = q("SELECT * FROM gift_collections WHERE owner_id=? ORDER BY id", (uid,))
    return {"collections": [_coll_json(c) for c in rows]}


def api_gift_collection_create(body, _qs):
    me = get_human(body.get("user_id"))
    title = (body.get("title") or "").strip()[:30]
    if not title:
        raise ApiError("Введите название коллекции")
    if q1("SELECT COUNT(*) n FROM gift_collections WHERE owner_id=?", (me["id"],))["n"] >= MAX_GIFT_COLLECTIONS:
        raise ApiError("Максимум коллекций: %d" % MAX_GIFT_COLLECTIONS)
    cur = ex("INSERT INTO gift_collections(owner_id,title,ts) VALUES(?,?,?)", (me["id"], title, now()))
    return {"ok": True, "collection": _coll_json(q1("SELECT * FROM gift_collections WHERE id=?", (cur.lastrowid,)))}


def api_gift_collection_rename(body, _qs):
    me = get_human(body.get("user_id"))
    c = _my_collection(body, me)
    title = (body.get("title") or "").strip()[:30]
    if not title:
        raise ApiError("Введите название коллекции")
    ex("UPDATE gift_collections SET title=? WHERE id=?", (title, c["id"]))
    return {"ok": True}


def api_gift_collection_delete(body, _qs):
    me = get_human(body.get("user_id"))
    c = _my_collection(body, me)
    ex("DELETE FROM gift_collection_items WHERE collection_id=?", (c["id"],))
    ex("DELETE FROM gift_collections WHERE id=?", (c["id"],))
    return {"ok": True}


def api_gift_collection_set(body, _qs):
    """Добавить (add=true) или убрать (add=false) свой подарок из коллекции."""
    me = get_human(body.get("user_id"))
    c = _my_collection(body, me)
    try:
        gid = int(body.get("gift_id"))
    except (TypeError, ValueError):
        raise ApiError("gift_id обязателен")
    if not q1("SELECT 1 FROM nft_gifts WHERE id=? AND owner_id=?", (gid, me["id"])):
        raise ApiError("Это не ваш подарок", 403)
    if body.get("add", True):
        n = q1("SELECT COUNT(*) n FROM gift_collection_items WHERE collection_id=?", (c["id"],))["n"]
        if n >= MAX_COLLECTION_ITEMS:
            raise ApiError("В коллекции максимум %d подарков" % MAX_COLLECTION_ITEMS)
        ex("INSERT OR IGNORE INTO gift_collection_items(collection_id,gift_id) VALUES(?,?)", (c["id"], gid))
    else:
        ex("DELETE FROM gift_collection_items WHERE collection_id=? AND gift_id=?", (c["id"], gid))
    return {"ok": True, "collection": _coll_json(c)}



def api_gifts(_body, qs):
    me = get_human(qs.get("user_id"))
    return {"stars": me["stars"] or 0,
            "gifts": [{"k": k, "name": n, "price": pr, "col": col, "img": gift_img(k)} for k, n, pr, col in GIFTS],
            "collectibles": [sale_item(k) for k in SALE]}


def api_gift_send(body, _qs):
    me = get_human(body.get("user_id"))
    if body.get("gift") in SALE:
        return _sale_buy(me, body)
    g = GIFT_BY_KEY.get(body.get("gift"))
    if not g:
        raise ApiError("Неизвестный подарок")
    try:
        chat_id = int(body.get("chat_id"))
    except (TypeError, ValueError):
        raise ApiError("chat_id обязателен")
    require_member(chat_id, me["id"])
    c = q1("SELECT * FROM chats WHERE id=?", (chat_id,))
    if not c or c["type"] != "private":
        raise ApiError("Подарки можно отправлять только в личные чаты")
    other = q1("SELECT user_id FROM members WHERE chat_id=? AND user_id!=?", (chat_id, me["id"]))
    if not other:
        raise ApiError("Получатель не найден")
    with _lock:
        cur = db.execute("UPDATE users SET stars=stars-? WHERE id=? AND stars>=?", (g[2], me["id"], g[2]))
        if cur.rowcount != 1:
            db.rollback()
            raise ApiError("Недостаточно ⭐ — нужно %s" % g[2], 402)
        db.execute("INSERT INTO user_gifts(owner_id,from_id,gift,price,ts) VALUES(?,?,?,?,?)",
                   (other["user_id"], me["id"], g[0], g[2], now()))
        db.commit()
    add_message(chat_id, me["id"], "%s Подарок «%s» (%s ⭐)" % (GIFT_EMOJI.get(g[0], "🎁"), g[1], g[2]))
    touch(me["id"])
    return {"ok": True, "stars": q1("SELECT stars FROM users WHERE id=?", (me["id"],))["stars"]}


