# ───────────────────── API админ-панели (/api/panel/*) ─────────────────────
# Доступ только по ключу в заголовке X-Admin-Key (переменная ADMIN_KEY; если не задана — генерируется и лежит в kv).
# Ключ можно посмотреть командой:  python server.py adminkey
_PANEL_FAILS = []


def _panel_auth():
    t = now()
    _PANEL_FAILS[:] = [x for x in _PANEL_FAILS if t - x < 60]
    if len(_PANEL_FAILS) >= 10:
        raise ApiError("Слишком много неверных попыток, подождите минуту", 429)
    k = (getattr(_req_ctx, "key", "") or "")
    if not k or not hmac.compare_digest(k.encode("utf-8"), admin_key().encode("utf-8")):
        _PANEL_FAILS.append(t)
        raise ApiError("Неверный ключ админ-панели", 403)


def _panel(fn):
    def w(body, qs):
        _panel_auth()
        return fn(body, qs)
    return w


def panel_stats(_b, _q):
    def n(sql, a=()):
        try:
            return q1(sql, a)["n"] or 0
        except Exception:
            return 0
    return {
        "users": n("SELECT COUNT(*) n FROM users WHERE is_bot=0"),
        "online": n("SELECT COUNT(*) n FROM users WHERE is_bot=0 AND last_seen>?", (now() - ONLINE_WINDOW,)),
        "chats": n("SELECT COUNT(*) n FROM chats"),
        "channels": n("SELECT COUNT(*) n FROM chats WHERE type='channel'"),
        "groups": n("SELECT COUNT(*) n FROM chats WHERE type='group'"),
        "messages": n("SELECT COUNT(*) n FROM messages"),
        "stars_total": n("SELECT SUM(stars) n FROM users"),
        "nft_gifts": n("SELECT COUNT(*) n FROM nft_gifts"),
        "nft_usernames": n("SELECT COUNT(*) n FROM nft_usernames"),
        "frozen": n("SELECT COUNT(*) n FROM users WHERE frozen=1"),
        "verified": n("SELECT COUNT(*) n FROM users WHERE verified=1"),
        "admins": len(ADMIN_IDS) + n("SELECT COUNT(*) n FROM admins"),
        "server_time": now(),
    }


def panel_users(_b, qs):
    s = (qs.get("q") or "").strip().lstrip("@")
    try:
        lim = max(1, min(200, int(qs.get("limit") or 50)))
    except ValueError:
        lim = 50
    cols = ("id,username,display_name,verified,grib,scam,frozen,stars,premium,phone,last_seen,created")
    if s:
        like = "%" + s.replace("%", "").replace("_", "") + "%"
        rows = q("SELECT %s FROM users WHERE is_bot=0 AND (username LIKE ? OR display_name LIKE ? OR phone LIKE ? OR CAST(id AS TEXT)=?) "
                 "ORDER BY id DESC LIMIT ?" % cols, (like, like, like, s, lim))
    else:
        rows = q("SELECT %s FROM users WHERE is_bot=0 ORDER BY id DESC LIMIT ?" % cols, (lim,))
    return {"users": [dict(r) for r in rows]}


PANEL_FLAGS = ("verified", "grib", "scam", "frozen", "premium")


def panel_user_flag(body, _q):
    flag = body.get("flag")
    if flag not in PANEL_FLAGS:
        raise ApiError("Неизвестный флаг")
    uid = int(body.get("id") or 0)
    if not q1("SELECT 1 FROM users WHERE id=? AND is_bot=0", (uid,)):
        raise ApiError("Пользователь не найден", 404)
    val = 1 if body.get("value") else 0
    ex("UPDATE users SET %s=? WHERE id=?" % flag, (val, uid))
    if flag == "premium" and val:
        ex("UPDATE users SET premium_until=NULL WHERE id=?", (uid,))
    return {"ok": True, "id": uid, "flag": flag, "value": val}


def panel_stars(body, _q):
    uid = int(body.get("id") or 0)
    try:
        delta = int(body.get("delta"))
    except (TypeError, ValueError):
        raise ApiError("Укажите число")
    if delta == 0 or abs(delta) > 1000000000:
        raise ApiError("Недопустимое количество")
    if not q1("SELECT 1 FROM users WHERE id=? AND is_bot=0", (uid,)):
        raise ApiError("Пользователь не найден", 404)
    ex("UPDATE users SET stars=MAX(0,stars+?) WHERE id=?", (delta, uid))
    return {"ok": True, "stars": q1("SELECT stars FROM users WHERE id=?", (uid,))["stars"]}


def panel_admins(_b, _q):
    out = [{"tg_id": i, "owner": True, "perms": sorted(ALL_PERMS)} for i in sorted(ADMIN_IDS)]
    for r in q("SELECT tg_id FROM admins ORDER BY rowid"):
        if r["tg_id"] not in ADMIN_IDS:
            out.append({"tg_id": r["tg_id"], "owner": False, "perms": sorted(get_perms(r["tg_id"]))})
    return {"admins": out, "all_perms": ALL_PERMS}


def panel_admin_set(body, _q):
    tid = int(body.get("tg_id") or 0)
    if tid <= 0 or tid in ADMIN_IDS:
        raise ApiError("Недопустимый Telegram ID (владельцев менять нельзя)")
    perms = {p for p in (body.get("perms") or []) if p in ALL_PERMS}
    set_perms(tid, perms)
    return {"ok": True, "perms": sorted(perms)}


def panel_admin_remove(body, _q):
    tid = int(body.get("tg_id") or 0)
    if tid in ADMIN_IDS:
        raise ApiError("Владельца удалить нельзя")
    ex("DELETE FROM admins WHERE tg_id=?", (tid,))
    return {"ok": True}


