def start_tunnel():
    """Запускает cloudflared (если установлен) и печатает общую ссылку."""
    import shutil
    import subprocess
    exe = shutil.which("cloudflared")
    if os.environ.get("NO_TUNNEL") or not exe:
        if not os.environ.get("NO_TUNNEL"):
            print("cloudflared не найден (pkg install cloudflared) — работаю только локально")
        return None
    proc = subprocess.Popen(
        [exe, "tunnel", "--no-autoupdate", "--url", "http://localhost:%d" % PORT],
        stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)

    def reader():
        shown = False
        for line in proc.stdout:
            m = re.search(r"https://[a-z0-9-]+\.trycloudflare\.com", line)
            if m and not shown:
                shown = True
                print("\n" + "=" * 52)
                print("  Ссылка для всех:  " + m.group(0))
                print("=" * 52 + "\n")

    threading.Thread(target=reader, daemon=True).start()
    return proc


def _start_keepalive():
    """Free Render усыпляет сервис через ~15 мин без запросов (и бот на long polling замолкает).
    Раз в 10 минут пингуем свой публичный адрес. Работает только на Render (есть RENDER_EXTERNAL_URL)."""
    url = os.environ.get("RENDER_EXTERNAL_URL", "").rstrip("/")
    if not url or os.environ.get("NO_KEEPALIVE"):
        return

    def loop():
        while True:
            time.sleep(600)
            try:
                urllib.request.urlopen(url + "/ping", timeout=20).read()
            except Exception:
                pass

    threading.Thread(target=loop, daemon=True).start()


def cli_verify():
    """python server.py verify <username>   — выдать галочку
       python server.py unverify <username> — забрать галочку"""
    import sys
    if len(sys.argv) >= 3 and sys.argv[1] in ("nftgive", "nftrevoke"):
        try:
            if sys.argv[1] == "nftrevoke":
                owner, new = nft_revoke(sys.argv[2])
                print("Имя @%s забрано у %s" % (ascii_username(sys.argv[2]), nft_owner_label(owner)))
            else:
                user, err = nft_resolve_user(sys.argv[3] if len(sys.argv) > 3 else "")
                if err:
                    print(err)
                else:
                    ton = _num(sys.argv[4]) if len(sys.argv) > 4 else 0.0
                    xtr = _num(sys.argv[5], int) if len(sys.argv) > 5 else 0
                    name, how = nft_give(sys.argv[2], user, ton, xtr)
                    print("@%s %s @%s" % (name, "куплен пользователем" if how == "bought" else "выдан пользователю", user["username"]))
        except (NftError, ValueError) as e:
            print("Ошибка:", e)
        return True
    if len(sys.argv) >= 2 and sys.argv[1] == "adminkey":
        print("Ключ админ-панели:", admin_key())
        return True
    if len(sys.argv) >= 3 and sys.argv[1] in ("scam", "unscam"):
        uname = ascii_username(sys.argv[2])
        u = q1("SELECT id FROM users WHERE username=?", (uname,))
        if not u:
            print("Пользователь @%s не найден" % uname)
        else:
            ex("UPDATE users SET scam=? WHERE id=?", (1 if sys.argv[1] == "scam" else 0, u["id"]))
            print("Метка SCAM %s у @%s" % ("выдана" if sys.argv[1] == "scam" else "снята", uname))
        return True
    if len(sys.argv) >= 3 and sys.argv[1] in ("grib", "ungrib"):
        uname = ascii_username(sys.argv[2])
        u = q1("SELECT id FROM users WHERE username=?", (uname,))
        if not u:
            print("Пользователь @%s не найден" % uname)
        else:
            ex("UPDATE users SET grib=? WHERE id=?", (1 if sys.argv[1] == "grib" else 0, u["id"]))
            print("Грибочек %s у @%s" % ("выдан" if sys.argv[1] == "grib" else "снят", uname))
        return True
    if len(sys.argv) >= 5 and sys.argv[1] == "nftmarket":
        try:
            nums = nft_market_mint(sys.argv[2].lower(), int(sys.argv[3]), int(sys.argv[4]))
            print("На маркет выпущено %s шт. по %s ⭐" % (len(nums), sys.argv[4]))
        except (NftError, ValueError) as e:
            print("Ошибка:", e)
        return True
    if len(sys.argv) >= 3 and sys.argv[1] == "nftgift":
        try:
            user, err = nft_resolve_user(sys.argv[2])
            if err:
                print(err)
            else:
                slug, num, frm_ = _parse_nftgift_args(sys.argv[3:])
                _gid, num = nft_gift_give(user["id"], slug, num, frm_)
                print("Выдан %s #%s пользователю @%s" % (COLLECTIBLES[slug]["title"], num, user["username"]))
        except NftError as e:
            print("Ошибка:", e)
        return True
    if len(sys.argv) >= 3 and sys.argv[1] in ("badge", "unbadge"):
        t = badge_target(sys.argv[2])
        if not t:
            print("Не найден:", sys.argv[2])
        else:
            txt = " ".join(sys.argv[3:]).strip()[:60] or BADGE_DEFAULT
            ex("UPDATE %s SET badge=? WHERE id=?" % t[0], (txt if sys.argv[1] == "badge" else None, t[1]))
            print("Значок </> %s у %s" % ("выдан" if sys.argv[1] == "badge" else "снят", t[2]))
        return True
    if len(sys.argv) >= 3 and sys.argv[1] in ("verify", "unverify"):
        uname = ascii_username(sys.argv[2])
        u = q1("SELECT id FROM users WHERE username=?", (uname,))
        if not u:
            print("Пользователь @%s не найден" % uname)
        else:
            ex("UPDATE users SET verified=? WHERE id=?", (1 if sys.argv[1] == "verify" else 0, u["id"]))
            print("Галочка %s у @%s" % ("выдана" if sys.argv[1] == "verify" else "снята", uname))
        return True
    return False


# ---------------------------------------------------------------------------
# Перенесено на Python из архивов (generated.zip, Stars.zip, Components.zip).
# ---------------------------------------------------------------------------
# 1) generated.zip -> полный Python-порт TL-классов Telegram (TlGen_*, TL_*, 2203 конструктора).
#    Исходник модуля вшит в конец файла (блок TLGEN_BLOB), загружается лениво:
#        tlgen = get_tlgen()
#        data = tlgen.TL_birthday(day=1, month=2, year=None).serialize()
def get_tlgen():
    import sys, types, base64, lzma
    mod = sys.modules.get("tlgen")
    if mod is not None:
        return mod
    with open(os.path.abspath(__file__), encoding="utf-8") as f:
        text = f.read()
    a = text.index("# TLGEN_BLOB_BEGIN\n") + len("# TLGEN_BLOB_BEGIN\n")
    b = text.index("# TLGEN_BLOB_END", a)
    data = "".join(l[2:] for l in text[a:b].splitlines() if l.startswith("# "))
    source = lzma.decompress(base64.b64decode(data)).decode("utf-8")
    mod = types.ModuleType("tlgen")
    mod.__file__ = os.path.abspath(__file__)
    sys.modules["tlgen"] = mod
    try:
        exec(compile(source, "tlgen(server.py)", "exec"), mod.__dict__)
    except Exception:
        sys.modules.pop("tlgen", None)
        raise
    return mod


# 2) Stars.zip: BagRandomizer.java (чистая логика, без Android).
class BagRandomizer:
    """Выдаёт элементы по кругу в случайном порядке («мешок»), next() отдаёт предыдущий выбранный."""

    def __init__(self, items=None):
        self._bag = list(items or [])
        self._shuffled = list(self._bag)
        self._index = 0
        self._random = random.Random()
        self._reshuffle_if_end = True
        self._next = None
        self._reshuffle()
        self.next()

    def next(self):
        if not self._bag:
            return None
        result = self._next
        if self._index >= len(self._shuffled):
            if self._reshuffle_if_end:
                self._reshuffle()
            else:
                self._index = 0
        self._next = self._shuffled[self._index]
        self._index += 1
        return result

    def set_reshuffle_if_end(self, value):
        self._reshuffle_if_end = bool(value)

    def get_next(self):
        return self._next

    def reset(self):
        self._index = 0
        self.next()

    def _reshuffle(self):
        self._random.shuffle(self._shuffled)
        self._index = 0


