def mix_hashes(*values):
    """FNV-1a 64 по little-endian представлению int64; результат 63-битный, 0 заменяется на 1."""
    h = 0xCBF29CE484222325
    for v in values:
        for byte in (int(v) & 0xFFFFFFFFFFFFFFFF).to_bytes(8, "little"):
            h = ((h ^ byte) * 0x100000001B3) & 0xFFFFFFFFFFFFFFFF
    s = h & 0x7FFFFFFFFFFFFFFF
    return s or 1


# --- giftclaim/auth.go ---
def init_data_hash(values, bot_token):
    """values: dict ключ -> значение (без учёта поля hash). Возвращает hex HMAC по схеме Telegram WebApp."""
    keys = sorted((k for k in values if k != "hash"), key=lambda k: k.encode("utf-8"))
    check = "\n".join("%s=%s" % (k, values[k]) for k in keys)
    secret = _hmac.new(b"WebAppData", bot_token.encode("utf-8"), _hashlib.sha256).digest()
    return _hmac.new(secret, check.encode("utf-8"), _hashlib.sha256).hexdigest()


def verify_init_data(raw, bot_token, max_age=0, now=None):
    """Проверка подписи Mini App initData. max_age и now в секундах. Ошибки — ValueError."""
    raw, bot_token = (raw or "").strip(), (bot_token or "").strip()
    if not raw or not bot_token:
        raise ValueError("Mini App authorization is missing")
    values = {}
    for k, v in _parse_qsl(raw, keep_blank_values=True):
        values.setdefault(k, v)
    if not values.get("hash"):
        raise ValueError("Mini App authorization is invalid")
    if not _hmac.compare_digest(values["hash"].encode(), init_data_hash(values, bot_token).encode()):
        raise ValueError("Mini App signature mismatch")
    try:
        auth_date = int(values.get("auth_date", ""))
    except ValueError:
        auth_date = 0
    if auth_date <= 0:
        raise ValueError("Mini App auth_date is invalid")
    now = time.time() if now is None else now
    if auth_date > now + 60 or (max_age > 0 and now - auth_date > max_age):
        raise ValueError("Mini App authorization expired")
    try:
        user = json.loads(values.get("user", ""))
        uid = int(user["id"])
    except (ValueError, KeyError, TypeError):
        raise ValueError("Mini App user is invalid")
    if uid <= 0:
        raise ValueError("Mini App user is invalid")
    return {"id": uid, "first_name": user.get("first_name", ""),
            "last_name": user.get("last_name", ""), "username": user.get("username", "")}


# --- stargifts/local_withdrawal.go ---
LOCAL_WITHDRAWAL_TTL = 15 * 60


class LocalWithdrawalInsecureBaseURL(ValueError):
    """Обычный HTTP вне loopback: ссылки на вывод — bearer-токены, по открытой сети их пускать нельзя."""


def _loopback_host(host):
    host = (host or "").strip()
    if host.lower() == "localhost":
        return True
    try:
        return _ipaddress.ip_address(host).is_loopback
    except ValueError:
        return False


class LocalWithdrawalProvider:
    def __init__(self, public_base_url, name="telesrv-local"):
        base = (public_base_url or "").strip().rstrip("/")
        try:
            u = _urlparse(base)
            host = u.hostname
        except ValueError:
            u, host = None, None
        if (u is None or not u.netloc or not host or "@" in u.netloc or u.query or u.fragment
                or u.scheme not in ("http", "https")):
            raise ValueError("invalid local star gift withdrawal base URL")
        if u.scheme == "http" and not _loopback_host(host):
            raise LocalWithdrawalInsecureBaseURL(
                "local star gift withdrawal base URL requires HTTPS outside loopback")
        self.public_base_url = base
        self._name = name

    @classmethod
    def custom_fragment(cls, public_base_url):
        return cls(public_base_url, name="customfragment-ton-mainnet")

    @property
    def name(self):
        return self._name or "telesrv-local"

    def create_withdrawal(self, _request=None):
        return self._create("gift-withdrawal")

    def create_revenue_withdrawal(self, _request=None):
        return self._create("revenue-withdrawal")

    def _create(self, path):
        token = _b64.urlsafe_b64encode(os.urandom(32)).rstrip(b"=").decode()
        return {"request_id": token,
                "url": "%s/%s/%s" % (self.public_base_url, path, _quote(token, safe="")),
                "expires_at": int(time.time() + LOCAL_WITHDRAWAL_TTL)}


# --- giftpack/assets.go (адаптация owpengram-server, Apache-2.0) ---
GIFTPACK_MAX_ARCHIVE_BYTES = 32 << 20
_GP_MAX_ASSET = 8 << 20
_GP_MAX_MANIFEST = 1 << 20
_GP_MAX_ENTRIES = 512
_GP_MAX_UNCOMPRESSED = 128 << 20


def valid_asset_path(name):
    return (name != "" and not any(c in name for c in "\\:\x00") and not name.startswith("/")
            and _posixpath.normpath(name) == name and name not in (".", "..")
            and not name.startswith("../"))


class ZipAssetResolver:
    """Читает ресурсы набора подарков из zip; pack.json обязателен в корне архива."""

    def __init__(self, data):
        if not data or len(data) > GIFTPACK_MAX_ARCHIVE_BYTES:
            raise ValueError("pack zip must be 1..%d bytes" % GIFTPACK_MAX_ARCHIVE_BYTES)
        try:
            zf = _zipfile.ZipFile(_io.BytesIO(data))
        except _zipfile.BadZipFile as e:
            raise ValueError("open pack zip: %s" % e)
        infos = zf.infolist()
        if not infos or len(infos) > _GP_MAX_ENTRIES:
            raise ValueError("pack zip has too many entries")
        files, total = {}, 0
        for info in infos:
            name = info.filename
            if name.endswith("/"):
                if not valid_asset_path(name[:-1]):
                    raise ValueError("invalid pack directory %r" % name)
                continue
            is_symlink = (info.external_attr >> 16) & 0o170000 == 0o120000
            if not valid_asset_path(name) or is_symlink:
                raise ValueError("invalid pack entry %r" % name)
            if name in files:
                raise ValueError("duplicate pack entry %r" % name)
            limit = _GP_MAX_MANIFEST if name == "pack.json" else _GP_MAX_ASSET
            if info.file_size == 0 or info.file_size > limit or total > _GP_MAX_UNCOMPRESSED - info.file_size:
                raise ValueError("pack entry %r exceeds size limit" % name)
            total += info.file_size
            files[name] = info
        if "pack.json" not in files:
            raise ValueError("pack.json is required at zip root")
        self._zf, self._files = zf, files

    def manifest(self):
        return self.open("pack.json")

    def open(self, path):
        if not valid_asset_path(path):
            raise ValueError("invalid pack asset path %r" % path)
        info = self._files.get(path)
        if info is None:
            raise ValueError("asset %r not found in pack" % path)
        limit = _GP_MAX_MANIFEST if path == "pack.json" else _GP_MAX_ASSET
        with self._zf.open(info) as f:
            data = f.read(limit + 1)
        if len(data) > limit:
            raise ValueError("%r in pack exceeds %d bytes" % (path, limit))
        return data


class MapAssetResolver(dict):
    """Для проверки сгенерированного набора без zip."""

    def open(self, path):
        if path not in self:
            raise ValueError("asset %r not found in pack" % path)
        return self[path]


