MAX_STAR_GIFT_COLLECTIBLE_ATTRIBUTES_PER_KIND = 200
MAX_STAR_GIFT_CATALOG_SIZE = 500
MAX_SAVED_STAR_GIFTS_LIMIT = 100
MAX_STAR_GIFTS_OFFSET_BYTES = 256

STAR_GIFT_ANIMATION_TGS = "tgs"
STAR_GIFT_ANIMATION_LOTTIE = "lottie"

STAR_GIFT_COLLECTIBLE_MODEL = "model"
STAR_GIFT_COLLECTIBLE_PATTERN = "pattern"
STAR_GIFT_COLLECTIBLE_BACKDROP = "backdrop"

STAR_GIFT_RARITY_PERMILLE = "permille"
STAR_GIFT_RARITY_UNCOMMON = "uncommon"
STAR_GIFT_RARITY_RARE = "rare"
STAR_GIFT_RARITY_EPIC = "epic"
STAR_GIFT_RARITY_LEGENDARY = "legendary"

PEER_TYPE_USER = "user"
PEER_TYPE_CHANNEL = "channel"

DOC_ATTR_IMAGE_SIZE = "image_size"
DOC_ATTR_STICKER = "sticker"
DOC_ATTR_CUSTOM_EMOJI = "custom_emoji"
DOC_ATTR_FILENAME = "filename"
PHOTO_SIZE_KIND_PATH = "path"


def _g(obj, name, default=None):
    """Доступ к полю и у dict, и у объекта (store/domain-значения приходят в любом виде)."""
    if obj is None:
        return default
    if isinstance(obj, dict):
        return obj.get(name, default)
    return getattr(obj, name, default)


def user_visible_text(value, fallback=""):
    """Аналог branding.UserVisibleText: переопределите, если нужен ребрендинг видимых названий."""
    return value if value else fallback


def normalize_stars_transaction_query(query):
    """Аналог domain.NormalizeStarsTransactionQuery (в архивах нет): по умолчанию без изменений."""
    return query


def random_positive_int64():
    value = int.from_bytes(os.urandom(8), "little") & 0x7FFFFFFFFFFFFFFF
    return value or 1


def _blob_name(blobs):
    name = getattr(blobs, "name", "")
    return name() if callable(name) else name


def _json_compact(text):
    """Как Go json.Compact: убирает пробелы вне строк, не трогая порядок ключей и запись чисел."""
    if isinstance(text, (bytes, bytearray)):
        text = bytes(text).decode("utf-8")
    out, start, in_str, esc = [], 0, False, False
    for i, ch in enumerate(text):
        if in_str:
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == '"':
                in_str = False
        elif ch == '"':
            in_str = True
        elif ch in " \t\r\n":
            out.append(text[start:i])
            start = i + 1
    out.append(text[start:])
    return "".join(out)


def _json_reject_constant(name):
    raise ValueError("invalid JSON constant %s" % name)


def _json_valid(text):
    try:
        json.loads(text, parse_constant=_json_reject_constant)
        return True
    except ValueError:
        return False


_JSON_DEC = json.JSONDecoder()
_JSON_WS = " \t\r\n"


def _json_skip_ws(text, i):
    while i < len(text) and text[i] in _JSON_WS:
        i += 1
    return i


def _json_object_raw_fields(text):
    """Верхний уровень JSON-объекта -> {ключ: сырой текст значения} (как map[string]json.RawMessage)."""
    i = _json_skip_ws(text, 0)
    if i >= len(text) or text[i] != "{":
        raise ValueError("not a JSON object")
    i = _json_skip_ws(text, i + 1)
    fields = {}
    if text[i] == "}":
        return fields
    while True:
        key, i = _JSON_DEC.raw_decode(text, i)
        i = _json_skip_ws(text, i)
        if text[i] != ":":
            raise ValueError("expected ':'")
        i = _json_skip_ws(text, i + 1)
        _, end = _JSON_DEC.raw_decode(text, i)
        fields[key] = text[i:end]
        i = _json_skip_ws(text, end)
        if text[i] == ",":
            i = _json_skip_ws(text, i + 1)
            continue
        if text[i] == "}":
            return fields
        raise ValueError("expected ',' or '}'")


def _json_array_raw_elements(text):
    """Сырой текст элементов JSON-массива (как []json.RawMessage); null -> пустой список."""
    i = _json_skip_ws(text, 0)
    if text[i:i + 4] == "null":
        return []
    if i >= len(text) or text[i] != "[":
        raise ValueError("not a JSON array")
    i = _json_skip_ws(text, i + 1)
    items = []
    if text[i] == "]":
        return items
    while True:
        _, end = _JSON_DEC.raw_decode(text, i)
        items.append(text[i:end])
        i = _json_skip_ws(text, end)
        if text[i] == ",":
            i = _json_skip_ws(text, i + 1)
            continue
        if text[i] == "]":
            return items
        raise ValueError("expected ',' or ']'")


def _go_num(value):
    """Число как его пишет encoding/json: целые без «.0»."""
    value = float(value)
    if value == int(value) and abs(value) < 1e15:
        return str(int(value))
    return repr(value)


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _is_num(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)


