def validate_star_gift_collectible_draft(write):
    """Аналог domain.ValidateStarGiftCollectibleDraft по правилам из комментариев giftpack/manifest.go."""
    if _g(write, "gift_id", 0) <= 0:
        raise StarGiftCollectibleInvalid()
    if _g(write, "upgrade_stars", 0) <= 0 or _g(write, "supply_total", 0) <= 0:
        raise StarGiftCollectibleInvalid()
    if not str(_g(write, "slug_prefix", "")).strip():
        raise StarGiftCollectibleInvalid()
    for kind, key in ((STAR_GIFT_COLLECTIBLE_MODEL, "models"), (STAR_GIFT_COLLECTIBLE_PATTERN, "patterns"),
                      (STAR_GIFT_COLLECTIBLE_BACKDROP, "backdrops")):
        items = _g(write, key) or []
        if not items or len(items) > MAX_STAR_GIFT_COLLECTIBLE_ATTRIBUTES_PER_KIND:
            raise StarGiftCollectibleInvalid()
        for a in items:
            if _g(a, "kind") != kind or not str(_g(a, "name", "")).strip():
                raise StarGiftCollectibleInvalid()
            rk, pm, crafted = _g(a, "rarity_kind"), _g(a, "rarity_permille", 0), _g(a, "crafted", False)
            if rk == STAR_GIFT_RARITY_PERMILLE:
                if crafted or not 0 <= pm <= 1000:
                    raise StarGiftCollectibleInvalid()
            elif not (crafted and kind == STAR_GIFT_COLLECTIBLE_MODEL and pm == 0 and rk in (
                    STAR_GIFT_RARITY_UNCOMMON, STAR_GIFT_RARITY_RARE, STAR_GIFT_RARITY_EPIC,
                    STAR_GIFT_RARITY_LEGENDARY)):
                raise StarGiftCollectibleInvalid()
            if kind != STAR_GIFT_COLLECTIBLE_BACKDROP and _g(a, "animation") is None:
                raise StarGiftCollectibleInvalid()


