PREMIUM_BOT_DEFAULT_USER_ID = int(os.environ.get("PREMIUM_BOT_USER_ID", "0") or 0)
PREMIUM_BOT_DEFAULT_USERNAME = os.environ.get("PREMIUM_BOT_USERNAME", "PremiumBot")


@_dc.dataclass
class PremiumPlan:
    months: int = 0
    label: str = ""
    stars: int = 0
    enabled: bool = True
    sort_order: int = 0

    def valid(self):
        return self.months > 0


class PremiumStore(object):
    """Интерфейс store.PremiumStore (реализуйте поверх sqlite). Имена — snake_case от Go-методов."""

    def plans(self): raise NotImplementedError
    def plan(self, months): raise NotImplementedError          # -> (plan, found)
    def sync_plans(self, plans): raise NotImplementedError
    def upsert_premium_plan(self, req): raise NotImplementedError
    def issue_premium_payment_form(self, form): raise NotImplementedError
    def purchase_premium(self, req): raise NotImplementedError
    def active_premium_entitlements(self, user_id, now): raise NotImplementedError
    def premium_entitlements(self, user_id, limit): raise NotImplementedError
    def premium_purchase_history(self, user_id, limit): raise NotImplementedError
    def premium_payment(self, payment_intent_id): raise NotImplementedError   # -> (details, found)
    def sweep_premium_entitlements(self, now, limit): raise NotImplementedError
    def grant_premium_entitlement(self, req): raise NotImplementedError       # -> (entitlement, user)
    def revoke_premium_entitlements(self, req): raise NotImplementedError
    def refund_premium_payment(self, req): raise NotImplementedError


def _plan_sort_key(plan):
    return (_g(plan, "sort_order", 0), _g(plan, "months", 0))


def _plan_valid(plan):
    check = _g(plan, "valid")
    if callable(check):
        return bool(check())
    return _g(plan, "months", 0) > 0


class PremiumService(object):
    """Граница приложения для покупок Telegram Premium, подарков и долговременных прав."""

    def __init__(self, store, bot_user_id=0, username="", stars=None):
        if bot_user_id <= 0:
            bot_user_id = PREMIUM_BOT_DEFAULT_USER_ID
        username = (username or "").strip()
        if username.startswith("@"):
            username = username[1:]
        if not username:
            username = PREMIUM_BOT_DEFAULT_USERNAME
        self.store, self.bot_user_id, self.username, self.stars = store, bot_user_id, username, stars

    def get_bot_user_id(self):
        return self.bot_user_id if self.bot_user_id > 0 else PREMIUM_BOT_DEFAULT_USER_ID

    def get_bot_username(self):
        return self.username or PREMIUM_BOT_DEFAULT_USERNAME

    def plans(self):
        if self.store is None:
            return []
        out = [p for p in self.store.plans() if _g(p, "enabled", False) and _plan_valid(p)]
        out.sort(key=_plan_sort_key)
        return out

    def catalog(self):
        """Включённые и выключенные планы для операторской панели."""
        if self.store is None:
            return []
        plans = list(self.store.plans())
        plans.sort(key=_plan_sort_key)
        return plans

    def plan(self, months):
        if self.store is None or months <= 0:
            raise PremiumPlanUnavailable()
        plan, found = self.store.plan(months)
        if not found or not _g(plan, "enabled", False) or not _plan_valid(plan):
            raise PremiumPlanUnavailable()
        return plan

    def sync_plans(self, plans):
        if self.store is None:
            raise GiftError("premium store is not configured")
        if not plans:
            return None
        seen = set()
        for plan in plans:
            if not _plan_valid(plan):
                raise PremiumPlanInvalid()
            months = _g(plan, "months", 0)
            if months in seen:
                raise PremiumPlanInvalid()
            seen.add(months)
        return self.store.sync_plans(plans)

    def upsert_plan(self, req):
        if self.store is None:
            raise GiftError("premium store is not configured")
        for field in ("label", "reason", "command_key"):
            value = _g(req, field, "")
            if isinstance(value, str):
                if isinstance(req, dict):
                    req[field] = value.strip()
                else:
                    setattr(req, field, value.strip())
        check = _g(req, "valid")
        if callable(check) and not check():
            raise PremiumPlanInvalid()
        return self.store.upsert_premium_plan(req)

    def issue_payment_form(self, form):
        check = _g(form, "valid")
        if self.store is None or (callable(check) and not check()):
            raise PremiumFormInvalid()
        if self.stars is not None:
            debit = _g(form, "effective_debit_stars")
            if (debit() if callable(debit) else debit is None or debit):
                self.stars.get_balance(_g(form, "buyer_user_id", 0))
        return self.store.issue_premium_payment_form(form)

    def balance(self, user_id):
        if self.stars is None or user_id <= 0:
            raise StarsInvalidAmount()
        return self.stars.get_balance(user_id)

    def purchase(self, req):
        if self.store is None:
            raise PremiumPlanUnavailable()
        return self.store.purchase_premium(req)

    def active_entitlements(self, user_id, now):
        if self.store is None or user_id <= 0:
            return []
        return self.store.active_premium_entitlements(user_id, now)

    def entitlements(self, user_id, limit):
        if self.store is None or user_id <= 0:
            return []
        return self.store.premium_entitlements(user_id, limit)

    def purchase_history(self, user_id, limit):
        if self.store is None or user_id <= 0:
            return []
        return self.store.premium_purchase_history(user_id, limit)

    def payment(self, payment_intent_id):
        """-> (details, found)"""
        if self.store is None or payment_intent_id <= 0:
            return None, False
        return self.store.premium_payment(payment_intent_id)

    def sweep_expired(self, now, limit):
        if self.store is None:
            return []
        return self.store.sweep_premium_entitlements(now, limit)

    def grant(self, req):
        if self.store is None:
            raise PremiumPlanUnavailable()
        return self.store.grant_premium_entitlement(req)

    def revoke(self, req):
        if self.store is None:
            raise PremiumPlanUnavailable()
        return self.store.revoke_premium_entitlements(req)

    def refund(self, req):
        if self.store is None:
            raise PremiumPaymentNotFound()
        return self.store.refund_premium_payment(req)


# ===========================================================================
# 4d) stargifts/animation.go
# ===========================================================================
def is_gzip(data):
    return len(data) >= 2 and data[0] == 0x1F and data[1] == 0x8B


def decompress_single_tgs(data):
    """Один gzip-член без хвоста и не больше MAX_STAR_GIFT_LOTTIE_BYTES (иначе StarGiftFileInvalid)."""
    try:
        d = _zlib.decompressobj(16 + _zlib.MAX_WBITS)
        raw = d.decompress(bytes(data), MAX_STAR_GIFT_LOTTIE_BYTES + 1)
        if not d.eof or d.unconsumed_tail or d.unused_data or len(raw) > MAX_STAR_GIFT_LOTTIE_BYTES:
            raise StarGiftFileInvalid()
        return raw
    except _zlib.error:
        raise StarGiftFileInvalid()


def gzip_lottie(data):
    """Детерминированный gzip: уровень 9, mtime=0, OS=255 (как у Go-версии)."""
    return _gzip.compress(bytes(data), compresslevel=9, mtime=0)


def contains_lottie_expression(value):
    if isinstance(value, dict):
        for key, child in value.items():
            if key == "x" and isinstance(child, str) and child.strip():
                return True
            if contains_lottie_expression(child):
                return True
    elif isinstance(value, list):
        for child in value:
            if contains_lottie_expression(child):
                return True
    return False


def normalize_and_validate_lottie(data, allow_expressions):
    """-> (compact_bytes, meta dict {v,w,h,fr,ip,op}); ошибки — StarGiftFileInvalid."""
    data = bytes(data)
    if data.startswith(b"\xef\xbb\xbf"):
        data = data[3:]
    data = data.strip()
    if not data or len(data) > MAX_STAR_GIFT_LOTTIE_BYTES:
        raise StarGiftFileInvalid()
    try:
        text = data.decode("utf-8")
        root = json.loads(text, parse_constant=_json_reject_constant)
    except ValueError:
        raise StarGiftFileInvalid()
    if not isinstance(root, dict):
        raise StarGiftFileInvalid()
    if not allow_expressions and contains_lottie_expression(root):
        raise StarGiftFileInvalid("%s: expressions are not allowed" % StarGiftFileInvalid.default)
    version = root.get("v")
    w, h = root.get("w", 0), root.get("h", 0)
    fr, ip, op = root.get("fr", 0), root.get("ip", 0), root.get("op", 0)
    layers, assets = root.get("layers"), root.get("assets")
    if version is None:
        version = ""
    if (not isinstance(version, str) or not _is_int(w) or not _is_int(h) or not _is_num(fr) or not _is_num(ip)
            or not _is_num(op) or (layers is not None and not isinstance(layers, list))
            or (assets is not None and not isinstance(assets, list))):
        raise StarGiftFileInvalid()
    fr, ip, op = float(fr), float(ip), float(op)
    if (version == "" or w != 512 or h != 512 or not _math.isfinite(fr) or fr <= 0
            or fr > MAX_STAR_GIFT_ANIMATION_FRAME_RATE or not _math.isfinite(ip) or ip < 0
            or not _math.isfinite(op) or op <= ip or (op - ip) > fr * MAX_STAR_GIFT_ANIMATION_SECONDS
            or not layers):
        raise StarGiftFileInvalid()
    # Анимированные стикеры самодостаточны: внешние/встроенные картинки запрещены,
    # прекомпозиции только с id/layers остаются допустимыми.
    for asset in assets or []:
        if not isinstance(asset, dict):
            raise StarGiftFileInvalid()
        for key in ("p", "u"):
            value = asset.get(key)
            if value is not None and value != "":
                raise StarGiftFileInvalid("%s: external assets are not allowed" % StarGiftFileInvalid.default)
    compact = _json_compact(text).encode("utf-8")
    if len(compact) > MAX_STAR_GIFT_LOTTIE_BYTES:
        raise StarGiftFileInvalid()
    return compact, {"v": version, "w": w, "h": h, "fr": fr, "ip": ip, "op": op}


def prepare_animation_with_policy(file_name, data, allow_expressions=False):
    """.tgs / .json / .lottie -> каноническая пара JSON+TGS (StarGiftAnimation)."""
    file_name = os.path.basename(str(file_name or "").strip()) or "."
    ext = os.path.splitext(file_name)[1].lower()
    fmt = STAR_GIFT_ANIMATION_LOTTIE
    data = bytes(data)
    if ext == ".tgs" or is_gzip(data):
        fmt = STAR_GIFT_ANIMATION_TGS
        if len(data) == 0 or len(data) > MAX_STAR_GIFT_TGS_BYTES:
            raise StarGiftFileInvalid()
        raw_json = decompress_single_tgs(data)
    else:
        if ext not in (".json", ".lottie"):
            raise StarGiftFileInvalid("%s: expected .tgs, .json or plain .lottie" % StarGiftFileInvalid.default)
        if len(data) == 0 or len(data) > MAX_STAR_GIFT_LOTTIE_BYTES:
            raise StarGiftFileInvalid()
        raw_json = data
    normalized, meta = normalize_and_validate_lottie(raw_json, allow_expressions)
    tgs = gzip_lottie(normalized)
    if len(tgs) > MAX_STAR_GIFT_TGS_BYTES:
        raise StarGiftFileInvalid()
    return StarGiftAnimation(
        source_name=file_name, source_format=fmt, json_data=normalized, tgs=tgs,
        sha256=_hashlib.sha256(tgs).digest(), width=meta["w"], height=meta["h"],
        frame_rate=meta["fr"], in_point=meta["ip"], out_point=meta["op"])


def prepare_animation(file_name, data):
    return prepare_animation_with_policy(file_name, data, False)


def prepare_official_animation(file_name, data):
    """Сохраняет expressions из подписанного официального снапшота (файл должен быть заранее сверен по SHA-256)."""
    return prepare_animation_with_policy(file_name, data, True)

