    id: int = 0
    title: str = ""
    stars: int = 0
    convert_stars: int = 0
    upgrade_stars: int = 0
    availability_total: int = 0
    availability_remains: int = 0
    availability_resale: int = 0
    limited: bool = False
    sold_out: bool = False
    birthday: bool = False
