def valid_rarity(rarity, crafted):
    """permille=0 допустим (атрибут остаётся в пуле, но не участвует в случайной выдаче)."""
    kind, permille = _g(rarity, "kind"), _g(rarity, "permille")
    if kind == "permille":
        return (not crafted and _is_int(permille) and 0 <= permille <= 1000)
    return bool(crafted and permille is None and kind in ("uncommon", "rare", "epic", "legendary"))


def _o_int(value, default=0):
    return value if _is_int(value) else default


def _o_str(value):
    return value if isinstance(value, str) else ""


def _o_bool(value):
    return value is True


def _o_rarity(value):
    value = value if isinstance(value, dict) else {}
    return OfficialRarity(kind=_o_str(value.get("kind")), permille=value.get("permille"))


def _o_background(value):
    if not isinstance(value, dict):
        return None
    return OfficialBackground(_o_int(value.get("center_color")), _o_int(value.get("edge_color")),
                              _o_int(value.get("text_color")))


class OfficialGiftsCatalog(object):
    """Читает manifest.json (schema 2) из каталога снапшота; загрузка ленивая и потокобезопасная."""

    def __init__(self, root):
        self.root = (root or "").strip()
        self._lock = threading.Lock()
        self._loaded = False
        self._snap = None
        self._err = None

    # --- публичный API -------------------------------------------------
    def list(self):
        snap = self._load()
        out = []
        for gid in snap["ordered"]:
            gift = snap["gifts"][gid]
            doc = snap["documents"][gift["document_ids"][0]]
            s = OfficialGiftSummary(
                id=gid, title=user_visible_text(gift["title"], ""), stars=gift["stars"],
                convert_stars=gift["convert_stars"], upgrade_stars=gift["upgrade_stars"],
                availability_total=gift["availability_total"], availability_remains=gift["availability_remains"],
                availability_resale=gift["availability_resale"], limited=gift["limited"], sold_out=gift["sold_out"],
                birthday=gift["birthday"], require_premium=gift["require_premium"],
                limited_per_user=gift["limited_per_user"], peer_color_available=gift["peer_color_available"],
                auction=gift["auction"], first_sale_date=gift["first_sale_date"],
                last_sale_date=gift["last_sale_date"], resell_min_stars=gift["resell_min_stars"],
                per_user_total=gift["per_user_total"], per_user_remains=gift["per_user_remains"],
                locked_until_date=gift["locked_until_date"],
                auction_slug=user_visible_text(gift["auction_slug"], ""), gifts_per_round=gift["gifts_per_round"],
                auction_start_date=gift["auction_start_date"], upgrade_variants=gift["upgrade_variants"],
                background=_copy.copy(gift["background"]), document_id=doc["id"],
                animation_validated=doc["animation_validated"])
            cs = snap["sets"].get(gid)
            if cs is not None:
                s.model_count, s.pattern_count, s.backdrop_count = len(cs["models"]), len(cs["patterns"]), len(cs["backdrops"])
                s.crafted_model_count = sum(1 for m in cs["models"] if m["crafted"])
            out.append(s)
        return out

    def bundle(self, gift_id, include_collectible=False):
        snap = self._load()
        gift = snap["gifts"].get(gift_id)
        if gift is None:
            raise OfficialGiftNotFound()
        base_id = gift["document_ids"][0]
        try:
            base = self._read_document(snap["documents"][base_id])
        except (OSError, GiftError) as e:
            raise GiftError("base document %d: %s" % (base_id, e))
        g = OfficialGift(
            id=gift["id"], title=user_visible_text(gift["title"], ""), stars=gift["stars"],
            convert_stars=gift["convert_stars"], upgrade_stars=gift["upgrade_stars"],
            availability_total=gift["availability_total"], availability_remains=gift["availability_remains"],
            limited=gift["limited"], sold_out=gift["sold_out"], birthday=gift["birthday"],
            require_premium=gift["require_premium"], limited_per_user=gift["limited_per_user"],
            peer_color_available=gift["peer_color_available"], auction=gift["auction"],
            availability_resale=gift["availability_resale"], first_sale_date=gift["first_sale_date"],
            last_sale_date=gift["last_sale_date"], resell_min_stars=gift["resell_min_stars"],
            per_user_total=gift["per_user_total"], per_user_remains=gift["per_user_remains"],
            locked_until_date=gift["locked_until_date"], auction_slug=user_visible_text(gift["auction_slug"], ""),
            gifts_per_round=gift["gifts_per_round"], auction_start_date=gift["auction_start_date"],
            upgrade_variants=gift["upgrade_variants"], background=_copy.copy(gift["background"]),
            document_id=base_id)
        out = OfficialBundle(manifest_sha256=bytes(snap["manifest_sha"]), source_json=gift["source_json"],
                             gift=g, base_document=base)
        if not include_collectible:
            return out
        cs = snap["sets"].get(gift_id)
        if cs is None:
            raise _official_invalid("gift %d has no collectible attribute set" % gift_id)
        models, patterns, backdrops = [], [], []
        for v in cs["models"]:
            try:
                doc = self._read_document(snap["documents"][v["document_id"]])
            except (OSError, GiftError) as e:
                raise GiftError("model %r document %d: %s" % (v["name"], v["document_id"], e))
            models.append(OfficialModel(user_visible_text(v["name"], ""), v["document_id"], v["crafted"], v["rarity"], doc))
        for v in cs["patterns"]:
            try:
                doc = self._read_document(snap["documents"][v["document_id"]])
            except (OSError, GiftError) as e:
                raise GiftError("pattern %r document %d: %s" % (v["name"], v["document_id"], e))
            patterns.append(OfficialPattern(user_visible_text(v["name"], ""), v["document_id"], v["rarity"], doc))
        for v in cs["backdrops"]:
            backdrops.append(OfficialBackdrop(user_visible_text(v["name"], ""), v["backdrop_id"], v["center_color"],
                                              v["edge_color"], v["pattern_color"], v["text_color"], v["rarity"]))
        out.collectible = OfficialCollectibleSet(models, patterns, backdrops)
        return out

    # --- внутреннее ------------------------------------------------------
    def _load(self):
        with self._lock:
            if not self._loaded:
                self._loaded = True
                try:
                    self._snap = self._load_snapshot()
                except GiftError as e:
                    self._err = e
        if self._err is not None:
            raise self._err
        return self._snap

    def _load_snapshot(self):
        if not self.root:
            raise OfficialGiftsUnavailable()
        try:
            with open(os.path.join(self.root, "manifest.json"), "rb") as f:
                raw = f.read()
        except OSError as e:
            raise OfficialGiftsUnavailable("%s: %s" % (OfficialGiftsUnavailable.default, e))
        try:
            text = raw.decode("utf-8")
            value = json.loads(text)
            if not isinstance(value, dict):
                raise ValueError("manifest is not an object")
            gift_spans = _json_array_raw_elements(_json_object_raw_fields(text).get("gifts", "null"))
        except ValueError as e:
            raise _official_invalid("decode manifest: %s" % e)
        gifts_raw = value.get("gifts") or []
        sets_raw = value.get("upgrade_attribute_sets") or []
        docs_raw = value.get("documents") or []
        if (value.get("schema") != OFFICIAL_MANIFEST_SCHEMA or _o_int(value.get("gift_count"), -1) != len(gifts_raw)
                or not gifts_raw or len(gift_spans) != len(gifts_raw)):
            raise _official_invalid("unexpected schema or gift count")
        snap = {"manifest_sha": _hashlib.sha256(raw).digest(), "gifts": {}, "sets": {}, "documents": {}, "ordered": []}
        for d in docs_raw:
            d = d if isinstance(d, dict) else {}
            f = d.get("file") if isinstance(d.get("file"), dict) else {}
            doc = {"id": _o_int(d.get("id")), "file_name": _o_str(d.get("file_name")),
                   "path": _o_str(f.get("path")), "size": _o_int(f.get("size")), "sha256": _o_str(f.get("sha256")),
                   "animation_validated": _o_bool(d.get("animation_validated")),
                   "validation_error": _o_str(d.get("validation_error"))}
            if doc["id"] <= 0 or doc["size"] <= 0 or len(doc["sha256"]) != 64 or not doc["path"].strip():
                raise _official_invalid("invalid document %d" % doc["id"])
            if doc["id"] in snap["documents"]:
                raise _official_invalid("duplicate document %d" % doc["id"])
            snap["documents"][doc["id"]] = doc
        for idx, g in enumerate(gifts_raw):
            g = g if isinstance(g, dict) else {}
            ids = g.get("document_ids")
            gift = {
                "index": _o_int(g.get("index")), "kind": _o_str(g.get("kind")), "id": _o_int(g.get("id")),
                "title": _o_str(g.get("title")), "stars": _o_int(g.get("stars")),
                "convert_stars": _o_int(g.get("convert_stars")), "upgrade_stars": _o_int(g.get("upgrade_stars")),
                "limited": _o_bool(g.get("limited")), "sold_out": _o_bool(g.get("sold_out")),
                "birthday": _o_bool(g.get("birthday")), "require_premium": _o_bool(g.get("require_premium")),
                "limited_per_user": _o_bool(g.get("limited_per_user")),
                "peer_color_available": _o_bool(g.get("peer_color_available")), "auction": _o_bool(g.get("auction")),
                "availability_remains": _o_int(g.get("availability_remains")),
                "availability_total": _o_int(g.get("availability_total")),
                "availability_resale": _o_int(g.get("availability_resale")),
                "first_sale_date": _o_int(g.get("first_sale_date")), "last_sale_date": _o_int(g.get("last_sale_date")),
                "resell_min_stars": _o_int(g.get("resell_min_stars")),
                "per_user_total": _o_int(g.get("per_user_total")), "per_user_remains": _o_int(g.get("per_user_remains")),
                "locked_until_date": _o_int(g.get("locked_until_date")),
                "auction_slug": _o_str(g.get("auction_slug")), "gifts_per_round": _o_int(g.get("gifts_per_round")),
                "auction_start_date": _o_int(g.get("auction_start_date")),
                "upgrade_variants": _o_int(g.get("upgrade_variants")),
                "background": _o_background(g.get("background")),
                "document_ids": [x for x in ids if _is_int(x)] if isinstance(ids, list) else [],
                "source_json": _json_compact(gift_spans[idx]).encode("utf-8"),
            }
            if gift["kind"] != "regular" or gift["id"] <= 0 or gift["stars"] <= 0 or len(gift["document_ids"]) != 1:
                raise _official_invalid("invalid gift %d" % gift["id"])
            if gift["document_ids"][0] not in snap["documents"]:
                raise _official_invalid("gift %d document missing" % gift["id"])
            if gift["id"] in snap["gifts"]:
                raise _official_invalid("duplicate gift %d" % gift["id"])
            snap["gifts"][gift["id"]] = gift
            snap["ordered"].append(gift["id"])
        for s in sets_raw:
            s = s if isinstance(s, dict) else {}
            gid = _o_int(s.get("gift_id"))
            models = [{"name": _o_str(m.get("name")), "document_id": _o_int(m.get("document_id")),
                       "crafted": _o_bool(m.get("crafted")), "rarity": _o_rarity(m.get("rarity"))}
                      for m in (s.get("models") or []) if isinstance(m, dict)]
            patterns = [{"name": _o_str(m.get("name")), "document_id": _o_int(m.get("document_id")),
                         "rarity": _o_rarity(m.get("rarity"))}
                        for m in (s.get("patterns") or []) if isinstance(m, dict)]
            backdrops = [{"name": _o_str(m.get("name")), "backdrop_id": _o_int(m.get("backdrop_id")),
                          "center_color": _o_int(m.get("center_color")), "edge_color": _o_int(m.get("edge_color")),
                          "pattern_color": _o_int(m.get("pattern_color")), "text_color": _o_int(m.get("text_color")),
                          "rarity": _o_rarity(m.get("rarity"))}
                         for m in (s.get("backdrops") or []) if isinstance(m, dict)]
            if (gid not in snap["gifts"] or _o_int(s.get("attribute_count"), -1) != len(models) + len(patterns) + len(backdrops)
                    or not models or not patterns or not backdrops):
                raise _official_invalid("invalid collectible set %d" % gid)
            if gid in snap["sets"]:
                raise _official_invalid("duplicate collectible set %d" % gid)
            for m in models:
                if m["document_id"] not in snap["documents"] or not valid_rarity(m["rarity"], m["crafted"]):
                    raise _official_invalid("invalid model %r" % m["name"])
            for p in patterns:
                if p["document_id"] not in snap["documents"] or not valid_rarity(p["rarity"], False):
                    raise _official_invalid("invalid pattern %r" % p["name"])
            for b in backdrops:
                if b["backdrop_id"] < 0 or not valid_rarity(b["rarity"], False):
                    raise _official_invalid("invalid backdrop %r" % b["name"])
            snap["sets"][gid] = {"models": models, "patterns": patterns, "backdrops": backdrops}
        snap["ordered"].sort(key=lambda gid_: snap["gifts"][gid_]["index"])   # sort устойчив, как SliceStable
        return snap

    def _read_document(self, doc):
        root = os.path.abspath(self.root)
        clean = os.path.normpath(doc["path"].replace("/", os.sep))
        if os.path.isabs(clean):
            raise OfficialGiftsInvalid()
        full = os.path.join(root, clean)
        rel = os.path.relpath(full, root)
        if rel == ".." or rel.startswith(".." + os.sep) or not os.path.realpath(full).startswith(os.path.realpath(root) + os.sep):
            raise OfficialGiftsInvalid()
        with open(full, "rb") as f:
            data = f.read()
        if len(data) != doc["size"]:
            raise _official_invalid("size mismatch")
        if _hashlib.sha256(data).hexdigest().lower() != doc["sha256"].lower():
            raise _official_invalid("sha256 mismatch")
        name = doc["file_name"].strip() or os.path.basename(clean)
        return OfficialDocument(id=doc["id"], file_name=name, path=doc["path"], size=doc["size"],
                                sha256=doc["sha256"].lower(), animation_validated=doc["animation_validated"],
                                validation_error=doc["validation_error"], data=data)


# ===========================================================================
# 4f) giftpack/manifest.go + giftpack/import.go (адаптация owpengram-server, Apache-2.0)
# ===========================================================================
@_dc.dataclass
class GiftPackAttrSpec:
    name: str = ""
    animation: str = ""
    permille: int = 0
    crafted: bool = False
    rarity: str = ""


@_dc.dataclass
class GiftPackBackdropSpec:
    name: str = ""
    center: str = ""
    edge: str = ""
    pattern: str = ""
    text: str = ""
    permille: int = 0


@_dc.dataclass
class GiftPackUpgradeSpec:
    upgrade_stars: int = 0
    supply_total: int = 0
    slug_prefix: str = ""
    models: list = _dc.field(default_factory=list)
    patterns: list = _dc.field(default_factory=list)
    backdrops: list = _dc.field(default_factory=list)


@_dc.dataclass
class GiftPackGiftSpec:
    id_slug: str = ""
    title: str = ""
    stars: int = 0
    convert_stars: int = 0
    base_animation: str = ""
    limited: bool = False
    availability_total: int = 0
    birthday: bool = False
    require_premium: bool = False
    support_only: bool = False
    limited_per_user: bool = False
    per_user_total: int = 0
    resell_min_stars: int = 0
    auction: bool = False
    auction_slug: str = ""
    gifts_per_round: int = 0
    auction_start_date: int = 0
    auction_round_duration: int = 0
    upgrade: object = None


@_dc.dataclass
class GiftPackManifest:
    pack_name: str = ""
    author: str = ""
    gifts: list = _dc.field(default_factory=list)


_GP_ATTR_KEYS = {"name": str, "animation": str, "permille": int, "crafted": bool, "rarity": str}
_GP_BACKDROP_KEYS = {"name": str, "center": str, "edge": str, "pattern": str, "text": str, "permille": int}
_GP_UPGRADE_KEYS = {"upgrade_stars": int, "supply_total": int, "slug_prefix": str, "models": list,
                    "patterns": list, "backdrops": list}
_GP_GIFT_KEYS = {"id_slug": str, "title": str, "stars": int, "convert_stars": int, "base_animation": str,
                 "limited": bool, "availability_total": int, "birthday": bool, "require_premium": bool,
                 "support_only": bool, "limited_per_user": bool, "per_user_total": int, "resell_min_stars": int,
                 "auction": bool, "auction_slug": str, "gifts_per_round": int, "auction_start_date": int,
                 "auction_round_duration": int, "upgrade": dict}
_GP_MANIFEST_KEYS = {"pack_name": str, "author": str, "gifts": list}


def _gp_strict(obj, spec, what):
    """DisallowUnknownFields + проверка типов (null = значение по умолчанию, как в Go)."""
    if not isinstance(obj, dict):
        raise GiftError("parse pack manifest: %s must be an object" % what)
    out = {}
    for key, value in obj.items():
        if key not in spec:
            raise GiftError("parse pack manifest: unknown field %r in %s" % (key, what))
        if value is None:
            continue
        want = spec[key]
        ok = (_is_int(value) if want is int else isinstance(value, bool) if want is bool
              else isinstance(value, want))
        if not ok:
            raise GiftError("parse pack manifest: %s.%s has wrong type" % (what, key))
        out[key] = value
    return out


def parse_gift_pack_manifest(data):
    """Декодирует и структурно проверяет pack.json (байты анимаций проверяются позже, по одному файлу)."""
    if not data or len(data) > _GP_MAX_MANIFEST:
        raise GiftError("pack manifest exceeds size limit")
    try:
        raw = json.loads(bytes(data).decode("utf-8"), parse_constant=_json_reject_constant)
    except ValueError as e:
        if "Extra data" in str(e):
            raise GiftError("pack manifest contains trailing JSON")
        raise GiftError("parse pack manifest: %s" % e)
    top = _gp_strict(raw, _GP_MANIFEST_KEYS, "manifest")
    m = GiftPackManifest(pack_name=top.get("pack_name", ""), author=top.get("author", ""))
    for i, g in enumerate(top.get("gifts", [])):
        gd = _gp_strict(g, _GP_GIFT_KEYS, "gifts[%d]" % i)
        up = gd.pop("upgrade", None)
        spec = GiftPackGiftSpec(**gd)
        if up is not None:
            ud = _gp_strict(up, _GP_UPGRADE_KEYS, "gifts[%d].upgrade" % i)
            models = [GiftPackAttrSpec(**_gp_strict(a, _GP_ATTR_KEYS, "models")) for a in ud.pop("models", [])]
            patterns = [GiftPackAttrSpec(**_gp_strict(a, _GP_ATTR_KEYS, "patterns")) for a in ud.pop("patterns", [])]
            backdrops = [GiftPackBackdropSpec(**_gp_strict(b, _GP_BACKDROP_KEYS, "backdrops"))
                         for b in ud.pop("backdrops", [])]
            spec.upgrade = GiftPackUpgradeSpec(models=models, patterns=patterns, backdrops=backdrops, **ud)
        m.gifts.append(spec)
    if not m.pack_name.strip() or len(m.pack_name) > 128 or len(m.author) > 128:
        raise GiftError("pack manifest: pack_name is required and name/author must be <= 128 characters")
    if not 1 <= len(m.gifts) <= 50:
        raise GiftError("pack manifest: 1..50 gifts are required")
    seen_titles, seen_slugs = set(), set()
    for i, g in enumerate(m.gifts):
        if not g.title.strip():
            raise GiftError("pack manifest: gifts[%d].title is required" % i)
        if len(g.title.strip()) > MAX_STAR_GIFT_TITLE_RUNES:
            raise GiftError("pack manifest: gifts[%d].title is too long" % i)
        key = g.title.strip().lower()
        if key in seen_titles:
            raise GiftError("pack manifest: duplicate gift title %r" % g.title)
        seen_titles.add(key)
        if g.stars <= 0:
            raise GiftError("pack manifest: gift %r: stars must be > 0" % g.title)
        if g.convert_stars < 0 or g.convert_stars > g.stars:
            raise GiftError("pack manifest: gift %r: convert_stars must be between 0 and stars" % g.title)
        if not valid_asset_path(g.base_animation) or g.base_animation == "pack.json":
            raise GiftError("pack manifest: gift %r: base_animation is required" % g.title)
        if (g.availability_total < 0 or g.per_user_total < 0 or g.resell_min_stars < 0
                or (g.limited and g.availability_total == 0)
                or (g.limited_per_user and g.per_user_total == 0)
                or (not g.limited_per_user and g.per_user_total > 0)):
            raise GiftError("pack manifest: gift %r: invalid supply or per-user limit" % g.title)
        u = g.upgrade
        if u is None:
            continue
        if not u.slug_prefix.strip() or u.upgrade_stars <= 0 or u.supply_total <= 0:
            raise GiftError("pack manifest: gift %r: upgrade.slug_prefix is required" % g.title)
        slug = u.slug_prefix.strip().lower()
        if slug in seen_slugs:
            raise GiftError("pack manifest: duplicate upgrade slug_prefix %r" % u.slug_prefix)
        seen_slugs.add(slug)
        if not u.models or not u.patterns or not u.backdrops:
            raise GiftError("pack manifest: gift %r: upgrade needs at least one model, pattern and backdrop" % g.title)
        if max(len(u.models), len(u.patterns), len(u.backdrops)) > MAX_STAR_GIFT_COLLECTIBLE_ATTRIBUTES_PER_KIND:
            raise GiftError("pack manifest: gift %r: too many upgrade attributes" % g.title)
        for attrs in (u.models, u.patterns):
            for a in attrs:
                if not a.name.strip() or not valid_asset_path(a.animation) or a.animation == "pack.json":
                    raise GiftError("pack manifest: gift %r: attribute name and animation are required" % g.title)
        for b in u.backdrops:
            if not b.name.strip():
                raise GiftError("pack manifest: gift %r: backdrop name is required" % g.title)
    return m


def parse_hex_color(s):
    """'#RRGGBB' (или 'RRGGBB') -> упакованный 24-битный int."""
    s = (s or "").strip()
    if s.startswith("#"):
        s = s[1:]
    if len(s) != 6:
        raise GiftError("invalid color %r, want #RRGGBB" % s)
    try:
        return int(s, 16)
    except ValueError as e:
        raise GiftError("invalid color %r: %s" % (s, e))


def build_gift_pack_attributes(prep, gift_title, kind, specs, assets):
    out = []
    for i, a in enumerate(specs):
        data = assets.open(a.animation)
        try:
            anim = prep.prepare_animation(a.animation, data)
        except GiftError as e:
            raise GiftError("gift %r: %s %r: %s" % (gift_title, kind, a.name, e))
        rarity = (a.rarity or "").strip() or STAR_GIFT_RARITY_PERMILLE
        out.append(StarGiftCollectibleAttribute(
            kind=kind, name=a.name, rarity_kind=rarity, rarity_permille=a.permille, crafted=a.crafted,
            sort_order=i, animation=anim))
    return out


def build_gift_pack_backdrops(gift_title, specs):
    out = []
    for i, b in enumerate(specs):
        colors = {}
        for field in ("center", "edge", "pattern", "text"):
            try:
                colors[field] = parse_hex_color(getattr(b, field))
            except GiftError as e:
                raise GiftError("gift %r: backdrop %r: %s: %s" % (gift_title, b.name, field, e))
        out.append(StarGiftCollectibleAttribute(
            kind=STAR_GIFT_COLLECTIBLE_BACKDROP, name=b.name, backdrop_id=i + 1, center_color=colors["center"],
            edge_color=colors["edge"], pattern_color=colors["pattern"], text_color=colors["text"],
            rarity_kind=STAR_GIFT_RARITY_PERMILLE, rarity_permille=b.permille, sort_order=i))
    return out


def build_gift_pack_bundle(prep, spec, assets):
    base_data = assets.open(spec.base_animation)
    try:
        base_anim = prep.prepare_animation(spec.base_animation, base_data)
    except GiftError as e:
        raise GiftError("gift %r: base animation: %s" % (spec.title, e))
    bundle = StarGiftCatalogBundleWrite(catalog=StarGiftCatalogWrite(
        title=spec.title, stars=spec.stars, convert_stars=spec.convert_stars, enabled=True, animation=base_anim,
        limited=spec.limited, birthday=spec.birthday, require_premium=spec.require_premium,
        support_only=spec.support_only, limited_per_user=spec.limited_per_user, auction=spec.auction,
        availability_total=spec.availability_total, resell_min_stars=spec.resell_min_stars,
        per_user_total=spec.per_user_total, auction_slug=spec.auction_slug, gifts_per_round=spec.gifts_per_round,
        auction_start_date=spec.auction_start_date, auction_round_duration=spec.auction_round_duration))
    if spec.upgrade is None:
        return bundle
    up = spec.upgrade
    models = build_gift_pack_attributes(prep, spec.title, STAR_GIFT_COLLECTIBLE_MODEL, up.models, assets)
    patterns = build_gift_pack_attributes(prep, spec.title, STAR_GIFT_COLLECTIBLE_PATTERN, up.patterns, assets)
    backdrops = build_gift_pack_backdrops(spec.title, up.backdrops)
    bundle.collectible = StarGiftCollectibleWrite(
        upgrade_stars=up.upgrade_stars, supply_total=up.supply_total, slug_prefix=up.slug_prefix,
        models=models, patterns=patterns, backdrops=backdrops, command_id="giftpack-preview")
    return bundle


@_dc.dataclass
class GiftPackImportOptions:
    dry_run: bool = False
    actor: str = ""
    command_id: str = ""
    now: object = None           # callable -> секунды (только тесты); по умолчанию time.time


@_dc.dataclass
class GiftImportOutcome:
    title: str = ""
    status: str = ""             # created | would_create | skipped | failed | not_attempted
    error: str = ""
    gift_id: str = ""


@_dc.dataclass
class GiftPackImportResult:
    pack_name: str = ""
    gifts: list = _dc.field(default_factory=list)


def import_gift_pack(svc, manifest, assets, opts=None):
    """Предвалидирует весь пак, затем публикует каждый новый подарок вместе с пулом атрибутов.
    svc: prepare_animation(name, data), catalog_all(), create_catalog_bundle(write) (см. StarGiftService).
    Сбой записи останавливает импорт; повторный запуск пропустит уже опубликованные названия."""
    opts = opts or GiftPackImportOptions()
    at = int((opts.now or time.time)())
    try:
        existing = svc.catalog_all()
    except (GiftError, ValueError) as e:
        raise GiftError("read existing catalog: %s" % e)
    existing_titles = set(str(_g(g, "title", "")).strip().lower() for g in existing)
    result = GiftPackImportResult(pack_name=manifest.pack_name)
    prepared = []
    for spec in manifest.gifts:
        outcome = GiftImportOutcome(title=spec.title)
        try:
            bundle = build_gift_pack_bundle(svc, spec, assets)
            anim = bundle.catalog.animation
            if anim.width != 512 or anim.height != 512 or not anim.tgs or len(anim.sha256) != 32:
                raise GiftError("invalid base animation")
            bundle.catalog.validate_lifecycle_authoring(at)
            bundle.catalog.normalize_lifecycle_authoring(at)
            bundle.catalog.actor, bundle.catalog.command_id = opts.actor, opts.command_id
            if bundle.collectible is not None:
                bundle.collectible.actor, bundle.collectible.command_id = opts.actor, opts.command_id
                validation = _copy.copy(bundle.collectible)
                validation.gift_id = 1
                validate_star_gift_collectible_draft(validation)
        except (GiftError, ValueError) as e:
            raise GiftError("gift %r: %s" % (spec.title, e))
        skip = spec.title.strip().lower() in existing_titles
        prepared.append((bundle, skip))
        outcome.status = "skipped" if skip else "would_create"
        result.gifts.append(outcome)
    new_count = sum(1 for _, skip in prepared if not skip)
    if len(existing) + new_count > MAX_STAR_GIFT_CATALOG_SIZE:
        raise GiftError("gift pack exceeds catalog capacity of %d" % MAX_STAR_GIFT_CATALOG_SIZE)
    if opts.dry_run:
        return result
    for i, (bundle, skip) in enumerate(prepared):
        if skip:
            continue
        try:
            created = svc.create_catalog_bundle(bundle)
        except GiftError as e:
            result.gifts[i].status, result.gifts[i].error = "failed", str(e)
            for j in range(i + 1, len(result.gifts)):
                if result.gifts[j].status == "would_create":
                    result.gifts[j].status = "not_attempted"
            raise GiftPackImportError("gift %r: %s" % (manifest.gifts[i].title, e), result)
        result.gifts[i].status = "created"
        result.gifts[i].gift_id = str(_g(_g(_g(created, "catalog"), "gift"), "id", ""))
    return result


class GiftPackImportError(GiftError):
    """Сбой записи при импорте: .result содержит частичный итог (как пара result+error в Go)."""

    def __init__(self, message, result=None):
        GiftError.__init__(self, message)
        self.result = result

# ===========================================================================
# 4g) stargifts/service.go — каталог звёздных подарков, коллекционные пулы, вывод, сводки.
#     Хранилища передаются как duck-typed объекты (методы snake_case от Go-имён):
#       store      — StarGiftStore   (catalog, catalog_all, catalog_revision, create_catalog_revision,
#                    create_catalog_bundle, set_catalog_enabled, set_catalog_sort_order, animation_json,
#                    publish_collectible_revision, active_collectible_projection, collectible_availability,
#                    collectible_animation_json, [collectible_animation_blob], unique_by_slug, unique_by_id,
#                    unique_by_ids, list_unique_by_owner, resolve_user_message_ref, get_by_ref, create,
#                    list_by_owner_filtered, resolve_saved_ids, count_by_owner, set_unsaved, mark_converted,
#                    list_collections, create_collection, update_collection, delete_collection,
#                    reorder_collections, set_pinned)
#       upgrades   — upgrade_star_gift, star_gift_upgrade_receipt, grant_unique_star_gift
#       lifecycle  — purchase_star_gift, issue_star_gift_purchase_form, settled_star_gift_purchase,
#                    validate_star_gift_purchase_form, list_resale_star_gifts, unique_star_gift_value_info,
#                    set_star_gift_listing, transfer_star_gift, purchase_resale_star_gift, send_star_gift_offer,
#                    resolve_star_gift_offer, list_craft_star_gifts, craft_star_gift, star_gift_auction_state,
#                    active_star_gift_auctions, star_gift_auction_acquired, bid_star_gift_auction,
#                    prepaid_upgrade_target, prepay_star_gift_upgrade, drop_star_gift_original_details,
#                    set_star_gift_notifications, star_gift_notifications_enabled, delete_star_gift,
#                    record_star_gift_withdrawal, resolve_star_gift_withdrawal, complete_star_gift_withdrawal,
#                    [complete_star_gift_withdrawal_on_chain], issue_channel_revenue_withdrawal,
#                    resolve_channel_revenue_withdrawal, complete_channel_revenue_withdrawal, ton_balance,
#                    ton_transactions, channel_stars_balance, channel_stars_overall_revenue,
#                    channel_stars_transactions, channel_ton_balance, channel_ton_overall_revenue,
#                    channel_ton_transactions, bot_stars_balance, bot_stars_overall_revenue,
#                    bot_stars_transactions, credit_bot_stars_wallet, bot_stars_revenue_series,
#                    sweep_star_gift_lifecycle, convert_star_gift, [cross_craft_capability]
#       blobs      — name(), put(data) -> object_key, get(object_key) -> bytes
#       withdrawal — name(), create_withdrawal(req), [create_revenue_withdrawal(req)]
# ===========================================================================
