PURCHASE_FORM_TTL = 600


@_dc.dataclass
class StarGiftWithdrawalProviderRequest:
    user_id: int = 0
    gift: object = None


@_dc.dataclass
class StarGiftWithdrawalProviderResult:
    request_id: str = ""
    url: str = ""
    expires_at: int = 0


