class ChannelRevenueWithdrawalProviderRequest:
    channel_id: int = 0
    creator_user_id: int = 0
    currency: object = None


def collectible_document_thumbs(kind):
    if kind != STAR_GIFT_COLLECTIBLE_PATTERN:
        return []
    return [PhotoSize(kind=PHOTO_SIZE_KIND_PATH, type="j", bytes=bytes(COLLECTIBLE_PATTERN_PATH_THUMB))]


def collectible_document_attributes(kind):
    render = DocumentAttribute(kind=DOC_ATTR_STICKER, alt="🎁")
    if kind == STAR_GIFT_COLLECTIBLE_PATTERN:
        # pattern_color применяется клиентом только к text-color custom emoji.
        render = DocumentAttribute(kind=DOC_ATTR_CUSTOM_EMOJI, alt="🎁", text_color=True)
    return [DocumentAttribute(kind=DOC_ATTR_IMAGE_SIZE, w=512, h=512), render,
            DocumentAttribute(kind=DOC_ATTR_FILENAME, file_name="%s.tgs" % kind)]


def brand_collectible_attributes(attributes):
    for a in attributes:
        a.name = user_visible_text((a.name or "").strip(), "")


def valid_purchase_form(form):
    msg_ok = _g(form, "message_valid")
    msg_ok = msg_ok() if callable(msg_ok) else len(_g(form, "message", "") or "") <= 255
    to = _g(form, "to")
    return (_g(form, "form_id", 0) == 0 and _g(form, "buyer_user_id", 0) > 0 and _g(to, "id", 0) > 0
            and _g(to, "type") in (PEER_TYPE_USER, PEER_TYPE_CHANNEL) and _g(form, "gift_id", 0) > 0
            and _g(form, "revision_id", 0) > 0 and _g(form, "charge_stars", 0) > 0 and _g(form, "issued_at", 0) > 0
            and _g(form, "expires_at", 0) == _g(form, "issued_at", 0) + PURCHASE_FORM_TTL and bool(msg_ok))


def validate_purchase_form_intent(form, req):
    for name in ("buyer_user_id", "gift_id", "include_upgrade", "hide_name", "message"):
        if _g(form, name) != _g(req, name):
            raise StarGiftFormPurposeInvalid()
    if _peer_tuple(_g(form, "to")) != _peer_tuple(_g(req, "to")):
        raise StarGiftFormPurposeInvalid()
    if list(_g(form, "message_entities") or []) != list(_g(req, "message_entities") or []):
        raise StarGiftFormPurposeInvalid()
    if _g(form, "revision_id") != _g(req, "revision_id") or _g(form, "charge_stars") != _g(req, "charge_stars"):
        raise StarGiftFormAmountMismatch()


def _peer_tuple(peer):
    return (_g(peer, "type"), _g(peer, "id"))


class StarGiftService(object):
    """Долговременный каталог звёздных подарков и состояние полученных подарков."""

    def __init__(self, store, blobs=None, dc=0, upgrades=None, lifecycle=None, withdrawal=None):
        self.store, self.blobs, self.dc = store, blobs, dc
        self.upgrades, self.lifecycle, self.withdrawal = upgrades, lifecycle, withdrawal
        self._mu = threading.RLock()
        self._built, self._gifts, self._by_id, self._hash = False, [], {}, 0
        self._form_mu = threading.Lock()
        self._forms = {}

    # --- опции (WithUpgradeStore / WithLifecycleStore / WithWithdrawalProvider) ---
    def with_upgrade_store(self, upgrades):
        self.upgrades = upgrades
        return self

    def with_lifecycle_store(self, lifecycle):
        self.lifecycle = lifecycle
        return self

    def with_withdrawal_provider(self, provider):
        self.withdrawal = provider
        return self

    def atomic_purchase_configured(self):
        return self.lifecycle is not None

    # --- анимации (методы-обёртки над функциями animation.go) ---
    def prepare_animation(self, file_name, data):
        return prepare_animation(file_name, data)

    def prepare_official_animation(self, file_name, data):
        return prepare_official_animation(file_name, data)

    # --- каталог ---
    def _ensure_catalog(self):
        with self._mu:
            if self._built:
                return
            if self.store is None:
                raise GiftError("star gift store is not configured")
            gifts = list(self.store.catalog())
            self._gifts = gifts
            self._by_id = dict((_g(g, "id"), g) for g in gifts)
            self._hash = star_gift_catalog_hash(gifts)
            self._built = True

    def catalog(self):
        self._ensure_catalog()
        with self._mu:
            return list(self._gifts)

    def catalog_all(self):
        """Свежий каталог, включая выключенные подарки (для админ-импорта)."""
        if self.store is None:
            raise GiftError("star gift store is not configured")
        return self.store.catalog_all()

    def catalog_hash(self):
        self._ensure_catalog()
        with self._mu:
            return self._hash

    def gift_by_id(self, gift_id):
        """-> (gift, found)"""
        self._ensure_catalog()
        with self._mu:
            gift = self._by_id.get(gift_id)
            return gift, gift is not None

    def gift_revision_by_id(self, revision_id):
        if self.store is None:
            return None, False
        return self.store.catalog_revision(revision_id)

    def invalidate_star_gift_catalog(self):
        with self._mu:
            self._built, self._gifts, self._by_id, self._hash = False, [], {}, 0

    flush_star_gift_catalog = invalidate_star_gift_catalog

    def create_catalog_revision(self, write):
        if self.store is None or self.blobs is None:
            raise GiftError("star gift catalog importer is not configured")
        write.title = user_visible_text((write.title or "").strip(), "")
        anim = write.animation
        if (write.stars <= 0 or write.convert_stars < 0 or write.convert_stars > write.stars or anim is None
                or anim.width != 512 or anim.height != 512 or not anim.tgs
                or len(write.title) > MAX_STAR_GIFT_TITLE_RUNES):
            raise StarGiftInvalid()
        self._materialize_catalog_write(write)
        entry = self.store.create_catalog_revision(write)
        self.invalidate_star_gift_catalog()
        return entry

    def _materialize_catalog_write(self, write):
        object_key = self.blobs.put(write.animation.tgs)
        document_id, access_hash = random_positive_int64(), random_positive_int64()
        write.document = Document(
            id=document_id, access_hash=access_hash, file_reference=os.urandom(16), date=int(time.time()),
            mime_type="application/x-tgsticker", size=len(write.animation.tgs), dc_id=self.dc,
            attributes=[DocumentAttribute(kind=DOC_ATTR_IMAGE_SIZE, w=512, h=512),
                        DocumentAttribute(kind=DOC_ATTR_STICKER, alt="🎁"),
                        DocumentAttribute(kind=DOC_ATTR_FILENAME, file_name="AnimatedSticker.tgs")])
        write.blob = FileBlob(location_key="doc:%d" % document_id, backend=_blob_name(self.blobs),
                              object_key=object_key, size=len(write.animation.tgs),
                              sha256=bytes(write.animation.sha256), mime_type="application/x-tgsticker")

    def create_catalog_bundle(self, write):
        """Материализует все проверенные ресурсы и публикует обе активные ревизии одной транзакцией store."""
        if self.store is None or self.blobs is None:
            raise GiftError("star gift catalog importer is not configured")
        cat = write.catalog
        cat.title = user_visible_text((cat.title or "").strip(), "")
        cat.auction_slug = user_visible_text((cat.auction_slug or "").strip(), "")
        anim = cat.animation
        if (cat.stars <= 0 or cat.convert_stars < 0 or cat.convert_stars > cat.stars or anim is None
                or anim.width != 512 or anim.height != 512 or not anim.tgs
                or len(cat.title) > MAX_STAR_GIFT_TITLE_RUNES):
            raise StarGiftInvalid()
        if cat.official_gift_id < 0:
            raise StarGiftInvalid()
        if cat.official_gift_id > 0:
            source = None
            try:
                source = json.loads(bytes(cat.official_source_json).decode("utf-8"))
            except ValueError:
                pass
            if len(cat.source_manifest_sha256) != 32 or not isinstance(source, dict):
                raise StarGiftInvalid()
        elif cat.source_manifest_sha256 or cat.official_source_json:
            raise StarGiftInvalid()
        col = write.collectible
        if col is not None:
            col.slug_prefix = (col.slug_prefix or "").strip().lower()
            brand_collectible_attributes(col.models)
            brand_collectible_attributes(col.patterns)
            brand_collectible_attributes(col.backdrops)
            if (col.official_gift_id != cat.official_gift_id
                    or bytes(col.source_manifest_sha256) != bytes(cat.source_manifest_sha256)):
                raise StarGiftCollectibleInvalid()
            validation = _copy.copy(col)
            if validation.gift_id == 0:
                validation.gift_id = cat.gift_id or 1
            validate_star_gift_collectible_draft(validation)
        self._materialize_catalog_write(cat)
        if col is not None:
            self._materialize_collectible_attributes(col.models)
            self._materialize_collectible_attributes(col.patterns)
        result = self.store.create_catalog_bundle(write)
        self.invalidate_star_gift_catalog()
        return result

    def set_catalog_enabled(self, gift_id, enabled):
        changed = self.store.set_catalog_enabled(gift_id, enabled)
        self.invalidate_star_gift_catalog()
        return changed

    def set_catalog_sort_order(self, gift_id, sort_order):
        changed = self.store.set_catalog_sort_order(gift_id, sort_order)
        self.invalidate_star_gift_catalog()
        return changed

    def animation_json(self, gift_id):
        return self.store.animation_json(gift_id)

    # --- коллекционные ревизии ---
    def publish_collectible_revision(self, write):
        if self.store is None:
            raise GiftError("star gift collectible store is not configured")
        brand_collectible_attributes(write.models)
        brand_collectible_attributes(write.patterns)
        brand_collectible_attributes(write.backdrops)
        revision = self.store.publish_collectible_revision(write)
        self.invalidate_star_gift_catalog()
        return revision

    def create_collectible_revision(self, write):
        """Материализует анимации моделей/паттернов и атомарно публикует полный неизменяемый пул."""
        if self.store is None or self.blobs is None:
            raise GiftError("star gift collectible importer is not configured")
        write.slug_prefix = (write.slug_prefix or "").strip().lower()
        brand_collectible_attributes(write.models)
        brand_collectible_attributes(write.patterns)
        brand_collectible_attributes(write.backdrops)
        validate_star_gift_collectible_draft(write)
        self._materialize_collectible_attributes(write.models)
        self._materialize_collectible_attributes(write.patterns)
        return self.publish_collectible_revision(write)

    def _materialize_collectible_attributes(self, attributes):
        for a in attributes:
            animation = a.animation
            if animation is None:
                raise StarGiftCollectibleInvalid()
            try:
                object_key = self.blobs.put(animation.tgs)
            except GiftError as e:
                raise GiftError("store collectible %s animation: %s" % (a.kind, e))
            document_id, access_hash = random_positive_int64(), random_positive_int64()
            a.document = Document(
                id=document_id, access_hash=access_hash, file_reference=os.urandom(16), date=int(time.time()),
                mime_type="application/x-tgsticker", size=len(animation.tgs), dc_id=self.dc,
                attributes=collectible_document_attributes(a.kind), thumbs=collectible_document_thumbs(a.kind))
            a.blob = FileBlob(location_key="doc:%d" % document_id, backend=_blob_name(self.blobs),
                              object_key=object_key, size=len(animation.tgs), sha256=bytes(animation.sha256),
                              mime_type="application/x-tgsticker")

    def collectible_preview(self, gift_id, sample_per_kind=0):
        """-> (preview dict, found). sample_per_kind=3 — маленький случайный набор для роллера апгрейда."""
        if self.store is None or gift_id <= 0:
            return None, False
        revision, ok = self.store.active_collectible_projection(gift_id, sample_per_kind)
        if not ok or not _g(revision, "published", False):
            return None, False
        return {"gift_id": gift_id, "revision": _g(revision, "revision"), "upgrade_stars": _g(revision, "upgrade_stars"),
                "supply_total": _g(revision, "supply_total"), "issued": _g(revision, "issued"),
                "models": _g(revision, "models"), "patterns": _g(revision, "patterns"),
                "backdrops": _g(revision, "backdrops"), "slug_prefix": _g(revision, "slug_prefix")}, True

