    def collectible_animation_json(self, gift_id, kind, attribute_id):
        """-> (json_bytes, found). Предпочитает неизменяемый TGS-блоб; JSONB-путь — запасной."""
        if self.store is None:
            return None, False
        if self.blobs is not None and hasattr(self.store, "collectible_animation_blob"):
            blob, found = self.store.collectible_animation_blob(gift_id, kind, attribute_id)
            if found:
                try:
                    data = self.blobs.get(_g(blob, "object_key"))
                except GiftError as e:
                    raise GiftError("get collectible animation blob bytes: %s" % e)
                try:
                    return decompress_single_tgs(data), True
                except GiftError as e:
                    raise GiftError("decompress collectible animation blob: %s" % e)
        return self.store.collectible_animation_json(gift_id, kind, attribute_id)

