    # --- вызовы lifecycle-хранилища (общий каркас: guard + делегирование) ---
    def _lc(self, method, *args, **kw):
        unavailable = kw.get("unavailable")
        if self.lifecycle is None:
            if unavailable is not None:
                raise unavailable()
            return kw.get("default")
        result = getattr(self.lifecycle, method)(*args)
        if kw.get("invalidate"):
            self.invalidate_star_gift_catalog()
        return result

    def purchase(self, req):
        return self._lc("purchase_star_gift", req, unavailable=StarGiftUnavailable, invalidate=True)

    def issue_purchase_form(self, form):
        """Создаёт один свежий платёжный intent; без lifecycle — ограниченная in-memory ветка (только тесты)."""
        if not valid_purchase_form(form):
            raise StarGiftFormPurposeInvalid()
        if self.lifecycle is not None:
            return self.lifecycle.issue_star_gift_purchase_form(form)
        with self._form_mu:
            issued = _g(form, "issued_at", 0)
            for key in [k for k, v in self._forms.items() if _g(v, "expires_at", 0) < issued]:
                del self._forms[key]
            for _ in range(8):
                form_id = random_positive_int64()
                key = (_g(form, "buyer_user_id"), form_id)
                if key in self._forms:
                    continue
                form = _copy.copy(form) if not isinstance(form, dict) else dict(form)
                if isinstance(form, dict):
                    form["form_id"] = form_id
                else:
                    form.form_id = form_id
                self._forms[key] = form
                return form
        raise StarGiftUnavailable()

    def settled_star_gift_purchase(self, req):
        if self.lifecycle is None:
            raise StarGiftUnavailable()
        return self.lifecycle.settled_star_gift_purchase(req)

    def validate_purchase_form(self, req):
        """Read-only предпроверка для точных RPC-ошибок (атомарность — в транзакции покупки)."""
        if self.lifecycle is not None:
            return self.lifecycle.validate_star_gift_purchase_form(req)
        if _g(req, "form_id", 0) == 0:
            raise StarGiftFormExpired()
        with self._form_mu:
            form = self._forms.get((_g(req, "buyer_user_id"), _g(req, "form_id")))
            if form is None or _g(form, "expires_at", 0) < _g(req, "date", 0):
                raise StarGiftFormExpired()
            validate_purchase_form_intent(form, req)

