    # --- вывод подарков ---
    def withdraw(self, req):
        if self.lifecycle is None or self.withdrawal is None:
            raise StarGiftWithdrawalUnavailable()
        saved, found = self.store.get_by_ref(_g(req, "ref"))
        owner = _g(saved, "owner")
        if (not found or _peer_tuple(owner) != (PEER_TYPE_USER, _g(req, "user_id")) or _g(saved, "unique_gift_id", 0) == 0
                or not _lifecycle_live(_g(saved, "lifecycle_status"))):
            raise StarGiftTransferUnavailable()
        # can_export_at доверяет только серверным часам: клиент не может ускорить экспорт.
        if _g(saved, "can_export_at", 0) > _g(req, "date", 0):
            raise StarGiftExportCooldown()
        unique, found = self.store.unique_by_id(_g(saved, "unique_gift_id"))
        if not found or _g(unique, "burned", False) or _peer_tuple(_g(unique, "owner")) != _peer_tuple(owner):
            raise StarGiftTransferUnavailable()
        provided = self.withdrawal.create_withdrawal(
            StarGiftWithdrawalProviderRequest(user_id=_g(req, "user_id"), gift=unique))
        if (not str(_g(provided, "request_id", "")).strip() or not str(_g(provided, "url", "")).strip()
                or _g(provided, "expires_at", 0) <= _g(req, "date", 0)):
            raise StarGiftWithdrawalUnavailable()
        name = self.withdrawal.name
        name = name() if callable(name) else name
        return self.lifecycle.record_star_gift_withdrawal(
            req, name, _g(provided, "request_id"), _g(provided, "url"), _g(provided, "expires_at"))

