    def record_saved_gift(self, gift):
        no_prepaid = (_g(gift, "unique_gift_id", 0) == 0 and _g(gift, "prepaid_upgrade_stars", 0) == 0
                      and not _g(gift, "prepaid_upgrade_hash", ""))
        if no_prepaid and self.store is not None:
            availability = self.store.collectible_availability([_g(gift, "gift_id")])
            current = availability.get(_g(gift, "gift_id"))
            if current is not None and _g(current, "issued", 0) < _g(current, "supply_total", 0):
                _set_field(gift, "prepaid_upgrade_hash",
                           _b64.urlsafe_b64encode(os.urandom(32)).rstrip(b"=").decode("ascii"))
        return self.store.create(gift)

