_BOT_TOKEN_RE = re.compile(r"^(\d{1,19}):([A-Za-z0-9_-]{16,})\Z")


def parse_bot_token(token):
    """'id:secret' -> (bot_id, secret, ok) (аналог domain.ParseBotToken)."""
    m = _BOT_TOKEN_RE.match(token or "")
    if not m:
        return 0, "", False
    return int(m.group(1)), m.group(2), True


def _crc16_xmodem(data):
    crc = 0
    for b in data:
        crc ^= b << 8
        for _ in range(8):
            crc = ((crc << 1) ^ 0x1021) & 0xFFFF if crc & 0x8000 else (crc << 1) & 0xFFFF
    return crc


def canonical_ton_address(raw):
    """Аналог domain.CanonicalTONAddress: принимает raw 'wc:hex64' или user-friendly base64 (EQ…/UQ…),
    проверяет CRC16 и отклоняет testnet-флаг; возвращает каноническую raw-форму 'wc:hex64' (нижний регистр).
    Исключение ValueError, если адрес некорректен."""
    raw = (raw or "").strip()
    m = re.match(r"^(-?\d{1,3}):([0-9a-fA-F]{64})\Z", raw)
    if m:
        workchain = int(m.group(1))
        if workchain not in (0, -1):
            raise ValueError("unsupported TON workchain")
        return "%d:%s" % (workchain, m.group(2).lower())
    try:
        data = _b64.urlsafe_b64decode(raw.replace("+", "-").replace("/", "_") + "=" * (-len(raw) % 4))
    except ValueError:
        raise ValueError("invalid TON address")
    if len(data) != 36 or _crc16_xmodem(data[:34]) != int.from_bytes(data[34:], "big"):
        raise ValueError("invalid TON address")
    tag = data[0]
    if tag & 0x80:
        raise ValueError("TON testnet address is not allowed")
    if tag not in (0x11, 0x51):
        raise ValueError("invalid TON address flags")
    workchain = data[1] - 256 if data[1] > 127 else data[1]
    if workchain not in (0, -1):
        raise ValueError("unsupported TON workchain")
    return "%d:%s" % (workchain, data[2:34].hex())


def normalize_gift_ref(ref):
    ref = (ref or "").strip()
    if ref.startswith("https://"):
        ref = ref[len("https://"):]
    ref = ref.strip()
    try:
        return canonical_ton_address(ref)
    except ValueError:
        pass
    return ref[len("nft/"):] if ref.startswith("nft/") else ref


def decode_claim_base64(value, min_len, max_len):
    value = (value or "").strip()
    out = None
    for decoder, pad in ((_b64.b64decode, True), (_b64.b64decode, False), (_b64.urlsafe_b64decode, True),
                         (_b64.urlsafe_b64decode, False)):
        try:
            padded = value
            if not pad:
                if "=" in value:
                    continue
                padded = value + "=" * (-len(value) % 4)
            elif len(value) % 4:
                continue
            out = decoder(padded)
            break
        except (ValueError, TypeError):
            continue
    if out is None or len(out) < min_len or len(out) > max_len:
        raise ValueError("invalid base64")
    return out


