class MemoryClaimLimiter(object):
    """Скользящее окно в памяти (потокобезопасно): allow(key, limit, window) -> (allowed, retry_after_seconds)."""

    def __init__(self):
        self._lock = threading.Lock()
        self._hits = {}

    def allow(self, key, limit, window):
        now = time.time()
        with self._lock:
            hits = [t for t in self._hits.get(key, ()) if now - t < window]
            if len(hits) >= limit:
                self._hits[key] = hits
                return False, max(1, int(_math.ceil(hits[0] + window - now)))
            hits.append(now)
            self._hits[key] = hits
            return True, 0


