def _claim_decode_strict(value, spec):
    """Аналог json.Decoder.DisallowUnknownFields: неизвестные поля и неверные типы -> ClaimInvalid."""
    if not isinstance(value, dict):
        raise ClaimInvalid()
    out = {}
    for key, v in value.items():
        if key not in spec:
            raise ClaimInvalid()
        want = spec[key]
        if v is None:
            continue
        if isinstance(want, dict):
            out[key] = _claim_decode_strict(v, want)
        elif want is int:
            if not _is_int(v):
                raise ClaimInvalid()
            out[key] = v
        elif want == "int64str":
            if not isinstance(v, str) or not re.match(r"^-?\d{1,19}\Z", v) or not -(1 << 63) <= int(v) < (1 << 63):
                raise ClaimInvalid()
            out[key] = int(v)
        else:
            if not isinstance(v, str):
                raise ClaimInvalid()
            out[key] = v
    return out


def _claim_input_defaults(d):
    account, proof = d.get("account") or {}, d.get("proof") or {}
    dom = proof.get("domain") or {}
    return {"payload": d.get("payload", ""),
            "account": {"address": account.get("address", ""), "chain": account.get("chain", ""),
                        "publicKey": account.get("publicKey", ""), "walletStateInit": account.get("walletStateInit", "")},
            "proof": {"timestamp": proof.get("timestamp", 0),
                      "domain": {"lengthBytes": dom.get("lengthBytes", 0), "value": dom.get("value", "")},
                      "signature": proof.get("signature", ""), "payload": proof.get("payload", "")}}


def _render_claim_template(template, app_name, base_path, bot_handle):
    """Подстановка {{.AppName}}/{{.BasePath}}/{{.BotHandle}} с экранированием по контексту (HTML / JS-строка),
    как это делает html/template."""
    values = {"AppName": app_name, "BasePath": base_path, "BotHandle": bot_handle}

    def js_escape(text):
        table = {"\\": "\\\\", "'": "\\u0027", '"': "\\u0022", "<": "\\u003c", ">": "\\u003e", "&": "\\u0026",
                 "=": "\\u003d", "+": "\\u002b", "/": "\\/", "`": "\\u0060", "\n": "\\n", "\r": "\\r"}
        return "".join(table.get(c, c) for c in text)

    def repl(m):
        in_script = template.rfind("<script", 0, m.start()) > template.rfind("</script>", 0, m.start())
        value = values[m.group(1)]
        return js_escape(value) if in_script else _html.escape(value, quote=True)

    return re.sub(r"\{\{\.(AppName|BasePath|BotHandle)\}\}", repl, template)


