def main():
    import sys
    if "--extract-tdlib" in sys.argv:
        i = sys.argv.index("--extract-tdlib")
        extract_tdlib(sys.argv[i + 1] if len(sys.argv) > i + 1 else "tdlib_src")
        return
    if "--extract-generated" in sys.argv:
        i = sys.argv.index("--extract-generated")
        extract_generated(sys.argv[i + 1] if len(sys.argv) > i + 1 else "generated")
        return
    if "--extract-components" in sys.argv:
        i = sys.argv.index("--extract-components")
        extract_components(sys.argv[i + 1] if len(sys.argv) > i + 1 else "Components")
        return
    if "--extract-stars" in sys.argv:
        i = sys.argv.index("--extract-stars")
        extract_stars(sys.argv[i + 1] if len(sys.argv) > i + 1 else "Stars")
        return
    if "--extract-gifts" in sys.argv:
        i = sys.argv.index("--extract-gifts")
        extract_gifts(sys.argv[i + 1] if len(sys.argv) > i + 1 else "gifts_go_src")
        return
    if cli_verify():
        return
    srv = Server((HOST, PORT), Handler)
    print("Vexis запущен:  http://localhost:%d" % PORT)
    print("База данных:    %s" % DB_PATH)
    start_bot()
    threading.Thread(target=_auto_delete_loop, daemon=True).start()
    threading.Thread(target=_auction_loop, daemon=True).start()
    tunnel = start_tunnel()
    _start_keepalive()
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        print("\nОстановлено")
    finally:
        if tunnel:
            tunnel.terminate()


if __name__ == "__main__":
    main()

